"""Pure spatial oracle for bounded offline RGB replay qualification.

Expected image coordinates come from recorded world poses and camera intrinsics.
Observed bounds come from a diagnostic renderer instance mask, never from this
projection.  This module has no Kit dependency and is not a dataset validator.
"""

from __future__ import annotations

from dataclasses import dataclass
from math import hypot

import numpy as np


IMAGE_WIDTH = 640
IMAGE_HEIGHT = 480
CUBE_EDGE_M = 0.04
CENTER_TOLERANCE_PX = 24.0
MIN_BOX_IOU = 0.20
MIN_MASK_PIXELS = 12


@dataclass(frozen=True)
class Projection:
    bounds: tuple[float, float, float, float] | None
    center: tuple[float, float] | None
    visibility: str


def quaternion_rotation(wxyz: np.ndarray) -> np.ndarray:
    """World rotation matrix for the recorder's normalized wxyz quaternion."""
    q = np.asarray(wxyz, dtype=np.float64)
    if q.shape != (4,) or not np.isfinite(q).all():
        raise ValueError("orientation must be a finite wxyz quaternion")
    norm = np.linalg.norm(q)
    if norm < 1e-8:
        raise ValueError("orientation quaternion is zero")
    w, x, y, z = q / norm
    return np.array(
        [
            [1 - 2 * (y * y + z * z), 2 * (x * y - w * z), 2 * (x * z + w * y)],
            [2 * (x * y + w * z), 1 - 2 * (x * x + z * z), 2 * (y * z - w * x)],
            [2 * (x * z - w * y), 2 * (y * z + w * x), 1 - 2 * (x * x + y * y)],
        ],
        dtype=np.float64,
    )


def project_cube(
    position: np.ndarray,
    orientation: np.ndarray,
    camera_position: np.ndarray,
    camera_orientation: np.ndarray,
    focal_length_mm: float,
    horizontal_aperture_mm: float,
    vertical_aperture_mm: float,
    *,
    edge_m: float = CUBE_EDGE_M,
    width: int = IMAGE_WIDTH, height: int = IMAGE_HEIGHT,
) -> Projection:
    """Project eight native cube corners through a recorded USD camera pose.

    USD camera optical axis is local -Z, with local +Y upward.  A box crossing
    the near plane is indeterminate and must not produce a passing comparison.
    """
    if min(focal_length_mm, horizontal_aperture_mm, vertical_aperture_mm, edge_m) <= 0:
        raise ValueError("camera intrinsics and cube edge must be positive")
    half = edge_m / 2
    corners = np.array(
        [(x, y, z) for x in (-half, half) for y in (-half, half) for z in (-half, half)]
    )
    world = corners @ quaternion_rotation(orientation).T + np.asarray(position)
    local = (world - np.asarray(camera_position)) @ quaternion_rotation(camera_orientation)
    depth = -local[:, 2]
    if np.any(depth <= 0.02):
        return Projection(None, None, "near_plane_or_behind")
    u = width / 2 + width * focal_length_mm / horizontal_aperture_mm * local[:, 0] / depth
    v = height / 2 - height * focal_length_mm / vertical_aperture_mm * local[:, 1] / depth
    raw = (float(u.min()), float(v.min()), float(u.max()), float(v.max()))
    if raw[2] <= 0 or raw[0] >= width or raw[3] <= 0 or raw[1] >= height:
        return Projection(None, None, "out_of_frame")
    # A diagnostic mask is clipped to the render product; compare like bounds.
    bounds = (
        max(0.0, raw[0]), max(0.0, raw[1]),
        min(float(width), raw[2]), min(float(height), raw[3]),
    )
    center = ((bounds[0] + bounds[2]) / 2, (bounds[1] + bounds[3]) / 2)
    raw_center = ((raw[0] + raw[2]) / 2, (raw[1] + raw[3]) / 2)
    partial = not (0 <= raw_center[0] < width and 0 <= raw_center[1] < height)
    return Projection(bounds, center, "partial_out_of_frame" if partial else "in_frame")


def mask_bounds(mask: np.ndarray) -> tuple[float, float, float, float] | None:
    pixels = np.asarray(mask, dtype=bool)
    if pixels.shape not in ((480, 640), (600, 960)):
        raise ValueError("diagnostic mask must match legacy or native ZED resolution")
    yy, xx = np.nonzero(pixels)
    if len(xx) < MIN_MASK_PIXELS:
        return None
    return (float(xx.min()), float(yy.min()), float(xx.max() + 1), float(yy.max() + 1))


def box_iou(left: tuple[float, ...], right: tuple[float, ...]) -> float:
    x0, y0 = max(left[0], right[0]), max(left[1], right[1])
    x1, y1 = min(left[2], right[2]), min(left[3], right[3])
    intersection = max(0.0, x1 - x0) * max(0.0, y1 - y0)
    area_left = max(0.0, left[2] - left[0]) * max(0.0, left[3] - left[1])
    area_right = max(0.0, right[2] - right[0]) * max(0.0, right[3] - right[1])
    union = area_left + area_right - intersection
    return intersection / union if union > 0 else 0.0


def compare_static_relative(
    expected_dynamic: Projection,
    expected_static: Projection,
    observed_dynamic: tuple[float, float, float, float] | None,
    observed_static: tuple[float, float, float, float] | None,
) -> dict[str, float | bool | None]:
    """Compare a recorded dynamic witness against an independent world landmark."""
    if (
        expected_dynamic.center is None or expected_static.center is None
        or observed_dynamic is None or observed_static is None
    ):
        return {"pass": False, "relative_error_px": None}
    expected = np.subtract(expected_dynamic.center, expected_static.center)
    dynamic = ((observed_dynamic[0] + observed_dynamic[2]) / 2,
               (observed_dynamic[1] + observed_dynamic[3]) / 2)
    static = ((observed_static[0] + observed_static[2]) / 2,
              (observed_static[1] + observed_static[3]) / 2)
    error = float(np.linalg.norm(expected - np.subtract(dynamic, static)))
    return {"pass": error <= CENTER_TOLERANCE_PX, "relative_error_px": round(error, 3)}


def compare_geometry(
    expected: Projection,
    observed: tuple[float, float, float, float] | None,
) -> dict[str, float | bool | str | None]:
    """Return a fixed spatial verdict; no photometric or exact pixel criterion."""
    if expected.visibility == "near_plane_or_behind":
        return {"pass": False, "reason": "indeterminate_near_plane", "center_error_px": None, "iou": None}
    if expected.visibility == "out_of_frame":
        return {"pass": observed is None, "reason": "expected_out_of_frame", "center_error_px": None, "iou": None}
    if expected.visibility == "partial_out_of_frame" and observed is None:
        return {"pass": True, "reason": "partial_out_of_frame_unseen", "center_error_px": None, "iou": None}
    if expected.bounds is None or expected.center is None or observed is None:
        return {"pass": False, "reason": "missing_visible_witness", "center_error_px": None, "iou": None}
    center = ((observed[0] + observed[2]) / 2, (observed[1] + observed[3]) / 2)
    error = hypot(center[0] - expected.center[0], center[1] - expected.center[1])
    overlap = box_iou(expected.bounds, observed)
    return {
        "pass": error <= CENTER_TOLERANCE_PX and overlap >= MIN_BOX_IOU,
        "reason": "spatial_comparison",
        "center_error_px": round(error, 3),
        "iou": round(overlap, 4),
    }

"""Concrete Unix-socket EVAL boundary for the isolated PIPER-X Isaac process."""

from __future__ import annotations

from collections import OrderedDict
import hashlib
import json
import math
from pathlib import Path
import socket
import stat
from threading import Lock
from typing import Any, Mapping
import uuid

import numpy as np


PROTOCOL_REVISION = "piper_x_eval_boundary_v2"
HANDSHAKE_FIELDS = (
    "protocol_revision",
    "run_id",
    "D0_contract_fingerprint",
    "environment_revision",
    "PIPER_X_asset_model_revision",
    "task_id",
    "task_revision",
    "processor_revision",
    "n_episodes",
    "horizon",
)
REQUEST_FIELDS = {
    "reset": ("run_id", "request_id", "episode_id", "seed", "task_id", "task_revision"),
    "step": ("run_id", "request_id", "episode_id", "step_index", "canonical_D0_action_t"),
    "abort": ("run_id", "request_id", "episode_id", "reason"),
    "close": ("run_id", "request_id"),
}


class EvalProtocolError(ValueError):
    """A request is invalid and was not executed."""


class EvalInfrastructureError(RuntimeError):
    """Transport or endpoint identity failure, never task truncation."""


class AmbiguousEvalTimeout(EvalInfrastructureError):
    """The caller cannot know whether the request executed."""


def _jsonable(value: Any) -> Any:
    if isinstance(value, np.ndarray):
        return value.tolist()
    if isinstance(value, np.generic):
        return value.item()
    if isinstance(value, Mapping):
        return {str(key): _jsonable(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_jsonable(item) for item in value]
    if isinstance(value, float) and not math.isfinite(value):
        raise EvalProtocolError("non-finite floats are forbidden by the JSON codec")
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    raise EvalProtocolError(f"value is not JSON serializable: {type(value).__name__}")


def _canonical_fingerprint(operation: str, request: Mapping[str, Any]) -> str:
    payload = {
        key: _jsonable(value)
        for key, value in request.items()
        if key not in {"run_id", "request_id", "operation"}
    }
    encoded = json.dumps(
        {"operation": operation, "payload": payload},
        allow_nan=False,
        separators=(",", ":"),
        sort_keys=True,
    ).encode()
    return hashlib.sha256(encoded).hexdigest()


def bind_runtime_handshake(requested: Mapping[str, Any], runtime_identity: Mapping[str, Any]) -> dict[str, Any]:
    """Bind the caller's run request to facts collected by the loaded S1 runtime."""
    handshake = IsaacEvalEndpoint._validate_handshake(requested)
    identity_fields = set(HANDSHAKE_FIELDS) - {"protocol_revision", "run_id", "n_episodes"}
    if set(runtime_identity) != identity_fields:
        raise EvalInfrastructureError("runtime identity fields are incomplete")
    differences = [key for key in sorted(identity_fields) if handshake[key] != runtime_identity[key]]
    if differences:
        raise EvalProtocolError(f"manifest differs from loaded runtime: {differences}")
    return handshake


class IsaacEvalEndpoint:
    """Episode-sensitive request execution around one concrete Isaac environment."""

    def __init__(self, environment: Any, handshake: Mapping[str, Any]) -> None:
        self.environment = environment
        self.handshake = self._validate_handshake(handshake)
        self.endpoint_instance_id = uuid.uuid4().hex
        self._lock = Lock()
        self._cache: OrderedDict[
            tuple[str, str],
            tuple[str, dict[str, Any] | EvalProtocolError | EvalInfrastructureError],
        ] = OrderedDict()
        self._active_episode: str | int | None = None
        self._next_step_index = 0
        self._started_episodes: set[str | int] = set()
        self.closed = False
        # reset + every possible step + abort per episode + final close
        self._capacity = self.handshake["n_episodes"] * (self.handshake["horizon"] + 2) + 1

    @staticmethod
    def _validate_handshake(value: Mapping[str, Any]) -> dict[str, Any]:
        if set(value) != set(HANDSHAKE_FIELDS):
            raise EvalProtocolError("handshake fields do not match the protocol")
        result = {key: _jsonable(value[key]) for key in HANDSHAKE_FIELDS}
        if result["protocol_revision"] != PROTOCOL_REVISION:
            raise EvalProtocolError("unsupported protocol_revision")
        if not isinstance(result["run_id"], str) or not result["run_id"]:
            raise EvalProtocolError("run_id must be a non-empty string")
        for key in (
            "D0_contract_fingerprint",
            "environment_revision",
            "PIPER_X_asset_model_revision",
            "task_id",
            "task_revision",
            "processor_revision",
        ):
            if not isinstance(result[key], str) or not result[key]:
                raise EvalProtocolError(f"{key} must be a non-empty string")
        for key in ("n_episodes", "horizon"):
            if (
                isinstance(result[key], bool)
                or not isinstance(result[key], int)
                or result[key] <= 0
            ):
                raise EvalProtocolError(f"{key} must be a positive integer")
        return result

    def accept_handshake(self, request: Mapping[str, Any]) -> dict[str, Any]:
        candidate = {key: request.get(key) for key in HANDSHAKE_FIELDS}
        if (
            set(request) != {"operation", *HANDSHAKE_FIELDS}
            or request.get("operation") != "handshake"
        ):
            raise EvalProtocolError("invalid handshake envelope")
        if self._validate_handshake(candidate) != self.handshake:
            raise EvalProtocolError("handshake does not identify the active run")
        return {
            "operation": "handshake",
            "run_id": self.handshake["run_id"],
            "endpoint_instance_id": self.endpoint_instance_id,
            "accepted": True,
        }

    def handle(self, request: Mapping[str, Any]) -> dict[str, Any]:
        operation = request.get("operation")
        if operation == "handshake":
            return self.accept_handshake(request)
        if operation not in REQUEST_FIELDS:
            raise EvalProtocolError(f"unknown operation: {operation!r}")
        expected = {"operation", *REQUEST_FIELDS[operation]}
        if set(request) != expected:
            raise EvalProtocolError(
                f"{operation} fields mismatch: missing={sorted(expected - set(request))} "
                f"extra={sorted(set(request) - expected)}"
            )
        run_id = request["run_id"]
        request_id = request["request_id"]
        if run_id != self.handshake["run_id"]:
            raise EvalInfrastructureError("request belongs to an inactive run")
        if not isinstance(request_id, str) or not request_id:
            raise EvalProtocolError("request_id must be a non-empty string")
        fingerprint = _canonical_fingerprint(operation, request)
        key = (run_id, request_id)
        with self._lock:
            cached = self._cache.get(key)
            if cached is not None:
                if cached[0] != fingerprint:
                    raise EvalProtocolError(
                        "request_id was reused with a different operation or payload"
                    )
                if isinstance(cached[1], (EvalProtocolError, EvalInfrastructureError)):
                    raise type(cached[1])(str(cached[1]))
                return dict(cached[1])
            if self.closed:
                raise EvalInfrastructureError("run is already closed")
            if len(self._cache) >= self._capacity:
                raise EvalInfrastructureError("declared run request capacity exceeded")
            try:
                native_response = self._execute(operation, request)
            except (EvalProtocolError, EvalInfrastructureError) as exc:
                self._cache[key] = (fingerprint, exc)
                raise
            try:
                response = {"request_id": request_id, **_jsonable(native_response)}
            except EvalProtocolError as exc:
                failure = EvalInfrastructureError(f"invalid Isaac response: {exc}")
                self._cache[key] = (fingerprint, failure)
                raise failure from exc
            self._cache[key] = (fingerprint, response)
            return dict(response)

    def _execute(self, operation: str, request: Mapping[str, Any]) -> dict[str, Any]:
        if operation == "reset":
            return self._reset(request)
        if operation == "step":
            return self._step(request)
        if operation == "abort":
            return self._abort(request)
        if self._active_episode is not None:
            raise EvalProtocolError("close requires the active episode to finish or abort")
        self.closed = True
        return {"close_state": "closed"}

    def _reset(self, request: Mapping[str, Any]) -> dict[str, Any]:
        episode_id = request["episode_id"]
        if not isinstance(episode_id, str) or not episode_id:
            raise EvalProtocolError("episode_id must be a non-empty string")
        seed = request["seed"]
        if isinstance(seed, bool) or not isinstance(seed, int):
            raise EvalProtocolError("seed must be an integer")
        if self._active_episode is not None:
            raise EvalProtocolError("reset while another episode is active")
        if episode_id in self._started_episodes:
            raise EvalProtocolError("episode_id was already used with another request_id")
        if len(self._started_episodes) >= self.handshake["n_episodes"]:
            raise EvalProtocolError("declared n_episodes exceeded")
        if (
            request["task_id"] != self.handshake["task_id"]
            or request["task_revision"] != self.handshake["task_revision"]
        ):
            raise EvalProtocolError("reset task identity differs from handshake")
        try:
            observation = self.environment.reset(seed)
        except Exception as exc:
            raise EvalInfrastructureError(f"Isaac reset failed: {exc}") from exc
        self._active_episode = episode_id
        self._started_episodes.add(episode_id)
        self._next_step_index = 0
        return {"canonical_D0_obs_0": observation, "effective_seed": seed}

    def _step(self, request: Mapping[str, Any]) -> dict[str, Any]:
        if request["episode_id"] != self._active_episode:
            raise EvalProtocolError("step episode_id is not active")
        step_index = request["step_index"]
        if isinstance(step_index, bool) or not isinstance(step_index, int):
            raise EvalProtocolError("step_index must be an integer")
        if step_index != self._next_step_index:
            raise EvalProtocolError(
                f"step_index={request['step_index']} expected={self._next_step_index}"
            )
        if self._next_step_index >= self.handshake["horizon"]:
            raise EvalProtocolError("declared episode horizon exceeded")
        action = np.asarray(request["canonical_D0_action_t"], dtype=np.float64)
        if action.shape != (14,) or not np.isfinite(action).all():
            raise EvalProtocolError("canonical_D0_action_t must be a finite 14-vector")
        try:
            observation, reward, terminated, truncated, _native_info = self.environment.step(action)
        except Exception as exc:
            raise EvalInfrastructureError(f"Isaac step failed: {exc}") from exc
        success = bool(terminated)
        self._next_step_index += 1
        if terminated or truncated:
            self._active_episode = None
        reason = "success" if success else "time_limit" if truncated else None
        return {
            "canonical_D0_obs_t_plus_1": observation,
            "reward_t": float(reward),
            "terminated_t": bool(terminated),
            "truncated_t": bool(truncated),
            "success_t": success,
            "termination_reason": reason,
        }

    def _abort(self, request: Mapping[str, Any]) -> dict[str, Any]:
        if request["episode_id"] != self._active_episode:
            raise EvalProtocolError("abort episode_id is not active")
        if not isinstance(request["reason"], str) or not request["reason"]:
            raise EvalProtocolError("abort reason must be a non-empty string")
        self._active_episode = None
        return {"abort_state": "aborted"}


def _error_response(exc: Exception) -> dict[str, Any]:
    classification = (
        "protocol_error" if isinstance(exc, EvalProtocolError) else "infrastructure_failure"
    )
    return {"error": {"classification": classification, "message": str(exc)}}


def serve_unix_socket(endpoint: IsaacEvalEndpoint, socket_path: Path) -> None:
    """Serve one endpoint until a deduplicated close request succeeds."""

    if socket_path.exists():
        mode = socket_path.stat().st_mode
        if stat.S_ISSOCK(mode):
            raise EvalInfrastructureError(f"socket already exists: {socket_path}")
        raise EvalInfrastructureError(f"refusing to replace non-socket path: {socket_path}")
    socket_path.parent.mkdir(parents=True, exist_ok=True)
    server = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    try:
        server.bind(str(socket_path))
        server.listen(1)
        while not endpoint.closed:
            connection, _ = server.accept()
            stream = connection.makefile("rwb")
            try:
                for raw in stream:
                    try:
                        request = json.loads(raw)
                        if not isinstance(request, dict):
                            raise EvalProtocolError("request must be a JSON object")
                        response = endpoint.handle(request)
                    except (EvalProtocolError, EvalInfrastructureError, ValueError) as exc:
                        response = _error_response(exc)
                    try:
                        stream.write(json.dumps(response, allow_nan=False).encode() + b"\n")
                        stream.flush()
                    except BrokenPipeError:
                        break
                    if endpoint.closed:
                        break
            finally:
                try:
                    stream.close()
                except OSError:
                    pass
                connection.close()
    finally:
        server.close()
        if socket_path.exists() and stat.S_ISSOCK(socket_path.stat().st_mode):
            socket_path.unlink()


class UnixEvalClient:
    """Single-in-flight client with explicit, same-ID retry only."""

    def __init__(self, socket_path: Path, handshake: Mapping[str, Any], timeout_s: float) -> None:
        if not math.isfinite(timeout_s) or timeout_s <= 0:
            raise ValueError("timeout_s must be positive")
        self.socket_path = socket_path
        self.handshake = dict(handshake)
        self.timeout_s = timeout_s
        self.endpoint_instance_id: str | None = None
        self._socket: socket.socket | None = None
        self._stream: Any = None
        self._lock = Lock()

    def connect(self) -> None:
        self.disconnect()
        transport = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        transport.settimeout(self.timeout_s)
        try:
            transport.connect(str(self.socket_path))
            stream = transport.makefile("rwb")
            self._socket, self._stream = transport, stream
            response = self._exchange({"operation": "handshake", **self.handshake})
        except OSError as exc:
            transport.close()
            self._socket = self._stream = None
            raise EvalInfrastructureError(f"failed to connect to Isaac endpoint: {exc}") from exc
        except Exception:
            transport.close()
            self._socket = self._stream = None
            raise
        instance = response.get("endpoint_instance_id")
        if self.endpoint_instance_id is not None and instance != self.endpoint_instance_id:
            self.disconnect()
            raise EvalInfrastructureError("endpoint restarted; the active run is invalid")
        self.endpoint_instance_id = instance

    def disconnect(self) -> None:
        if self._stream is not None:
            try:
                self._stream.close()
            except OSError:
                pass
        if self._socket is not None:
            self._socket.close()
        self._stream = self._socket = None

    def request(self, operation: str, request_id: str, **payload: Any) -> dict[str, Any]:
        with self._lock:
            if self._stream is None:
                raise EvalInfrastructureError("client is not connected")
            request = {
                "operation": operation,
                "run_id": self.handshake["run_id"],
                "request_id": request_id,
                **payload,
            }
            try:
                response = self._exchange(request)
            except (TimeoutError, socket.timeout) as exc:
                self.disconnect()
                raise AmbiguousEvalTimeout(
                    "request timed out; do not retry automatically, reconnect and reuse request_id"
                ) from exc
            except OSError as exc:
                self.disconnect()
                raise EvalInfrastructureError(f"Isaac transport failed: {exc}") from exc
            if "error" in response:
                error = response["error"]
                exception = (
                    EvalProtocolError
                    if error["classification"] == "protocol_error"
                    else EvalInfrastructureError
                )
                raise exception(error["message"])
            if response.get("request_id") != request_id:
                raise EvalProtocolError("response request_id mismatch")
            return response

    def _exchange(self, request: Mapping[str, Any]) -> dict[str, Any]:
        assert self._stream is not None
        try:
            encoded = json.dumps(_jsonable(request), allow_nan=False).encode() + b"\n"
        except (TypeError, ValueError) as exc:
            raise EvalProtocolError(f"request is not valid JSON: {exc}") from exc
        self._stream.write(encoded)
        self._stream.flush()
        raw = self._stream.readline()
        if not raw:
            raise EvalInfrastructureError("endpoint closed before responding")
        try:
            response = json.loads(raw)
        except json.JSONDecodeError as exc:
            raise EvalProtocolError("endpoint returned invalid JSON") from exc
        if not isinstance(response, dict):
            raise EvalProtocolError("response must be a JSON object")
        if "error" in response:
            error = response["error"]
            exception = (
                EvalProtocolError
                if error["classification"] == "protocol_error"
                else EvalInfrastructureError
            )
            raise exception(error["message"])
        return response

"""Two persistent upstream panel placements sharing the existing RGB feeds."""

from copy import deepcopy
from typing import Any


class PreviewLayoutPanels:
    def __init__(self, manager: Any, presenter: Any, wall_layout: dict, isolation=None):
        from isaaclab_teleop.camera_feed import _layout_feed_cfgs, _panel_descriptor
        from isaaclab_teleop.isaac_teleop_cfg import XrCameraFeedLayoutCfg

        self.manager = manager
        self.isolation = isolation
        self.mode = "head_locked"
        self.toggle_count = 0
        self.pressed = False
        self.panels = {"head_locked": [feed.panel for feed in manager._feeds], "wall": []}
        layout = XrCameraFeedLayoutCfg(**{
            key: value for key, value in wall_layout.items() if key != "panel_width_m"
        })
        cfgs = [deepcopy(feed.cfg) for feed in manager._feeds]
        for cfg in cfgs:
            cfg.panel_width_m = float(wall_layout["panel_width_m"])
        sizes = [(int(feed.image.shape[1]), int(feed.image.shape[0])) for feed in manager._feeds]
        try:
            for cfg, (width, height) in zip(_layout_feed_cfgs(cfgs, sizes, layout), sizes, strict=True):
                panel = presenter.create_panel(_panel_descriptor(cfg, layout), width, height)
                self.panels["wall"].append(panel)
                self._hide(panel)
        except Exception:
            self.close_inactive()
            raise

    def _hide(self, panel):
        panel._container.hide()
        if self.isolation is not None:
            self.isolation.release_panel(panel)

    def consume_button(self, value: float) -> bool:
        pressed = bool(value > 0.5)
        changed = pressed and not self.pressed
        self.pressed = pressed
        if not changed:
            return False
        for feed in self.manager._feeds:
            self._hide(feed.panel)
        self.mode = "wall" if self.mode == "head_locked" else "head_locked"
        for feed, panel in zip(self.manager._feeds, self.panels[self.mode], strict=True):
            feed.panel = panel
        self.toggle_count += 1
        return True

    def close_inactive(self):
        # Normal feed-session teardown owns the active panels.
        inactive = "wall" if self.mode == "head_locked" else "head_locked"
        for panel in self.panels[inactive]:
            panel.close()
        self.panels[inactive].clear()

    def report(self):
        return {"mode": self.mode, "toggle_count": self.toggle_count,
                "order": [feed.cfg.camera_name for feed in self.manager._feeds],
                "persistent_panel_count": sum(map(len, self.panels.values()))}

"""Concrete S1 wrist/scene presentation using pinned NVIDIA SceneUI manager.

Two policy camera buffers retain their native batched Camera and RGB semantics.
The third, presentation-only scene camera is not a policy observation.
"""
from types import SimpleNamespace
import torch
from isaaclab.sensors import Camera, CameraCfg
from isaaclab_physx.renderers import IsaacRtxRendererCfg
from isaaclab_teleop.camera_feed import _XrCameraFeedManager
from isaaclab_teleop.camera_feed_kit_scene_ui import _KitSceneUiCameraFeedPresenter
from isaaclab_teleop import XrCameraFeedCfg, XrCameraFeedLayoutCfg
import isaaclab.sim as sim_utils
from isaac_preview_partitions import PreviewPartitions
from isaac_vr_runtime import _CpuStagedFeedPresenter


class _BatchedFeedManager(_XrCameraFeedManager):
    """Only adapt upstream's batch[0]/RGBA assumption at the presentation edge."""
    def _image_from_output(self, cfg, output):
        key = 'rgba' if 'rgba' in output else 'rgb'
        image = output[key].torch[1 if cfg.camera_name == 'right_wrist' else 0]
        if image.dtype != torch.uint8 or image.shape != (480, 640, 3 if key == 'rgb' else 4):
            raise RuntimeError(f'Unexpected policy camera buffer for {cfg.camera_name}')
        if image.shape[-1] == 3:
            image = torch.cat((image, torch.full_like(image[..., :1], 255)), dim=-1)
        return image


class _PanelLease:
    """Manager lifetime is shorter than the upstream UiContainer lifetime."""
    def __init__(self, panel, isolation):
        self.panel, self.isolation = panel, isolation

    @property
    def _container(self):
        return self.panel._container

    def upload(self, image):
        self.panel.upload(image)

    def close(self):
        if self.isolation:
            self.isolation.release_panel(self.panel)
        self._container.hide()


class _RetainedPresenter(_CpuStagedFeedPresenter):
    """Pinned UiContainer explicitly requires show/hide instead of churn.

    Fixed three descriptors only, no generic resource cache. Managers may be
    recreated; their SceneViews remain owned by S1Preview until final shutdown.
    """
    def __init__(self, upstream, isolation):
        super().__init__(upstream, isolation)
        self.panels = {}

    def create_panel(self, descriptor, width, height):
        key = (descriptor, width, height)
        if key not in self.panels:
            if len(self.panels) >= 3:
                raise RuntimeError('S1 preview layout changed; restart the scene')
            self.panels[key] = super().create_panel(descriptor, width, height)
        panel = self.panels[key]
        panel._container.show()
        if self._isolation:
            self._isolation.check_panel(panel)
        return _PanelLease(panel, self._isolation)

    def finish(self):
        for panel in self.panels.values():
            panel.close()
        self.panels.clear()


class S1Preview:
    """Lifecycle composition, no camera/render/IK implementation replacement."""
    def __init__(self, env, *, isolation=True, validation_stamp=None):
        self.env = env
        self.isolation = PreviewPartitions(env.sim.stage) if isolation else None
        self.validation_stamp = validation_stamp
        self.scene_camera = self.make_scene_camera('/World/S1PreviewSceneCamera')
        self.manager = None
        self.presenter = _RetainedPresenter(_KitSceneUiCameraFeedPresenter(), self.isolation)
        if self.validation_stamp:
            stage_upload = self.presenter.stage_upload_image
            def stamped(image, upload):
                stage_upload(image, upload)
                self.validation_stamp(upload)
            self.presenter.stage_upload_image = stamped  # type: ignore[method-assign]
        self.validation_callback = None
        self.scene_paths = ['/World/S1PreviewSceneCamera0/Camera', '/World/S1PreviewSceneCamera1/Camera']
        self.paths = list(env.camera_prim_paths) + self.scene_paths[:1]
        if self.isolation:
            self.isolation.bind_sensors((), concrete_paths=list(env.camera_prim_paths) + self.scene_paths)
        # Public scene reset initializes the additional upstream Camera before bind.
        env.sim.reset()
        env.reset(0)
        self.scene_camera.set_world_poses_from_view(
            torch.tensor([[1.5, -1.5, 1.5]]*2, device=env.sim.device),
            torch.tensor([[0., 0., .4]]*2, device=env.sim.device))
        env.sim.render()
        self.scene_camera.update(env.sim.get_physics_dt(), force_recompute=True)
        self.open()

    @staticmethod
    def make_scene_camera(path):
        # Pinned RenderContext requires the canonical wrist batch size (two)
        # for every Camera. Second view is presentation-only, never a D0 role.
        stage = sim_utils.SimulationContext.instance().stage
        for index in range(2):
            stage.DefinePrim(f'{path}{index}', 'Xform')
        return Camera(CameraCfg(prim_path=path+'[01]/Camera', update_period=0., width=640, height=480,
            data_types=['rgba'], update_latest_camera_pose=True,
            renderer_cfg=IsaacRtxRendererCfg(enable_scene_partitioning=False),
            spawn=sim_utils.PinholeCameraCfg(focal_length=18., horizontal_aperture=20.955,
                                            clipping_range=(.02, 10.))))

    def open(self):
        if self.manager is not None:
            raise RuntimeError('Preview manager already open')
        cfgs = [XrCameraFeedCfg(camera_name=name, label=label, panel_width_m=.36,
                               max_update_hz=30.) for name, label in (
            ('left_wrist','LEFT WRIST'), ('right_wrist','RIGHT WRIST'), ('scene','SCENE'))]
        layout = XrCameraFeedLayoutCfg(mode='horizontal', placement='world' if self.validation_stamp else 'head_locked',
                                      world_position_m=(0., 0., 0.) if self.validation_stamp else None, distance_m=.75,
                                      center_offset_m=(0., -.2), panel_gap_m=.03)
        scene = SimpleNamespace(sensors={'left_wrist':self.env.camera, 'right_wrist':self.env.camera,
                                         'scene':self.scene_camera})
        self.manager = _BatchedFeedManager(SimpleNamespace(scene=scene), cfgs, layout, self.presenter)
        self.manager.refresh()
        self.assert_valid()

    def assert_valid(self):
        if self.isolation:
            self.isolation.assert_valid()

    def update(self, dt):
        self.scene_camera.update(dt, force_recompute=True)
        if self.manager is not None:
            self.manager.update()
        if self.validation_callback is not None:
            self.validation_callback()

    def refresh(self):
        self.scene_camera.reset()
        if self.manager is not None:
            self.manager.refresh()

    def close_panels(self):
        if self.manager is not None:
            self.manager.close()
            self.manager = None

    def close(self):
        self.close_panels()
        self.presenter.finish()

"""Opt-in single-GPU diagnostic: one CPU physics owner, passive Kit XR view.

Keeps the current environment, native recorder and upstream IK. The inherited
socket has one concrete worker and two commands; it is not a simulator service.
No physical hardware is commanded. No SDK files or production selection change.
"""

from __future__ import annotations

import hashlib
import json
from multiprocessing.connection import Connection
import os
from pathlib import Path
import socket
import subprocess
import time

import numpy as np

from isaac_vr_standalone_ik import piper_ik_state
from isaac_vr_standalone_view import PassiveKitView, SourceClock


class StandaloneState:
    """Own source snapshots and scoped instance overrides, with explicit restore."""

    def __init__(self, env, output, *, python, timeout=60):
        self.env, self.output = env, Path(output)
        self.python, self.timeout = str(python), float(timeout)
        self.output.mkdir(parents=True, exist_ok=False)
        self.clock = SourceClock(
            env.sim,
            epoch=int(env.camera.reset_epoch),
            physics_step=int(env.sim.get_physics_step_count()),
        )
        self.offset = self.clock.physics_step
        self.conn = self.proc = self.log = None
        self.snapshot = self.resolver = self.view = None
        self.targets = None
        self.seq = -1
        self.failed = False
        self.closed = False
        self.saved = {}
        self.native_state_step = env._state_physics_step
        self.timings = []
        self.receipt = dict(
            schema="single_gpu_source_owner_v1",
            physical=False,
            dataset_admissible=False,
            controls=0,
            native_physics_frozen=False,
        )

    def pose_batch(self, paths):
        owner = self

        class Batch:
            def get_world_poses(self):
                if owner.failed:
                    raise RuntimeError("external physics owner failed closed")
                owner.clock.assert_native_frozen()
                if owner.snapshot is None:
                    raise RuntimeError("external snapshot is not ready")
                poses = owner.resolver.poses(paths, owner.snapshot["rigid_body_world_pose"])
                return poses[:, :3], poses[:, 3:]

        return Batch()

    def sample_time(self):
        return self.clock.sample()

    def _override(self, name, value):
        self.saved[name] = (name in vars(self.env), vars(self.env).get(name))
        setattr(self.env, name, value)

    def _receive(self):
        if not self.conn.poll(self.timeout):
            raise RuntimeError(f"physics reply timeout: worker={self.proc.poll()}")
        reply = self.conn.recv()
        if reply.get("op") == "error":
            raise RuntimeError(f"physics worker failed: {reply}")
        return reply

    def start(self, snapshot):
        from isaac_vr_standalone_scene import build_seed, SnapshotPoses
        from isaacsim.core.simulation_manager import SimulationManager

        seed = build_seed(self.env, Path(snapshot), self.output)
        self.seed = seed
        self.resolver = SnapshotPoses(Path(snapshot), seed["rigid_body_paths"])
        seed_path = self.output / "seed.json"
        seed_path.write_text(json.dumps(seed, indent=2) + "\n")
        parent, child = socket.socketpair()
        self.conn = Connection(parent.detach())
        self.log = (self.output / "worker.log").open("wb")
        worker = Path(__file__).with_name("isaac_vr_standalone_worker.py")
        self.receipt.update(
            worker_sha256=hashlib.sha256(worker.read_bytes()).hexdigest(),
            seed_sha256=hashlib.sha256(seed_path.read_bytes()).hexdigest(),
        )
        try:
            self.proc = subprocess.Popen(
                [
                    self.python,
                    str(worker),
                    "--fd",
                    str(child.fileno()),
                    "--seed",
                    str(seed_path),
                    "--receipt",
                    str(self.output / "worker.json"),
                ],
                pass_fds=(child.fileno(),),
                stdout=self.log,
                stderr=self.log,
                env={k: v for k, v in os.environ.items() if k not in ("PYTHONPATH", "PYTHONHOME")},
            )
        finally:
            child.close()
        ready = self._receive()
        if ready.get("op") != "ready":
            raise RuntimeError(f"invalid physics startup: {ready}")
        self.properties = ready["dof_properties"]
        self._accept(ready["snapshot"], initial=True)
        self.receipt["initial_parity"] = self._initial_parity()
        paths = list(seed["rigid_body_paths"])
        paths += ["/World/LeftPiper", "/World/RightPiper"]
        paths += list(self.env.camera.camera_prim_paths.values())
        self.view = PassiveKitView(paths, native_counter=SimulationManager.get_num_physics_steps)
        self.view.update(
            self.resolver.poses(paths, self.snapshot["rigid_body_world_pose"]), verify_readback=True
        )
        self.clock.assert_native_frozen()
        self.targets = np.asarray(
            seed["initial"].get("position_target", seed["initial"]["q"]), np.float32
        ).copy()
        self._override("standalone_state", self)
        self._override("_apply", self.apply)
        self._override("_advance", self.advance)
        self._override("capture_measured_state", self.capture_measured_state)
        # Resetting the original Kit engine would silently fork the source clock.
        self._override("_reset_native", self.reject_reset)
        self.receipt["native_physics_frozen"] = True

    def _accept(self, snapshot, *, initial=False):
        expected = -1 if initial else self.seq + 1
        if snapshot["seq"] != expected or snapshot["physics_steps"] != 4 * (expected + 1):
            raise RuntimeError("nonconsecutive completed native snapshot")
        if not snapshot["fixed_base"]:
            raise RuntimeError("external articulation is not fixed base")
        for key, value in list(snapshot.items()):
            if isinstance(value, np.ndarray):
                if not np.isfinite(value).all():
                    raise RuntimeError(f"nonfinite source snapshot: {key}")
                snapshot[key] = value.copy()
                snapshot[key].setflags(write=False)
        if np.max(np.abs(snapshot["mimic_residual"])) > 2e-4:
            raise RuntimeError("imported native mimic constraints diverged")
        ik = piper_ik_state(
            q=snapshot["q"],
            link_poses_xyzw=snapshot["rigid_body_world_pose"][:24].reshape(2, 12, 7),
            com_poses_xyzw=snapshot["articulation_body_com_local_pose"],
            jacobian_com=snapshot["jacobian"],
            limits=self.properties["limits"],
            body_names=self.seed["body_names"],
            dof_names=self.seed["dof_names"],
            fixed_base=True,
        )
        self.snapshot, self.seq, self._ik = snapshot, expected, ik

    def _initial_parity(self):
        initial = self.seed["initial"]
        errors = {}
        for key in ("q", "dq", "root_pose", "rigid_body_world_pose"):
            if key in initial:
                errors[key] = float(
                    np.max(np.abs(self.snapshot[key] - np.asarray(initial[key], np.float32)))
                )
                if errors[key] > 3e-5:
                    raise RuntimeError(f"initial Kit/native state mismatch: {key}={errors[key]}")
        for arm, (robot, wrist_id, ids) in enumerate(
            zip(self.env.robots, self.env.wrist_ids, self.env.joint_ids, strict=True)
        ):
            row = wrist_id - 1 if robot.is_fixed_base else wrist_id
            cols = [i + robot.num_base_dofs for i in ids[:6]]
            reference = robot.data.body_link_jacobian_w.torch[:, row, :, cols].cpu().numpy()[0]
            error = float(np.max(np.abs(reference - self._ik["jacobian"][arm])))
            errors[f"jacobian_{arm}"] = error
            if error > 2e-4:
                raise RuntimeError(f"initial Kit/native TCP Jacobian mismatch: {error}")
        return errors

    def capture_measured_state(self):
        from isaac_s1_runtime import native_state_to_d0

        if self.failed:
            raise RuntimeError("external physics owner failed closed")
        self.clock.assert_native_frozen()
        q = self.snapshot["q"]
        native = [q[i, ids] for i, ids in enumerate(self.env.joint_ids)]
        return self.clock.physics_step, tuple(float(v) for v in native_state_to_d0(*native))

    def ik_state(self, arm):
        import torch

        if self.failed:
            raise RuntimeError("external physics owner failed closed")
        self.clock.assert_native_frozen()
        return {
            k: torch.as_tensor(v[arm].copy(), dtype=torch.float32, device=self.env.sim.device)
            if k == "limits"
            else torch.as_tensor(
                v[arm : arm + 1].copy(), dtype=torch.float32, device=self.env.sim.device
            )
            for k, v in self._ik.items()
        }

    def apply(self, targets):
        if self.failed:
            raise RuntimeError("external physics owner failed closed")
        self.clock.assert_native_frozen()
        result = self.targets.copy()
        for arm, (ids, values) in enumerate(
            zip(self.env.actuated_joint_ids, (targets.left_rad_m, targets.right_rad_m), strict=True)
        ):
            result[arm, ids] = self.env._with_mimics(values)
        if result.shape != (2, 9) or not np.isfinite(result).all():
            raise ValueError("invalid native command")
        self.targets = result

    def advance(self, repeat):
        if self.failed:
            raise RuntimeError("external physics owner failed closed")
        try:
            self._advance_completed(repeat)
        except BaseException:
            self.failed = True
            raise

    def _advance_completed(self, repeat):
        if repeat != 4:
            raise ValueError("standalone source requires one four-substep control boundary")
        self.clock.assert_native_frozen()
        started = time.perf_counter_ns()
        self.conn.send(dict(op="step", seq=self.seq + 1, native_targets=self.targets))
        reply = self._receive()
        if reply.get("op") != "captured" or not np.array_equal(
            reply["native_targets"], self.targets
        ):
            raise RuntimeError("native completion/command acknowledgment differs")
        self._accept(reply["snapshot"])
        self.clock.commit(
            epoch=self.clock.epoch,
            physics_step=self.offset + self.snapshot["physics_steps"],
            captured_wall_time=time.time(),
        )
        self.env._state_physics_step = self.clock.physics_step
        captured = time.perf_counter_ns()
        poses = self.resolver.poses(self.view.paths, self.snapshot["rigid_body_world_pose"])
        self.view.update(poses, verify_readback=self.seq < 2 or self.seq % 120 == 0)
        self.clock.assert_native_frozen()
        self.timings.append(
            dict(
                seq=self.seq,
                physics_ipc_ns=captured - started,
                passive_view_ns=time.perf_counter_ns() - captured,
                **reply["timings_ns"],
            )
        )
        self.receipt["controls"] += 1

    def reject_reset(self, seed):
        raise RuntimeError(
            "experimental standalone reset requires closing and recreating this source owner"
        )

    def close(self):
        if self.closed:
            return
        self.closed = True
        errors = []
        if self.proc and self.proc.poll() is None:
            try:
                self.conn.send(dict(op="close"))
                self.receipt["tail"] = self._receive()
                if self.receipt["tail"] != dict(
                    op="closed", controls=self.seq + 1, physics_steps=4 * (self.seq + 1)
                ):
                    raise RuntimeError("physics terminal acknowledgment differs")
                if self.proc.wait(timeout=10) != 0:
                    raise RuntimeError("physics worker exited unsuccessfully")
            except Exception as exc:
                errors.append(repr(exc))
                if self.proc.poll() is None:
                    self.proc.terminate()
                try:
                    self.proc.wait(timeout=10)
                except subprocess.TimeoutExpired:
                    self.proc.kill()
                    self.proc.wait()
        for name, (existed, previous) in self.saved.items():
            if existed:
                setattr(self.env, name, previous)
            else:
                vars(self.env).pop(name, None)
        self.env._state_physics_step = self.native_state_step
        if self.proc and self.proc.poll() not in (None, 0):
            errors.append(f"physics worker exit status {self.proc.poll()}")
        if self.conn:
            self.conn.close()
        if self.log:
            self.log.close()
        try:
            self.clock.close()
        except Exception as exc:
            errors.append(repr(exc))
        worker_receipt = self.output / "worker.json"
        if worker_receipt.exists():
            native_errors = json.loads(worker_receipt.read_text()).get("cleanup_errors", [])
            errors.extend(native_errors)
            self.receipt["worker_cleanup_errors"] = native_errors
        self.receipt.update(cleanup_errors=errors, timing_rows=len(self.timings))
        (self.output / "owner.json").write_text(json.dumps(self.receipt, indent=2) + "\n")
        (self.output / "timings.json").write_text(json.dumps(self.timings, indent=2) + "\n")
        if errors:
            raise RuntimeError(f"standalone cleanup failed: {errors}")

