    )
)
PHYSICS_DT = 1.0 / 120.0
CAMERA_PERIOD = 1.0 / 30.0


def _tensor(value) -> torch.Tensor:
    return value if isinstance(value, torch.Tensor) else value.torch


def _cpu(value) -> np.ndarray:
    return _tensor(value).detach().cpu().numpy()


class _CpuRgbaPanel:
    """Use Kit's raw CPU buffer upload while upstream owns the panel lifetime."""

    def __init__(self, upstream_panel: Any, isolation=None) -> None:
        self._upstream = upstream_panel
        self._isolation = isolation
        self._closed = False
        self._retained_image: torch.Tensor | None = None
        # An isolated signature avoids changing ctypes.pythonapi's shared
        # PyCapsule_New binding, which other Kit extensions also use.
        capsule_address = ctypes.cast(ctypes.pythonapi.PyCapsule_New, ctypes.c_void_p).value
        assert capsule_address is not None
        self._capsule_new = ctypes.PYFUNCTYPE(
            ctypes.py_object, ctypes.c_void_p, ctypes.c_char_p, ctypes.c_void_p
        )(capsule_address)

    @property
    def _component(self):
        return self._upstream._component

    @property
    def _container(self):
        return self._upstream._container

    def upload(self, image: torch.Tensor) -> None:
        if self._closed:
            return
        if image.device.type != "cpu" or image.dtype != torch.uint8:
            raise TypeError("demo panel requires CPU uint8 RGBA")
        if image.ndim != 3 or image.shape[-1] != 4 or not image.is_contiguous():
            raise ValueError("demo panel requires contiguous HWC RGBA")
        if image.shape[0] == 0 or image.shape[1] == 0:
            raise ValueError("demo panel image dimensions must be positive")
        from omni.gpu_foundation_factory import TextureFormat  # type: ignore[import-not-found]
        from omni.ui.scene import Widget  # type: ignore[import-not-found]

        self._retained_image = image
        capsule = self._capsule_new(image.data_ptr(), None, None)
        self._upstream._provider.set_raw_bytes_data(
            capsule, [int(image.shape[1]), int(image.shape[0])], TextureFormat.RGBA8_UNORM
        )
        widget = self._component.scene_widget
        if widget is not None:
            widget.update_policy = Widget.UpdatePolicy.ON_DEMAND
            widget.invalidate()

    def close(self) -> None:
        if not self._closed:
            if self._isolation is not None:
                self._isolation.release_panel(self._upstream)
            self._upstream.close()
            self._retained_image = None
            self._closed = True


class _CameraFeedFrameDiagnostics:
    """Persist bounded source/upload samples without changing feed ownership."""

    _SCHEDULE = frozenset((1, 30, 120, 300, 600, 1200))

    def __init__(self, output_dir: Path | None, *, max_per_feed: int = 12) -> None:
        self._output_dir = output_dir
        self._max_per_feed = max_per_feed
        self._counts: dict[str, int] = {}
        self._records: list[dict[str, Any]] = []

    @staticmethod
    def _rgba_bytes(image: torch.Tensor) -> tuple[torch.Tensor, bytes]:
        cpu = image.detach().to(device="cpu").contiguous()
        return cpu, cpu.numpy().tobytes()

    @staticmethod
    def _write_ppm(path: Path, image: torch.Tensor) -> None:
        height, width = int(image.shape[0]), int(image.shape[1])
        rgb = image[..., :3].contiguous().numpy().tobytes()
        path.write_bytes(f"P6\n{width} {height}\n255\n".encode("ascii") + rgb)

    def capture(self, feed: Any, publication: int, reason: str) -> None:
        if self._output_dir is None:
            return
        if publication not in self._SCHEDULE and reason == "scheduled":
            return
        name = feed.cfg.camera_name
        if self._counts.get(name, 0) >= self._max_per_feed:
            return
        self._counts[name] = self._counts.get(name, 0) + 1
        self._output_dir.mkdir(parents=True, exist_ok=True)
        source, source_bytes = self._rgba_bytes(feed.image)
        upload, upload_bytes = self._rgba_bytes(feed.upload_image)
        stem = f"{publication:04d}-{feed.cfg.camera_name}-{reason}"
        source_path = self._output_dir / f"{stem}-source.ppm"
        upload_path = self._output_dir / f"{stem}-upload.ppm"
        self._write_ppm(source_path, source)
        self._write_ppm(upload_path, upload)
        self._records.append(
            {
                "camera": feed.cfg.camera_name,
                "publication": publication,
                "reason": reason,
                "source": source_path.name,
                "source_rgba_sha256": hashlib.sha256(source_bytes).hexdigest(),
                "upload": upload_path.name,
                "upload_rgba_sha256": hashlib.sha256(upload_bytes).hexdigest(),
                "source_upload_identical": source_bytes == upload_bytes,
                "shape": list(source.shape),
            }
        )
        manifest = self._output_dir / "manifest.json"
        pending = manifest.with_suffix(".json.tmp")
        pending.write_text(json.dumps(self._records, indent=2, sort_keys=True) + "\n")
        pending.replace(manifest)


class _FreshVisibleFeedUpdates:
    """Filter preview callbacks before upstream acquisition, staging and upload.

    Candidate B has no public callback predicate. Its existing _on_frame calls
    manager.update dynamically; only that scheduling boundary is adapted.
    Upstream _publish_feed and refresh still own cameras and image lifetime.
    """

    def __init__(
        self,
        manager: Any,
        is_visible: Callable[[], bool],
        diagnostics: _CameraFeedFrameDiagnostics | None = None,
    ) -> None:
        self._manager = manager
        self._is_visible = is_visible
        self._diagnostics = diagnostics
        self._last_frames: dict[str, tuple[int, int]] = {}
        self._publications: dict[str, int] = {}
        self._snapshot_reason: str | None = None
        self._snapshot_remaining: set[str] = set()
        self.counters = dict(
            callbacks=0,
            hidden_callbacks=0,
            duplicate_frames=0,
            throttled_frames=0,
            published_frames=0,
        )

    def invalidate(self) -> None:
        self._last_frames.clear()

    def request_snapshot(self, reason: str) -> None:
        self._snapshot_reason = reason
        self._snapshot_remaining = {feed.cfg.camera_name for feed in self._manager._feeds}

    def update(self) -> None:
        self.counters["callbacks"] += 1
        if not self._is_visible():
            self.counters["hidden_callbacks"] += 1
            return
        now = time.monotonic()
        snapshot_reason = self._snapshot_reason
        for feed in self._manager._feeds:
            name = feed.cfg.camera_name
            frame = (id(feed.camera), int(_tensor(feed.camera.frame).reshape(-1)[0].item()))
            if self._last_frames.get(name) == frame:
                self.counters["duplicate_frames"] += 1
                continue
            if now < feed.next_update_time:
                self.counters["throttled_frames"] += 1
                continue
            self._manager._publish_feed(feed)
            publication = self._publications.get(name, 0) + 1
            self._publications[name] = publication
            capture_reason = snapshot_reason if name in self._snapshot_remaining else "scheduled"
            if self._diagnostics is not None:
                self._diagnostics.capture(
                    feed,
                    publication,
                    capture_reason or "scheduled",
                )
            self._snapshot_remaining.discard(name)
            period = 0.0 if feed.cfg.max_update_hz == 0.0 else 1.0 / feed.cfg.max_update_hz
            feed.next_update_time = now + period
            self._last_frames[name] = frame
            self.counters["published_frames"] += 1
        if snapshot_reason is not None and not self._snapshot_remaining:
            self._snapshot_reason = None


class _CpuStagedFeedPresenter:
    """Select upstream SceneUI's CPU provider path for CloudXR compatibility.

    The pinned presenter remains responsible for the feed source, panels,
    SceneUI lifecycle, and frame subscription. This adapter only stages its
    unchanged RGBA tensor to a reusable CPU buffer before the upstream panel
    uploads it through ``ByteImageProvider``'s raw buffer API.
    """

    def __init__(self, upstream_presenter: Any, isolation=None) -> None:
        self._upstream = upstream_presenter
        self._isolation = isolation

    def create_image_source(self, camera_name: str, camera: Any, cfg: Any = None) -> Any:
        del camera_name, camera, cfg
        # Reuse the sensor cache for presentation. This is a buffer/lifecycle
        # choice, not an anti-recursion boundary; RTX partitions own isolation.
        return None

    def create_panel(self, descriptor: Any, width: int, height: int) -> Any:
        panel = self._upstream.create_panel(descriptor, width, height)
        try:
            # WidgetComponent's layout scale and texture supersampling differ.
            # Candidate B uses meters for UI layout, so the 22-pixel label and
            # 1-pixel border overflow a 0.36-unit panel. Keep its physical size
            # and placement, but lay out children at camera pixel resolution.
            if self._isolation is not None:
                self._isolation.check_panel(panel)
            component = panel._component
            component.resolution_scale = 1.0
            component.unit_to_pixel_scale = float(width) / component.width
        except Exception:
            panel.close()
            raise
        return _CpuRgbaPanel(panel, self._isolation)

    def subscribe_to_frame_updates(self, callback: Callable[[Any], None]) -> Any:
        return self._upstream.subscribe_to_frame_updates(callback)

    @staticmethod
    def prepare_upload_image(
        camera_name: str,
        image: torch.Tensor,
        previous_source: torch.Tensor | None = None,
        previous_upload: torch.Tensor | None = None,
    ) -> torch.Tensor:
        del camera_name, previous_source
        if image.device.type == "cpu":
            return image
        if (
            previous_upload is not None
            and previous_upload.device.type == "cpu"
            and tuple(previous_upload.shape) == tuple(image.shape)
            and previous_upload.dtype == image.dtype
        ):
            return previous_upload
        return torch.empty(tuple(image.shape), dtype=image.dtype, device="cpu")

    @staticmethod
    def stage_upload_image(image: torch.Tensor, upload_image: torch.Tensor) -> None:
        if upload_image is not image:
            upload_image.copy_(image, non_blocking=False)


class _BimanualCameraData:
    def __init__(self, cameras: tuple[Camera, Camera]) -> None:
        self._cameras = cameras

    @property
    def output(self) -> dict[str, torch.Tensor]:
        return {
            "rgb": torch.cat(
                tuple(_tensor(camera.data.output["rgba"])[..., :3] for camera in self._cameras),
                dim=0,
            )
        }

    @property
    def pos_w(self) -> torch.Tensor:
        return torch.cat(tuple(_tensor(camera.data.pos_w) for camera in self._cameras), dim=0)

    @property
    def quat_w_world(self) -> torch.Tensor:
        return torch.cat(
            tuple(_tensor(camera.data.quat_w_world) for camera in self._cameras), dim=0
        )


def _scene_rgb(camera):
    output = camera.data.output
    return _cpu(output["rgba" if "rgba" in output else "rgb"])[0, ..., :3]


class VRCameraRig:
    """Three canonical cameras with an explicit control-boundary capture owner."""

    def __init__(
        self, wrists: tuple[Camera, Camera] | tuple[CameraCfg, CameraCfg],
        scene: Camera | CameraCfg, *, live_rgb_enabled: bool = True,
    ) -> None:
        self.wrists = wrists
        self.scene_camera = scene
        self.preview_isolation: Any = None
        self.data = _BimanualCameraData(wrists)
        self.num_instances = 2
        self._elapsed = 0.0
        self.reset_epoch = 0
        self.capture: ThreeCameraCapture | None = None
        self.live_rgb_enabled = live_rgb_enabled

    @property
    def camera_prim_paths(self) -> dict[str, str]:
        return {
            role: getattr(camera, "cfg", camera).prim_path
            for role, camera in zip(
                ("left_wrist", "right_wrist", "scene"),
                (*self.wrists, self.scene_camera), strict=True,
            )
        }

    @property
    def capture_cycles_total(self) -> int:
        return self.capture.successful_capture_cycle if self.capture else 0

    @property
    def frame(self) -> torch.Tensor:
        return torch.cat(tuple(_tensor(camera.frame).reshape(-1) for camera in self.wrists))

    def reset(self) -> None:
        self.reset_epoch += 1
        if self.capture:
            self.capture.invalidate()
        if self.live_rgb_enabled:
            for camera in (*self.wrists, self.scene_camera):
                camera.reset()
        self._elapsed = 0.0

    def update(self, dt: float, *, force_recompute: bool = False) -> None:
        # Physics advances independently; only capture_boundary extracts pixels.
        if not self.live_rgb_enabled:
            return
        self._elapsed += dt
        if self.capture:
            self.capture.invalidate()

    def producer_boundary(self, env) -> ProducerBoundary:
        # Pinned Kit advertises pumps_app_update even when HEADLESS skips it.
        # A counter without a completed pump cannot attest fresh RTX pixels.
        pumps = [v for v in env.sim.visualizers if v.pumps_app_update()]
        if not pumps or not all(getattr(v, "_app_pumped_this_step", False) for v in pumps):
            raise RuntimeError(
                "No completed Kit RTX pump for this boundary; HEADLESS Kit is unsupported"
            )
        return ProducerBoundary(
            self.reset_epoch, env.sim.get_physics_step_count(), env.sim.render_generation
        )

    def capture_boundary(self, env) -> None:
        if not self.live_rgb_enabled:
            return
        if self.capture is None:
            self.capture = ThreeCameraCapture(
                dict(
                    zip(("left_wrist", "right_wrist", "scene"), (*self.wrists, self.scene_camera))
                ),
                lambda: self.producer_boundary(env),
                env.capture_measured_state,
            )
        self.capture.capture(self._elapsed, eligible=env.vr_runtime._validation_complete)
        self._elapsed = 0.0


class VRRuntime:
    """Own VR scene reset, validation, and upstream PiP binding for every mode."""

    def __init__(
        self,
        *,
        config: dict[str, Any],
        profile: str,
        camera_rig: VRCameraRig,
        camera_cfgs: tuple[CameraCfg, CameraCfg],
        dynamic_assets: list[Any],
        contact_sensors: dict[str, list[ContactSensor]],
        imported_prims: dict[str, str],
        hud_on_start: bool,
        diagnostic: bool = False,
    ) -> None:
        from isaaclab_teleop.camera_feed import XrCameraFeedSession  # type: ignore[import-not-found]
        from isaaclab_teleop.isaac_teleop_cfg import (  # type: ignore[import-not-found]
            XrCameraFeedCfg,
            XrCameraFeedLayoutCfg,
        )

        self.diagnostic = diagnostic
        self.config = config
        self.profile = profile
        self.camera_rig = camera_rig
        self.preview_isolation = getattr(camera_rig, "preview_isolation", None)
        self.preview_scene = bool(config["vr_camera_feeds"].get("include_scene_camera", False))
        self.dynamic_assets = dynamic_assets
        self.contact_sensors = contact_sensors
        self.imported_prims = imported_prims
        self.hud_on_start = hud_on_start
        self.display_control = str(config["vr_camera_feeds"]["toggle_control"])
        self.backdrop_control = str(config["scene"]["backdrop"]["toggle_control"])
        self.recenter_control = str(config["xr_presentation"]["recenter"]["toggle_control"])
        self.recenter_view_prim_path = str(config["xr_presentation"]["recenter"]["view_prim_path"])
        self.layout_control = str(config["vr_camera_feeds"]["layout_toggle_control"])
        self.pipeline_action_dim = 26 if camera_rig.live_rgb_enabled else 25
        self._preview_layouts = None
        self._preview_layout_report = {}
        self.validation: dict[str, Any] = {}
        self._env = None
        self._display_visible = False
        self._feed_bound = False
        self._feed_bound_ever = False
        self._feed_updates: _FreshVisibleFeedUpdates | None = None
        self._feed_update_report: dict[str, int] = {}
        diagnostic_root = os.environ.get("ROBOSYN_VR_CAMERA_DIAGNOSTICS_DIR")
        self._camera_diagnostics = (
            _CameraFeedFrameDiagnostics(
                Path(diagnostic_root),
                max_per_feed=int(config["diagnostics"]["camera_capture_limit_per_feed"]),
            )
            if diagnostic and diagnostic_root is not None
            else None
        )
        self._display_button_pressed = False
        self._display_toggle_count = 0
        self._backdrop_visible = True
        self._backdrop_button_pressed = False
        self._backdrop_toggle_count = 0
        self._recenter_button_pressed = False
        self._recenter_request_count = 0
        self._recenter_scheduled_count = 0
        self._runtime_frames: dict[str, int] = {}
        self._runtime_capture_cycles = 0
        self._validation_complete = False
        layout = config["vr_camera_feeds"]["layout"]
        feed_cfgs = [
            XrCameraFeedCfg(
                camera_name=name,
                panel_width_m=float(layout["panel_width_m"]),
                max_update_hz=float(layout["max_update_hz"]),
                label=label,
            )
            for name, label in (
                (name, {"left_wrist": "LEFT WRIST", "demo_scene": "SCENE",
                        "right_wrist": "RIGHT WRIST"}[name])
                for name in config["vr_camera_feeds"]["order"]
                if name != "demo_scene" or self.preview_scene
            )
        ]
        layout_cfg = XrCameraFeedLayoutCfg(
            mode=str(layout["mode"]),
            placement=str(layout["placement"]),
            center_offset_m=tuple(layout["center_offset_m"]),
            distance_m=float(layout["distance_m"]),
            panel_gap_m=float(layout["panel_gap_m"]),
        )
        scene_cfg = SimpleNamespace(
            num_envs=1,
            left_wrist=camera_cfgs[0],
            right_wrist=camera_cfgs[1],
            demo_scene=getattr(camera_rig.scene_camera, "cfg", camera_rig.scene_camera),
        )
        env_cfg = SimpleNamespace(
            scene=scene_cfg,
            isaac_teleop=SimpleNamespace(
                xr_camera_feeds=feed_cfgs,
                xr_camera_feed_layout=layout_cfg,
            ),
        )
        self._feed_session = XrCameraFeedSession.prepare(
            env_cfg, enabled=camera_rig.live_rgb_enabled,
            camera_rendering_enabled=camera_rig.live_rgb_enabled,
        )
        self.feed_session_prepared_enabled = bool(self._feed_session.enabled)
        self.feed_upload_path = str(config["vr_camera_feeds"]["upload_path"])
        if self.feed_session_prepared_enabled:
            if self.feed_upload_path != "cpu_staged":
                raise ValueError(f"unsupported demo XR camera upload path: {self.feed_upload_path}")
            presenter = self._feed_session._presenter
            if presenter is None:
                raise RuntimeError("upstream XR camera feed presenter is unavailable")
            self._feed_session._presenter = _CpuStagedFeedPresenter(
                presenter, self.preview_isolation
            )

    @property
    def xr_presentation(self) -> dict[str, Any]:
        return self.config["xr_presentation"]

    @property
    def sensitivity(self) -> dict[str, Any]:
        return self.config["teleop_tuning"]["sensitivity"]

    @property
    def display_toggle_count(self) -> int:
        return self._display_toggle_count

    @property
    def display_visible(self) -> bool:
        return self._display_visible

    @property
    def backdrop_visible(self) -> bool:
        return self._backdrop_visible

    @property
    def backdrop_toggle_count(self) -> int:
        return self._backdrop_toggle_count

    @property
    def recenter_request_count(self) -> int:
        return self._recenter_request_count

    @property
    def recenter_scheduled_count(self) -> int:
        return self._recenter_scheduled_count

    def reset_scene(self) -> None:
        for asset in self.dynamic_assets:
            asset.write_root_pose_to_sim_index(root_pose=asset.data.default_root_pose.torch.clone())
            asset.write_root_velocity_to_sim_index(
                root_velocity=asset.data.default_root_vel.torch.clone()
            )
            asset.reset()
        for sensors in self.contact_sensors.values():
            for sensor in sensors:
                sensor.reset()

    def update(self, dt: float) -> None:
        for asset in self.dynamic_assets:
            asset.update(dt)
        if not self._validation_complete:
            for sensors in self.contact_sensors.values():
                for sensor in sensors:
                    sensor.update(dt, force_recompute=True)
        # Viewer-start panels may be shown again by upstream after an XR
        # reconnect. Reassert display-only OFF without touching capture or the
        # Replicator binding.
        if self._feed_bound and not self._display_visible:
            self._set_upstream_panel_visibility(False)

    def before_render(self) -> None:
        if self.preview_isolation is not None:
            self.preview_isolation.assert_valid()

    def disable_live_rgb(self) -> None:
        """Stop sensor updates and keep all canonical camera prims for replay."""
        if self._feed_bound or self._display_visible:
            raise RuntimeError("State-only RECORD requires unbound camera previews")
        self.camera_rig.live_rgb_enabled = False
        if self.camera_rig.capture is not None:
            self.camera_rig.capture.invalidate()

    def prepare_recording_view(self) -> None:
        """Keep the selected background without enabling any camera RGB."""
        self.disable_live_rgb()
        self._set_backdrop_visibility(bool(self.config["scene"]["backdrop"]["initial_visibility"]))

    def open(self, env) -> None:
        self._env = env
        self._initial_capture = asdict(env.latest_observation_capture())
        self._runtime_frames = self._camera_frames()
        self._runtime_capture_cycles = self.camera_rig.capture_cycles_total
        self._set_backdrop_visibility(bool(self.config["scene"]["backdrop"]["initial_visibility"]))
        self._prebind_camera_panels()
        if self.hud_on_start:
            self._set_display(True)

    def _prebind_camera_panels(self) -> None:
        """Complete Candidate B's bind phase before XR session entry."""

        # Candidate B's two-phase lifecycle requires bind(env) before entering
        # the XR teleop session. Build both SceneUI panels now, initially
        # hidden, so X only changes visibility after the headset connects.
        if self.feed_session_prepared_enabled:
            self._feed_session.bind(self._env)
            self._feed_bound = True
            self._feed_bound_ever = True
            manager = self._feed_session._manager
            if manager is None:
                raise RuntimeError("upstream XR camera feed manager is unavailable")
            self._feed_updates = _FreshVisibleFeedUpdates(
                manager,
                lambda: self._display_visible,
                getattr(self, "_camera_diagnostics", None),
            )
            manager.update = self._feed_updates.update
            # One initial publication validates the compatibility buffer.
            # Subsequent hidden callbacks return before any feed acquisition.
            self._feed_session.refresh()
            from tools.isaac_vr_preview_layout import PreviewLayoutPanels

            self._preview_layouts = PreviewLayoutPanels(
                manager, self._feed_session._presenter,
                self.config["vr_camera_feeds"]["wall_layout"], self.preview_isolation,
            )
            self._set_upstream_panel_visibility(False)
            manager = self._feed_session._manager
            feeds = tuple(manager._feeds) if manager is not None else ()
            if getattr(self, "diagnostic", False):
                diagnostics = []
                for feed in feeds:
                    source_image = feed.image
                    upload_image = feed.upload_image
                    diagnostics.append(
                        {
                            "camera": feed.cfg.camera_name,
                            "rgb_stddev": float(upload_image[..., :3].float().std().item()),
                            "source_alpha_range": [
                                int(source_image[..., 3].min().item()),
                                int(source_image[..., 3].max().item()),
                            ],
                            "source_device": source_image.device.type,
                            "source": (
                                "isaac_lab_camera_rgba"
                                if feed.image_source is None
                                else "feed_owned_replicator_annotator"
                            ),
                            "upload_alpha_range": [
                                int(upload_image[..., 3].min().item()),
                                int(upload_image[..., 3].max().item()),
                            ],
                            "upload_device": upload_image.device.type,
                            "panel_layout_pixels": [
                                feed.panel._component.width
                                * feed.panel._component.unit_to_pixel_scale,
                                feed.panel._component.height
                                * feed.panel._component.unit_to_pixel_scale,
                            ],
                            "panel_resolution_scale": feed.panel._component.resolution_scale,
                        }
                    )
                print(
                    json.dumps(
                        {
                            "event": "demo_vr_camera_feed_bound",
                            "feeds": diagnostics,
                            "layout": self.config["vr_camera_feeds"]["layout"]["placement"],
                            "upload_path": self.feed_upload_path,
                        },
                        sort_keys=True,
                    ),
                    flush=True,
                )
            print("[DEMO] wrist camera panels prebound hidden before XR session", flush=True)

    def close(self) -> None:
        if self._feed_bound:
            if getattr(self, "_preview_layouts", None) is not None:
                self._preview_layout_report = self._preview_layouts.report()
                self._preview_layouts.close_inactive()
                self._preview_layouts = None
            if self._feed_updates is not None:
                self._feed_update_report = dict(self._feed_updates.counters)
            self._feed_session.close()
            self._feed_bound = False
            self._feed_updates = None
        self._env = None

    def after_reset(self) -> None:
        # Preserve edge state across a scene reset so a physically held X/B
        # cannot be interpreted as a second press in the new reset epoch.
        self._set_backdrop_visibility(self._backdrop_visible)
        if self._feed_bound:
            # Refresh/reset may recycle a frame number or replace its camera.
            assert self._feed_updates is not None
            self._feed_updates.invalidate()
            self._feed_session._manager.refresh(publish=False)
            self._feed_updates.update()
            self._set_upstream_panel_visibility(self._display_visible)

    def consume_display_button(
        self, value: float, *, event_origin: str = "controller_pipeline"
    ) -> None:
        pressed = bool(value > 0.5)
        if pressed and not self._display_button_pressed:
            self._set_display(not self._display_visible)
            self._display_toggle_count += 1
            print(
                json.dumps(
                    {
                        "capture_continues": True,
                        "control": self.display_control,
                        "display_visible": self._display_visible,
                        "event": "demo_vr_camera_feed_visibility_changed",
                        "event_origin": event_origin,
                        "feed_bound": self._feed_bound,
                        "quest_button": self.config["vr_camera_feeds"]["quest_button"],
                    },
                    sort_keys=True,
                ),
                flush=True,
            )
        self._display_button_pressed = pressed

    def consume_backdrop_button(
        self, value: float, *, event_origin: str = "controller_pipeline"
    ) -> None:
        pressed = bool(value > 0.5)
        if pressed and not self._backdrop_button_pressed:
            self._set_backdrop_visibility(not self._backdrop_visible)
            self._backdrop_toggle_count += 1
            print(
                json.dumps(
                    {
                        "backdrop_visible": self._backdrop_visible,
                        "control": self.backdrop_control,
                        "event": "demo_backdrop_visibility_changed",
                        "event_origin": event_origin,
                        "quest_button": self.config["scene"]["backdrop"]["quest_button"],
                        "visual_only": True,
                    },
                    sort_keys=True,
                ),
                flush=True,
            )
        self._backdrop_button_pressed = pressed

    def consume_layout_button(self, value: float, *, event_origin: str = "controller_pipeline") -> None:
        if self._preview_layouts is None or not self._preview_layouts.consume_button(value):
            return
        self._feed_updates.invalidate()
        if self._preview_layouts.mode == "wall":
            self._set_backdrop_visibility(True)
        self._set_upstream_panel_visibility(self._display_visible)
        print(json.dumps({"event": "demo_preview_layout_changed",
                          "event_origin": event_origin, "control": self.layout_control,
                          "quest_button": self.config["vr_camera_feeds"]["layout_quest_button"],
                          **self._preview_layouts.report()}, sort_keys=True), flush=True)

    def consume_recenter_button(
        self,
        value: float,
        *,
        schedule_recenter: Callable[[], bool],
        event_origin: str = "controller_pipeline",
    ) -> bool:
        """Schedule one XR recenter per R3 press and report whether it ran."""

        pressed = bool(value > 0.5)
        scheduled = False
        if pressed and not self._recenter_button_pressed:
            self._recenter_request_count += 1
            scheduled = bool(schedule_recenter())
            self._recenter_scheduled_count += int(scheduled)
            print(
                json.dumps(
                    {
                        "authoritative_scene_geometry_changed": False,
                        "control": self.recenter_control,
                        "event": "demo_xr_recenter_requested",
                        "event_origin": event_origin,
                        "quest_button": self.config["xr_presentation"]["recenter"]["quest_button"],
                        "scheduled": scheduled,
                        "session_restart": False,
                        "view_prim_path": self.recenter_view_prim_path,
                    },
                    sort_keys=True,
                ),
                flush=True,
            )
        self._recenter_button_pressed = pressed
        return scheduled

    def _set_backdrop_visibility(self, visible: bool) -> None:
        """Toggle only the visual USD backdrop; robot/table physics are untouched."""

        import omni.usd  # type: ignore[import-not-found]
        from pxr import UsdGeom  # type: ignore[import-not-found]

        stage = omni.usd.get_context().get_stage()
        prim = stage.GetPrimAtPath("/World/RobosynDemo/Backdrop")
        if not prim.IsValid():
            raise RuntimeError("demo backdrop prim is missing")
        imageable = UsdGeom.Imageable(prim)
        if visible:
            imageable.MakeVisible()
        else:
            imageable.MakeInvisible()
        self._backdrop_visible = visible

    def _set_upstream_panel_visibility(self, visible: bool) -> None:
        """Show/hide pinned upstream SceneUI panels without closing their RGB source."""

        manager = self._feed_session._manager
        if manager is None:
            raise RuntimeError("upstream XR camera feed manager is not bound")
        feeds = tuple(manager._feeds)
        expected = 3 if self.preview_scene else 2
        if len(feeds) != expected:
            raise RuntimeError(f"expected {expected} upstream feed panels, got {len(feeds)}")
        self.before_render()
        for feed in feeds:
            container = feed.panel._container
            if container is None:
                raise RuntimeError("upstream XR camera feed panel has no UiContainer")
            if visible:
                container.show()
                if self.preview_isolation is not None:
                    self.preview_isolation.check_panel(feed.panel)
            else:
                if self.preview_isolation is not None:
                    self.preview_isolation.release_panel(feed.panel)
                container.hide()

    def _set_display(self, visible: bool) -> None:
        if visible == self._display_visible:
            return
        if self._env is None:
            raise RuntimeError("demo HUD cannot change before runtime binding")
        if visible:
            if not self.feed_session_prepared_enabled:
                raise RuntimeError(
                    "upstream XR CameraFeedSession is unavailable in this Kit experience"
                )
            if not self._feed_bound:
                raise RuntimeError("upstream XR camera panels were not bound before the XR session")
            self._set_upstream_panel_visibility(True)
            if self._feed_updates is not None:
                self._feed_updates.request_snapshot(
                    f"display-visible-{self._display_toggle_count + 1}"
                )
        else:
            # Closing here detaches the pinned Replicator RGB annotator shared
            # with Isaac Lab Camera and makes the next Camera.update() fail.
            # UiContainer visibility is the upstream display-only mechanism;
            # final resource teardown remains in close().
            self._set_upstream_panel_visibility(False)
        self._display_visible = visible
        print(f"[DEMO] wrist camera display {'ON' if visible else 'OFF'}", flush=True)

    def _camera_frames(self) -> dict[str, int]:
        wrist: np.ndarray = _cpu(self.camera_rig.frame).astype(np.int64)
        scene: np.ndarray = _cpu(self.camera_rig.scene_camera.frame).astype(np.int64)
        return {
            "left_wrist": int(wrist[0]),
            "right_wrist": int(wrist[1]),
            "demo_scene": int(scene[0]),
        }

    def performance_report(self, elapsed: float, camera_observation_frames: int) -> dict[str, Any]:
        assert self.camera_rig.capture is not None
        final = self._camera_frames()
        cycles = self.camera_rig.capture_cycles_total - self._runtime_capture_cycles
        rates = {name: camera_observation_frames / elapsed for name in final}
        try:
            current_capture = asdict(self.camera_rig.capture.latest())
        except RuntimeError:
            current_capture = None
        return {
            "observation_capture": {
                "initial": self._initial_capture,
                "current": current_capture,
                "last_error": self.camera_rig.capture.last_error,
                "failed_attempts": self.camera_rig.capture.failed_attempts,
                "successful_capture_cycles": self.camera_rig.capture_cycles_total,
                "rgb_cpu_copies_for_capture": 0,
            },
            "profile": self.profile,
            "preview_partition_topology": self.preview_isolation.report()
            if self.preview_isolation
            else {"enabled": False},
            "preview_feed_count": 3 if self.preview_scene else 2,
            "preview_layout": (self._preview_layouts.report() if self._preview_layouts
                               else self._preview_layout_report),
            "camera_frames_start": self._runtime_frames,
            "camera_frames_end": final,
            "camera_capture_cycles_including_reset": cycles,
            "camera_effective_hz": rates,
            "camera_configured_simulation_hz": {
                "left_wrist": 30.0,
                "right_wrist": 30.0,
                "demo_scene": 30.0,
            },
            "camera_feed_updates": (
                dict(self._feed_updates.counters)
                if self._feed_updates is not None
                else self._feed_update_report
            ),
            "vr_feed_visibility": {
                "initial": self.hud_on_start,
                "final": self._display_visible,
                "toggle_count": self._display_toggle_count,
                "control": self.display_control,
                "quest_button": self.config["vr_camera_feeds"]["quest_button"],
                "capture_continues_when_hidden": True,
                "feed_bound_ever": self._feed_bound_ever,
                "upstream_session_prepared_enabled": self.feed_session_prepared_enabled,
                "upload_path": self.feed_upload_path,
                "provider_api": "ByteImageProvider.set_raw_bytes_data CPU RGBA8_UNORM",
                "preview_policy": "visible fresh camera frames; on-demand UI texture capture",
            },
            "backdrop_visibility": {
                "initial": bool(self.config["scene"]["backdrop"]["initial_visibility"]),
                "final": self._backdrop_visible,
                "toggle_count": self._backdrop_toggle_count,
                "control": self.backdrop_control,
                "quest_button": self.config["scene"]["backdrop"]["quest_button"],
                "visual_only": True,
            },
            "xr_recenter": {
                "request_count": self._recenter_request_count,
                "scheduled_count": self._recenter_scheduled_count,
                "control": self.recenter_control,
                "quest_button": self.config["xr_presentation"]["recenter"]["quest_button"],
                "view_prim_path": self.recenter_view_prim_path,
                "upstream_mechanism": "XRCore.schedule_teleport_to_view",
                "controller_transform_source": ("XRCore.get_physical_to_virtual_world_transform"),
                "authoritative_scene_geometry_changed": False,
            },
            "optional_demo_performance_mode": "preview_uploads_optimized_renderer_unchanged",
            "validation": self.validation,
        }

    def validate(self, env) -> dict[str, Any]:
        from tools.isaac_vr_zed import verify_mounts

        mount_readback = verify_mounts(env)
        live_rgb = self.camera_rig.live_rgb_enabled
        preflight_capture = (
            self.camera_rig.capture.latest(require_eligible=False) if live_rgb else None
        )
        observation = env.observation() if live_rgb else {}
        state = (
            observation["observation.state"] if live_rgb
            else np.asarray(env.capture_measured_state()[1], dtype=np.float32)
        )
        home_error = np.abs(state - env.home_d0)
        forces = {}
        for side, sensors in self.contact_sensors.items():
            magnitudes = [
                float(np.linalg.norm(_cpu(sensor.data.net_forces_w), axis=-1).max(initial=0.0))
                for sensor in sensors
            ]
            forces[side] = max(magnitudes, default=0.0)
        scene_image = _scene_rgb(self.camera_rig.scene_camera) if live_rgb else None
        wrist_shapes = {
            role: list(observation[f"observation.images.{role}"].shape)
            for role in ("left_wrist", "right_wrist")
        } if live_rgb else {}
        import omni.usd  # type: ignore[import-not-found]
        from pxr import UsdPhysics  # type: ignore[import-not-found]

        stage = omni.usd.get_context().get_stage()
        imports = {
            asset_id: bool(stage.GetPrimAtPath(path).IsValid())
            for asset_id, path in self.imported_prims.items()
        }
        required_paths = [
            "/World/RobosynDemo/Table",
            "/World/RobosynDemo/Backdrop",
            "/World/LeftPiper",
            "/World/RightPiper",
            "/World/RobosynDemo/SceneCamera",
        ]
        if self.profile == "dual_cube_to_matching_plates":
            required_paths.extend(
                [
                    "/World/RobosynDemo/LeftCube",
                    "/World/RobosynDemo/RightCube",
                    "/World/RobosynDemo/LeftPlate",
                    "/World/RobosynDemo/RightPlate",
                ]
            )
        required_prims = {
            path: bool(stage.GetPrimAtPath(path).IsValid()) for path in required_paths
        }
        camera_prims = {
            role: bool(stage.GetPrimAtPath(path).IsValid()
                       and stage.GetPrimAtPath(path).GetTypeName() == "Camera")
            for role, path in self.camera_rig.camera_prim_paths.items()
        }
        table_collision = any(
            prim.HasAPI(UsdPhysics.CollisionAPI)
            for prim in stage.Traverse()
            if str(prim.GetPath()).startswith("/World/RobosynDemo/Table")
        )
        reset_errors = []
        for asset in self.dynamic_assets:
            actual = _cpu(asset.data.root_pos_w)
            expected = _cpu(asset.data.default_root_pose.torch)[:, :3]
            reset_errors.append(float(np.linalg.norm(actual - expected, axis=-1).max()))
        tcp_positions = [
            _cpu(robot.data.body_link_pose_w)[0, wrist_id, :3].tolist()
            for robot, wrist_id in zip(env.robots, env.wrist_ids, strict=True)
        ]
        contact_free = all(value <= 1.0e-3 for value in forces.values())
        report: dict[str, Any] = {
            "observation_capture": asdict(preflight_capture) if live_rgb else None,
            "camera_rendering": "live_rgb" if live_rgb else "usd_prims_only",
            "camera_prim_valid": camera_prims,
            "zed_mounts": self.camera_rig.zed_mounts,
            "zed_pose_readback": mount_readback,
            "candidate_home_used": True,
            "maximum_home_error_deg_or_mm": float(home_error.max()),
            "finite_state": bool(np.isfinite(state).all()),
            "maximum_arm_contact_force_n": forces,
            "collision_free_at_home": contact_free,
            "home_tcp_world_m": {"left": tcp_positions[0], "right": tcp_positions[1]},
            "home_tcp_separation_m": float(
                np.linalg.norm(np.asarray(tcp_positions[0]) - np.asarray(tcp_positions[1]))
            ),
            "maximum_profile_reset_position_error_m": max(reset_errors, default=0.0),
            "wrist_shapes": wrist_shapes,
            "scene_camera": {
                "shape": list(scene_image.shape),
                "dtype": str(scene_image.dtype),
                "rgb_stddev": float(scene_image.astype(np.float32).std()),
                "frame": int(_cpu(self.camera_rig.scene_camera.frame)[0]),
            } if live_rgb else {"rendered": False},
            "imported_prim_valid": imports,
            "required_prim_valid": required_prims,
            "table_collision_api": bool(table_collision),
        }
        threshold = float(self.config["validation"]["maximum_home_drift_deg"])
        report["passed"] = bool(
            report["finite_state"]
            and report["maximum_home_error_deg_or_mm"] <= threshold
            and report["collision_free_at_home"]
            and report["maximum_profile_reset_position_error_m"]
            <= float(self.config["validation"]["profile_reset_position_tolerance_m"])
            and (not live_rgb or (
                wrist_shapes == {role: [self.config["cameras"]["wrist"]["height"],
                                      self.config["cameras"]["wrist"]["width"], 3]
                                 for role in ("left_wrist", "right_wrist")}
                and report["scene_camera"]["shape"] == [self.config["cameras"]["scene"]["height"],
                                                    self.config["cameras"]["scene"]["width"], 3]
                and report["scene_camera"]["dtype"] == "uint8"
                and report["scene_camera"]["rgb_stddev"]
                >= float(self.config["validation"]["minimum_scene_rgb_stddev"])
            ))
            and all(imports.values())
            and all(required_prims.values())
            and all(camera_prims.values())
            and report["table_collision_api"]
        )
        self.validation = report
        # Contact tensors are a preflight-only check.  Keep their PhysX reporters
        # intact, but stop forcing tensor reads on every physical teleop frame.
        self._validation_complete = True
        return report


def _spawn_static_scene(config: dict[str, Any]) -> None:
    scene = config["scene"]
    floor = scene["floor"]
    ground = sim_utils.GroundPlaneCfg(size=tuple(floor["size_m"]), color=tuple(floor["color_rgb"]))
    if os.environ.get("ROBOSYN_VR_GROUND_USD"):
        ground.usd_path = os.environ["ROBOSYN_VR_GROUND_USD"]
    ground.func("/World/Ground", ground)
    table = scene["table"]
    table_cfg = sim_utils.CuboidCfg(
        size=tuple(table["size_m"]),
        collision_props=sim_utils.CollisionPropertiesCfg(),
        physics_material=sim_utils.RigidBodyMaterialCfg(
            static_friction=float(table["static_friction"]),
            dynamic_friction=float(table["dynamic_friction"]),
        ),
        visual_material=sim_utils.PreviewSurfaceCfg(
            diffuse_color=tuple(table["color_rgb"]), roughness=0.72
        ),
    )
    table_cfg.func("/World/RobosynDemo/Table", table_cfg, translation=tuple(table["center_m"]))
    backdrop = scene["backdrop"]
    backdrop_cfg = sim_utils.CuboidCfg(
        size=tuple(backdrop["size_m"]),
        visual_material=sim_utils.PreviewSurfaceCfg(
            diffuse_color=tuple(backdrop["color_rgb"]), roughness=0.85
        ),
    )
    backdrop_cfg.func(
        "/World/RobosynDemo/Backdrop", backdrop_cfg, translation=tuple(backdrop["center_m"])
    )
    dome = scene["lighting"]["dome"]
    dome_cfg = sim_utils.DomeLightCfg(
        intensity=float(dome["intensity"]), color=tuple(dome["color_rgb"])
    )
    dome_cfg.func("/World/RobosynDemo/DomeLight", dome_cfg)
    key = scene["lighting"]["key"]
    key_cfg = sim_utils.DistantLightCfg(
        intensity=float(key["intensity"]),
        color=tuple(key["color_rgb"]),
        angle=float(key["angle_deg"]),
    )
    key_cfg.func(
        "/World/RobosynDemo/KeyLight",
        key_cfg,
        orientation=(0.270598, -0.270598, -0.653281, 0.653281),
    )


def _rigid_cube(path: str, item: dict[str, Any]) -> RigidObject:
    return RigidObject(
        RigidObjectCfg(
            prim_path=path,
            spawn=sim_utils.CuboidCfg(
                size=(float(item["edge_m"]),) * 3,
                rigid_props=sim_utils.RigidBodyPropertiesCfg(max_depenetration_velocity=1.0),
                mass_props=sim_utils.MassPropertiesCfg(mass=0.035),
                collision_props=sim_utils.CollisionPropertiesCfg(),
                physics_material=sim_utils.RigidBodyMaterialCfg(
                    static_friction=0.8, dynamic_friction=0.6
                ),
                visual_material=sim_utils.PreviewSurfaceCfg(
                    diffuse_color=tuple(item["color_rgb"]), roughness=0.42
                ),
            ),
            init_state=RigidObjectCfg.InitialStateCfg(pos=tuple(item["position_m"])),
        )
    )


def _spawn_task_profile(config: dict[str, Any]) -> tuple[list[Any], dict[str, str]]:
    profile = config["profiles"]["dual_cube_to_matching_plates"]
    objects = [
        _rigid_cube("/World/RobosynDemo/LeftCube", profile["left_cube"]),
        _rigid_cube("/World/RobosynDemo/RightCube", profile["right_cube"]),
    ]
    for side in ("left", "right"):
        plate = profile[f"{side}_plate"]
        plate_cfg = sim_utils.CylinderCfg(
            radius=float(plate["diameter_m"]) / 2.0,
            height=float(plate["thickness_m"]),
            collision_props=sim_utils.CollisionPropertiesCfg(),
            visual_material=sim_utils.PreviewSurfaceCfg(
                diffuse_color=tuple(plate["color_rgb"]), roughness=0.5
            ),
        )
        plate_cfg.func(
            f"/World/RobosynDemo/{side.title()}Plate",
            plate_cfg,
            translation=tuple(plate["position_m"]),
        )
    return objects, {}


def _spawn_asset_profile(config: dict) -> tuple[list[Any], dict[str, str]]:
    asset_root = Path(config["asset_lab"]["source_checkout"])
    button_source = asset_root / "assets/button/button.urdf"
    button_hash = hashlib.sha256(button_source.read_bytes()).hexdigest()
    button_converter = sim_utils.UrdfConverter(
        sim_utils.UrdfConverterCfg(
            asset_path=str(button_source),
            usd_dir=str(CONVERTED_ROOT / f"button-{button_hash}"),
            fix_base=True,
            merge_fixed_joints=False,
            self_collision=False,
            run_multi_physics_conversion=False,
            joint_drive=sim_utils.UrdfConverterCfg.JointDriveCfg(
                drive_type="force",
                target_type="position",
                gains=sim_utils.UrdfConverterCfg.JointDriveCfg.PDGainsCfg(
                    stiffness=40.0, damping=2.0
                ),
            ),
        )
    )
    button = Articulation(
        ArticulationCfg(
            prim_path="/World/RobosynDemo/TestAssets/Button",
            spawn=sim_utils.UsdFileCfg(usd_path=button_converter.usd_path),
            init_state=ArticulationCfg.InitialStateCfg(
                pos=(0.88, 0.28, 0.84), joint_pos={"press": 0.0}, joint_vel={"press": 0.0}
            ),
            actuators={
                "press": ImplicitActuatorCfg(
                    joint_names_expr=["press"],
                    effort_limit_sim=1.0,
                    velocity_limit_sim=1.0,
                    stiffness=40.0,
                    damping=2.0,
                )
            },
        )
    )
    pen_source = asset_root / "assets/Pen/the_pen.obj"
    pen_hash = hashlib.sha256(pen_source.read_bytes()).hexdigest()
    pen_converter = sim_utils.MeshConverter(
        sim_utils.MeshConverterCfg(
            asset_path=str(pen_source),
            usd_dir=str(CONVERTED_ROOT / f"pen-{pen_hash}"),
            usd_file_name="pen.usd",
            force_usd_conversion=False,
            make_instanceable=True,
            scale=(1.0, 1.6, 1.6),
            mass_props=sim_utils.MassPropertiesCfg(mass=0.005),
            rigid_props=sim_utils.RigidBodyPropertiesCfg(max_depenetration_velocity=1.0),
            collision_props=sim_utils.CollisionPropertiesCfg(),
            mesh_collision_props=sim_utils.ConvexHullPropertiesCfg(),
        )
    )
    pen = RigidObject(
        RigidObjectCfg(
            prim_path="/World/RobosynDemo/TestAssets/Pen",
            spawn=sim_utils.UsdFileCfg(usd_path=pen_converter.usd_path),
            init_state=RigidObjectCfg.InitialStateCfg(pos=(0.88, -0.22, 0.835)),
        )
    )
    beaker_path = "/World/RobosynDemo/TestAssets/Beaker"
    beaker_cfg = sim_utils.UsdFileCfg(
        usd_path=str(asset_root / "assets/Beaker/Beaker.usd"), scale=(0.014, 0.014, 0.015)
    )
    beaker_cfg.func(beaker_path, beaker_cfg, translation=(1.02, 0.0, 0.825))
    return [button, pen], {
        "robosyn_button": "/World/RobosynDemo/TestAssets/Button",
        "robosyn_pen": "/World/RobosynDemo/TestAssets/Pen",
        "robosyn_beaker": beaker_path,
    }


def _demo_robot_cfg(
    robot_cfg_factory,
    config: dict[str, Any],
    prim_path: str,
    position: tuple[float, float, float],
    usd_path: str,
    *,
    home_per_arm: np.ndarray,
) -> ArticulationCfg:
    """Keep imported mimic followers passive in the selected VR scene."""

    cfg = robot_cfg_factory(
        prim_path,
        position,
        usd_path,
        home_per_arm=home_per_arm,
        enable_self_collisions=True,
        activate_contact_sensors=True,
    )
    gripper = config["demo_physics"]["gripper_contact"]
    leader = gripper["leader_drive"]
    follower = gripper["mimic_follower_drive"]
    cfg.actuators["gripper_position_drives"] = ImplicitActuatorCfg(
        joint_names_expr=[str(gripper["leader_joint"])],
        effort_limit_sim=float(leader["effort_limit_n"]),
        velocity_limit_sim=float(leader["velocity_limit_m_s"]),
        stiffness=float(leader["stiffness_n_m"]),
        damping=float(leader["damping_n_s_m"]),
    )
    cfg.actuators["gripper_mimic_followers"] = ImplicitActuatorCfg(
        joint_names_expr=[str(gripper["mimic_follower_joint_expr"])],
        effort_limit_sim=float(follower["effort_limit_n"]),
        velocity_limit_sim=float(follower["velocity_limit_m_s"]),
        stiffness=float(follower["stiffness_n_m"]),
        damping=float(follower["damping_n_s_m"]),
    )
    return cfg


