def _arm_contact_sensors(sim, arm_path: str) -> list[ContactSensor]:
    from pxr import Usd, UsdPhysics  # type: ignore[import-not-found]

    body_paths = [
        str(prim.GetPath())
        for prim in Usd.PrimRange(sim.stage.GetPrimAtPath(arm_path))
        if prim.HasAPI(UsdPhysics.RigidBodyAPI) and prim.GetName() != "base_link"
    ]
    if not body_paths:
        raise RuntimeError(f"no articulated arm bodies found for contact smoke: {arm_path}")
    return [
        ContactSensor(
            ContactSensorCfg(
                prim_path=path,
                update_period=0.0,
                history_length=1,
                debug_vis=False,
            )
        )
        for path in body_paths
    ]


def run_vr(
    args_cli,
    simulation_app,
    *,
    urdf_path: Path,
    urdf_sha: str,
    robot_cfg_factory,
    wrist_path_resolver,
    environment_type,
    stop_requested=None,
) -> int:
    """Build the selected VR scene, validate it, then enter the existing S2 loop."""

    config = load_composition(args_cli.demo_profile)
    render_substeps = int(config["rendering"]["physics_substeps_per_render"])
    if render_substeps != 4:
        raise ValueError("The selected VR composition requires FFFT rendering")
    recording = bool(args_cli.s2_record)
    if recording and args_cli.demo_hud_on_start:
        raise ValueError("RECORD forbids live camera previews")
    print(f"[VR] profile={args_cli.demo_profile} physical_human_gate=required")
    sim = sim_utils.SimulationContext(
        sim_utils.SimulationCfg(
            dt=PHYSICS_DT, render_interval=render_substeps,
            device=args_cli.device, use_fabric=True
        )
    )
    isolation = None
    if args_cli.demo_preview_isolation == "scene-partitions":
        from isaac_preview_partitions import PreviewPartitions

        isolation = PreviewPartitions(sim.stage)
    config["vr_camera_feeds"]["include_scene_camera"] = bool(args_cli.demo_preview_scene)
    _spawn_static_scene(config)
    dynamic_assets, imported_prims = (
        _spawn_task_profile(config)
        if args_cli.demo_profile == "dual_cube_to_matching_plates"
        else _spawn_asset_profile(config)
    )
    probe = _physics_probe()
    converter = sim_utils.UrdfConverter(
        sim_utils.UrdfConverterCfg(
            asset_path=str(urdf_path),
            usd_dir=str(urdf_path.parent / "converted" / urdf_sha),
            fix_base=True,
            merge_fixed_joints=False,
            self_collision=False,
            robot_type="Manipulator",
            run_multi_physics_conversion=False,
            ros_package_paths=[
                {"name": "agx_arm_description", "path": "/data/vla-infrastructure/assets"}
            ],
            joint_drive=sim_utils.UrdfConverterCfg.JointDriveCfg(
                drive_type="force",
                target_type="position",
                gains=sim_utils.UrdfConverterCfg.JointDriveCfg.PDGainsCfg(
                    stiffness=400.0, damping=40.0
                ),
            ),
        )
    )
    homes = config["scene"]["candidate_home_d0_per_arm"]
    home_left = np.asarray(homes["left"], dtype=np.float64)
    home_right = np.asarray(homes["right"], dtype=np.float64)
    bases = config["scene"]["robot_bases_m"]
    left = Articulation(
        _demo_robot_cfg(
            robot_cfg_factory,
            config,
            "/World/LeftPiper",
            tuple(bases["left"]),
            converter.usd_path,
            home_per_arm=home_left,
        )
    )
    right = Articulation(
        _demo_robot_cfg(
            robot_cfg_factory,
            config,
            "/World/RightPiper",
            tuple(bases["right"]),
            converter.usd_path,
            home_per_arm=home_right,
        )
    )
    wrist_paths = tuple(
        wrist_path_resolver(sim, arm) for arm in ("/World/LeftPiper", "/World/RightPiper")
    )
    from tools.isaac_vr_zed import create_camera, upstream_identity

    zed_selection = config["cameras"]["zed"]
    zed_identity = upstream_identity(zed_selection)
    wrist_results = tuple(
        create_camera(
            sim.stage, f"{path}/ZEDCamera", config["cameras"]["wrist"],
            zed_selection, zed_identity, rgba=True, wrist=True,
            live_rgb_enabled=not recording,
        ) for path in wrist_paths
    )
    wrist_cameras = tuple(result[0] for result in wrist_results)
    wrist_camera_cfgs = tuple(getattr(camera, "cfg", camera) for camera in wrist_cameras)
    scene_camera, scene_mount = create_camera(
        sim.stage, "/World/RobosynDemo/SceneCamera", config["cameras"]["scene"],
        zed_selection, zed_identity, rgba=bool(args_cli.demo_preview_scene), wrist=False,
        live_rgb_enabled=not recording,
    )
    camera_rig = VRCameraRig(wrist_cameras, scene_camera, live_rgb_enabled=not recording)
    camera_rig.zed_mounts = {
        "left_wrist": wrist_results[0][1], "right_wrist": wrist_results[1][1],
        "scene": scene_mount,
    }
    camera_rig.preview_isolation = isolation
    if isolation:
        isolation.bind_sensors(
            (*wrist_cameras, scene_camera),
            concrete_paths=list(camera_rig.camera_prim_paths.values()),
        )
    contacts = {
        side.lower(): _arm_contact_sensors(sim, f"/World/{side.title()}Piper")
        for side in ("left", "right")
    }
    runtime = VRRuntime(
        config=config,
        profile=args_cli.demo_profile,
        camera_rig=camera_rig,
        camera_cfgs=wrist_camera_cfgs,
        dynamic_assets=dynamic_assets,
        contact_sensors=contacts,
        imported_prims=imported_prims,
        hud_on_start=bool(args_cli.demo_hud_on_start),
        diagnostic=args_cli.s2_mode == "diagnostic",
    )
    sim.reset()
    env = environment_type(
        sim,
        left,
        right,
        camera_rig,
        wrist_paths,
        "two_named_demo_wrist_cameras",
        probe,
        home_d0=np.concatenate((home_left, home_right)),
        vr_runtime=runtime,
    )
    env.scene = SimpleNamespace(
        sensors={
            "left_wrist": wrist_cameras[0],
            "right_wrist": wrist_cameras[1],
            "demo_scene": scene_camera,
        }
    )
    env.reset(0)
    env._advance(int(config["validation"]["settle_physics_steps"]) - env.reset_settle_physics_steps)
    validation = runtime.validate(env)
    print(f"[DEMO] validation={validation}", flush=True)
    if not validation["passed"]:
        raise RuntimeError(f"VR preflight failed: {validation}")
    if args_cli.demo_scene_preview is not None:
        from PIL import Image

        preview = _scene_rgb(scene_camera)
        args_cli.demo_scene_preview.parent.mkdir(parents=True, exist_ok=True)
        Image.fromarray(preview).save(args_cli.demo_scene_preview)
        print(f"[DEMO] scene preview={args_cli.demo_scene_preview}", flush=True)
    from isaac_s2_runtime import run_s2

    return run_s2(env, args_cli, simulation_app, stop_requested=stop_requested)

