_SHA256 = re.compile(r"[0-9a-f]{64}\Z")


class MaterializationError(RuntimeError):
    """The source projection or LeRobot materialization is invalid."""


def _canonical_json(value: object) -> bytes:
    return json.dumps(
        value,
        allow_nan=False,
        ensure_ascii=True,
        separators=(",", ":"),
        sort_keys=True,
    ).encode("utf-8")


def _canonical_sha256(value: object) -> str:
    return hashlib.sha256(_canonical_json(value)).hexdigest()


def _sha256_stable(path: Path) -> str:
    try:
        before = path.stat()
        digest = hashlib.sha256()
        with path.open("rb") as stream:
            for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                digest.update(chunk)
        after = path.stat()
    except OSError as exc:
        raise MaterializationError(f"cannot hash artifact: {path}") from exc
    identity_before = (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns)
    identity_after = (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
    if identity_before != identity_after:
        raise MaterializationError(f"artifact changed while it was hashed: {path}")
    return digest.hexdigest()


def _require_sha256(value: object, *, field: str) -> str:
    if not isinstance(value, str) or _SHA256.fullmatch(value) is None:
        raise MaterializationError(f"{field} must be a lowercase SHA-256 digest")
    return value


def _load_json_object(path: Path, *, label: str) -> dict[str, Any]:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise MaterializationError(f"{label} is unreadable: {path}") from exc
    if not isinstance(value, dict):
        raise MaterializationError(f"{label} root must be an object")
    return value


def _write_json(path: Path, value: object) -> None:
    path.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    path.chmod(0o600)


def _decode_text(value: Any) -> str:
    array = np.asarray(value)
    if array.shape != ():
        raise MaterializationError("native text identity is not scalar")
    raw = array.item()
    if isinstance(raw, bytes):
        text = raw.rstrip(b"\0").decode("utf-8")
    elif isinstance(raw, str):
        text = raw.rstrip("\0")
    else:
        raise MaterializationError(f"native text identity has unsupported type {type(raw)!r}")
    if not text:
        raise MaterializationError("native text identity is empty")
    return text


def _digest_hex(value: Any) -> str:
    raw = np.asarray(value, dtype=np.uint8)
    if raw.shape != (32,):
        raise MaterializationError(f"native digest has shape {raw.shape}, expected (32,)")
    return raw.tobytes().hex()


def _projection_from_rows(rows: Sequence[Mapping[str, Any]]) -> dict[str, np.ndarray]:
    if not rows:
        raise MaterializationError("native episode contains no committed D0 rows")
    frames = len(rows)
    frame_index = np.asarray([int(row["frame_index"]) for row in rows], dtype=np.int64)
    if not np.array_equal(frame_index, np.arange(frames, dtype=np.int64)):
        raise MaterializationError("native committed frame indices are not dense zero-based")

    def texts(field: str) -> np.ndarray:
        return np.asarray([_decode_text(row[field]) for row in rows], dtype=np.str_)

    def digests(field: str) -> np.ndarray:
        return np.asarray([_digest_hex(row[field]) for row in rows], dtype=np.str_)

    observation_state = np.stack(
        [np.asarray(row["observation_state"], dtype=np.float32) for row in rows]
    )
    action = np.stack([np.asarray(row["dataset_action"], dtype=np.float32) for row in rows])
    successor = np.stack(
        [np.asarray(row["successor_observation_state"], dtype=np.float32) for row in rows]
    )
    for field, values in (
        ("observation_state", observation_state),
        ("action", action),
        ("successor_observation_state", successor),
    ):
        if values.shape != (frames, *VECTOR_SHAPE) or values.dtype != np.float32:
            raise MaterializationError(f"{field} must be float32[{frames},14]")
        if not np.isfinite(values).all():
            raise MaterializationError(f"{field} contains NaN or Inf")

    result = {
        "frame_index": frame_index,
        "observation_state": observation_state,
        "action": action,
        "obs_id": texts("obs_id"),
        "scene_state_snapshot_id": texts("scene_state_snapshot_id"),
        "scene_state_snapshot_sha256": digests("scene_state_snapshot_sha256"),
        "transition_id": texts("transition_id"),
        "transition_outcome": texts("transition_outcome"),
        "terminated": np.asarray([int(row["terminated"]) for row in rows], dtype=np.uint8),
        "success": np.asarray([int(row["success"]) for row in rows], dtype=np.uint8),
        "next_obs_id": texts("next_obs_id"),
        "successor_observation_state": successor,
    }
    _validate_projection_arrays(result)
    return result


def _validate_projection_arrays(arrays: Mapping[str, np.ndarray]) -> int:
    if set(arrays) != set(PROJECTION_ARRAYS):
        raise MaterializationError(
            "projection arrays differ from schema: "
            f"missing={sorted(set(PROJECTION_ARRAYS) - set(arrays))}, "
            f"extra={sorted(set(arrays) - set(PROJECTION_ARRAYS))}"
        )
    frame_index = np.asarray(arrays["frame_index"])
    if frame_index.ndim != 1 or frame_index.dtype != np.int64 or len(frame_index) == 0:
        raise MaterializationError("projection frame_index must be a non-empty int64 vector")
    frames = len(frame_index)
    if not np.array_equal(frame_index, np.arange(frames, dtype=np.int64)):
        raise MaterializationError("projection frame_index must be dense and zero-based")
    for field in ("observation_state", "action", "successor_observation_state"):
        values = np.asarray(arrays[field])
        if values.dtype != np.float32 or values.shape != (frames, *VECTOR_SHAPE):
            raise MaterializationError(f"projection {field} must be float32[{frames},14]")
        if not np.isfinite(values).all():
            raise MaterializationError(f"projection {field} contains NaN or Inf")
    for field in (
        "obs_id",
        "scene_state_snapshot_id",
        "scene_state_snapshot_sha256",
        "transition_id",
        "transition_outcome",
        "next_obs_id",
    ):
        values = np.asarray(arrays[field])
        if values.shape != (frames,) or values.dtype.kind != "U":
            raise MaterializationError(f"projection {field} must be a Unicode vector")
        if any(not str(value) for value in values):
            raise MaterializationError(f"projection {field} contains an empty identity")
    for field in ("scene_state_snapshot_sha256",):
        for value in np.asarray(arrays[field]):
            _require_sha256(str(value), field=f"projection.{field}")
    for field in ("obs_id", "scene_state_snapshot_id", "transition_id"):
        values = [str(value) for value in np.asarray(arrays[field])]
        if len(values) != len(set(values)):
            raise MaterializationError(f"projection reuses {field}")
    for field in ("terminated", "success"):
        values = np.asarray(arrays[field])
        if values.shape != (frames,) or values.dtype != np.uint8:
            raise MaterializationError(f"projection {field} must be uint8[{frames}]")
        if not np.isin(values, (0, 1)).all():
            raise MaterializationError(f"projection {field} is not boolean-valued")
    if np.flatnonzero(np.asarray(arrays["terminated"])).tolist() not in ([], [frames - 1]):
        raise MaterializationError("a terminated transition must be the final committed row")
    return frames


def _validate_native_rows(rows: Sequence[Mapping[str, Any]]) -> dict[str, np.ndarray]:
    try:
        from tools.isaac_vr_recording import (
            canonical_committed_transition,
            verify_committed_transition_sample,
        )
    except ImportError:  # Isaac starts this module with tools/ on sys.path.
        from isaac_vr_recording import (  # type: ignore[no-redef]
            canonical_committed_transition,
            verify_committed_transition_sample,
        )

    canonical_rows: list[dict[str, Any]] = []
    for index, raw in enumerate(rows):
        try:
            row = canonical_committed_transition(raw)
            verify_committed_transition_sample(row)
        except (TypeError, ValueError) as exc:
            raise MaterializationError(f"native D0 row {index} failed verification: {exc}") from exc
        if int(row["frame_index"]) != index:
            raise MaterializationError(f"native D0 row {index} has a non-dense frame index")
        if int(row["committed"]) != 1:
            raise MaterializationError(f"native D0 row {index} is not committed")
        canonical_rows.append(row)

    for index, (current, following) in enumerate(zip(canonical_rows, canonical_rows[1:])):
        if _decode_text(current["next_obs_id"]) != _decode_text(following["obs_id"]):
            raise MaterializationError(f"native successor obs_id mismatch at row {index}")
        if _decode_text(current["next_scene_state_snapshot_id"]) != _decode_text(
            following["scene_state_snapshot_id"]
        ):
            raise MaterializationError(f"native successor snapshot ID mismatch at row {index}")
        if _digest_hex(current["next_scene_state_snapshot_sha256"]) != _digest_hex(
            following["scene_state_snapshot_sha256"]
        ):
            raise MaterializationError(f"native successor snapshot digest mismatch at row {index}")
        if _digest_hex(current["successor_payload_sha256"]) != _digest_hex(
            following["observation_payload_sha256"]
        ):
            raise MaterializationError(f"native successor payload mismatch at row {index}")
        if not np.array_equal(
            current["successor_observation_state"], following["observation_state"]
        ):
            raise MaterializationError(f"native successor state mismatch at row {index}")
    return _projection_from_rows(canonical_rows)


def _atomic_directory(target: Path) -> Path:
    target = target.expanduser().resolve(strict=False)
    if target.exists() or target.is_symlink():
        raise FileExistsError(f"output already exists: {target}")
    target.parent.mkdir(parents=True, exist_ok=True)
    temporary = target.parent / f".{target.name}.tmp-{uuid4().hex}"
    temporary.mkdir(mode=0o700)
    return temporary


def _publish_directory(temporary: Path, target: Path) -> None:
    target = target.expanduser().resolve(strict=False)
    if target.exists() or target.is_symlink():
        raise FileExistsError(f"output appeared during materialization: {target}")
    os.replace(temporary, target)


def _source_image_shape(source: Mapping[str, Any]) -> tuple[int, int, int]:
    """Use the immutable source geometry; old projections imply legacy 640x480."""
    cameras = source.get("visual_identity", {}).get("camera_roles", {})
    if set(cameras) != set(CAMERA_ROLES):
        raise MaterializationError("projection source camera identities are incomplete")
    shapes = set()
    for camera in cameras.values():
        resolution = camera.get("resolution", [640, 480])
        if (not isinstance(resolution, (list, tuple)) or len(resolution) != 2
                or any(type(value) is not int for value in resolution)):
            raise MaterializationError("projection source camera resolution is invalid")
        shapes.add((resolution[1], resolution[0], 3))
    if len(shapes) != 1 or not shapes <= {IMAGE_SHAPE, LEGACY_IMAGE_SHAPE}:
        raise MaterializationError("projection cameras require one supported image schema")
    return next(iter(shapes))


def _source_schema_fingerprint(source: Mapping[str, Any]) -> str:
    return (SCHEMA_FINGERPRINT if _source_image_shape(source) == IMAGE_SHAPE
            else LEGACY_SCHEMA_FINGERPRINT)


def _write_projection_bundle(
    output: Path,
    arrays: Mapping[str, np.ndarray],
    source: Mapping[str, Any],
) -> dict[str, Any]:
    frames = _validate_projection_arrays(arrays)
    target = output.expanduser().resolve(strict=False)
    temporary = _atomic_directory(target)
    try:
        projection_path = temporary / PROJECTION_FILE
        np.savez_compressed(projection_path, **arrays)
        projection_path.chmod(0o600)
        manifest: dict[str, Any] = {
            "schema": BUNDLE_SCHEMA,
            "conversion_revision": CONVERSION_REVISION,
            "schema_fingerprint_sha256": _source_schema_fingerprint(source),
            "frames": frames,
            "projection": {
                "path": PROJECTION_FILE,
                "sha256": _sha256_stable(projection_path),
                "arrays": list(PROJECTION_ARRAYS),
            },
            "source": dict(source),
        }
        manifest["manifest_sha256"] = _canonical_sha256(manifest)
        _write_json(temporary / BUNDLE_MANIFEST, manifest)
        _publish_directory(temporary, target)
    except BaseException:
        shutil.rmtree(temporary, ignore_errors=True)
        raise
    return verify_projection_bundle(target)[0]


def verify_projection_bundle(bundle: Path) -> tuple[dict[str, Any], dict[str, np.ndarray]]:
    bundle = bundle.expanduser().resolve()
    if not bundle.is_dir():
        raise MaterializationError(f"projection bundle is not a directory: {bundle}")
    manifest = _load_json_object(bundle / BUNDLE_MANIFEST, label="projection manifest")
    if manifest.get("schema") != BUNDLE_SCHEMA:
        raise MaterializationError("unsupported projection bundle schema")
    if manifest.get("conversion_revision") != CONVERSION_REVISION:
        raise MaterializationError("unsupported projection conversion revision")
    if manifest.get("schema_fingerprint_sha256") != _source_schema_fingerprint(manifest.get("source", {})):
        raise MaterializationError("projection schema fingerprint mismatch")
    declared_self = _require_sha256(
        manifest.get("manifest_sha256"), field="projection manifest_sha256"
    )
    self_payload = dict(manifest)
    del self_payload["manifest_sha256"]
    if _canonical_sha256(self_payload) != declared_self:
        raise MaterializationError("projection manifest self-hash mismatch")
    projection = manifest.get("projection")
    if not isinstance(projection, dict) or projection.get("path") != PROJECTION_FILE:
        raise MaterializationError("projection manifest has an invalid projection entry")
    if projection.get("arrays") != list(PROJECTION_ARRAYS):
        raise MaterializationError("projection manifest array order differs from schema")
    projection_path = bundle / PROJECTION_FILE
    declared_projection = _require_sha256(projection.get("sha256"), field="projection.sha256")
    if _sha256_stable(projection_path) != declared_projection:
        raise MaterializationError("projection payload digest mismatch")
    try:
        with np.load(projection_path, allow_pickle=False) as archive:
            arrays = {name: np.array(archive[name], copy=True) for name in archive.files}
    except (OSError, ValueError, KeyError) as exc:
        raise MaterializationError("projection payload is unreadable") from exc
    frames = _validate_projection_arrays(arrays)
    if manifest.get("frames") != frames:
        raise MaterializationError("projection manifest frame count mismatch")
    source = manifest.get("source")
    if not isinstance(source, dict):
        raise MaterializationError("projection source metadata is missing")
    for field in (
        "recording_sha256",
        "stage_snapshot_sha256",
        "asset_closure_sha256",
        "visual_provenance_sha256",
        "terminal_successor_sha256",
    ):
        _require_sha256(source.get(field), field=f"projection.source.{field}")
    if source.get("source_profile") not in {
        "isaac_human_vr_offline_rgb_v1", "isaac_human_vr_offline_rgb_v2"
    }:
        raise MaterializationError("projection source profile is unsupported")
    visual_identity = source.get("visual_identity")
    if not isinstance(visual_identity, dict):
        raise MaterializationError("projection source visual identity is missing")
    cameras = visual_identity.get("camera_roles")
    if not isinstance(cameras, dict) or set(cameras) != set(CAMERA_ROLES):
        raise MaterializationError("projection source camera identities are incomplete")
    for role, camera in cameras.items():
        if not isinstance(camera, dict) or set(camera) not in (
            {"camera_configuration_sha256", "prim_path"},
            {"camera_configuration_sha256", "prim_path", "resolution"},
        ):
            raise MaterializationError(f"projection source camera identity is invalid for {role}")
        _require_sha256(
            camera["camera_configuration_sha256"],
            field=f"projection.source.visual_identity.camera_roles.{role}",
        )
        if not isinstance(camera["prim_path"], str) or not camera["prim_path"]:
            raise MaterializationError(f"projection source camera prim path is invalid for {role}")
    _require_sha256(
        visual_identity.get("renderer_configuration_sha256"),
        field="projection.source.visual_identity.renderer_configuration_sha256",
    )
    if (
        not isinstance(visual_identity.get("materialization_revision"), str)
        or not visual_identity["materialization_revision"]
    ):
        raise MaterializationError("projection source materialization revision is invalid")
    return manifest, arrays


def _extract_hdf_rows(recording: Path, episode: str | None) -> tuple[str, list[dict[str, Any]]]:
    try:
        import h5py  # type: ignore[import-not-found]
    except ImportError as exc:
        raise MaterializationError(
            "extract requires h5py from the pinned Isaac environment"
        ) from exc
    try:
        with h5py.File(recording, "r") as handle:
            episodes = handle.get("episodes")
            if episodes is None:
                raise MaterializationError("native HDF has no episodes group")
            names = sorted(str(name) for name in episodes.keys())
            if episode is None:
                if len(names) != 1:
                    raise MaterializationError(
                        f"native HDF has {len(names)} episodes; select one explicitly"
                    )
                selected = names[0]
            else:
                selected = episode
                if selected not in names:
                    raise MaterializationError(f"native HDF has no episode {selected!r}")
            group = handle.get(f"episodes/{selected}/d0/committed_transition")
            if group is None:
                raise MaterializationError("native HDF has no committed D0 transition group")
            try:
                from tools.isaac_vr_recording import _empty_d0_sample
            except ImportError:
                from isaac_vr_recording import _empty_d0_sample  # type: ignore[no-redef]
            expected = set(_empty_d0_sample())
            actual = set(group.keys())
            if actual != expected:
                raise MaterializationError(
                    "native D0 channels differ from schema: "
                    f"missing={sorted(expected - actual)}, extra={sorted(actual - expected)}"
                )
            arrays = {name: np.asarray(group[name][...]) for name in expected}
            lengths = {values.shape[0] for values in arrays.values() if values.ndim >= 1}
            if len(lengths) != 1:
                raise MaterializationError("native D0 channels have inconsistent frame counts")
            frames = lengths.pop() if lengths else 0
            if frames <= 0:
                raise MaterializationError("native D0 group is empty")
            episode_group = handle[f"episodes/{selected}"]
            declared = int(episode_group.attrs.get("num_frames", -1))
            if declared != frames:
                raise MaterializationError("native episode num_frames disagrees with D0 channels")
            rows = [
                {name: values[index] for name, values in arrays.items()} for index in range(frames)
            ]
    except MaterializationError:
        raise
    except (OSError, KeyError, TypeError, ValueError) as exc:
        raise MaterializationError(f"native HDF is unreadable: {recording}") from exc
    return selected, rows


def extract_projection(
    *,
    recording: Path,
    output: Path,
    portable_roots: Mapping[str, Path],
    episode: str | None = None,
) -> dict[str, Any]:
    try:
        from tools.isaac_vr_replay import verify_recording_artifact
        from tools.isaac_vr_recording import verify_terminal_successor_snapshot
    except ImportError:
        from isaac_vr_replay import verify_recording_artifact  # type: ignore[no-redef]
        from isaac_vr_recording import (  # type: ignore[no-redef]
            verify_terminal_successor_snapshot,
        )

    recording = recording.expanduser().resolve()
    artifact = verify_recording_artifact(recording, portable_roots=portable_roots)
    selected, rows = _extract_hdf_rows(recording, episode)
    arrays = _validate_native_rows(rows)
    if len(rows) != artifact.committed_frames:
        raise MaterializationError("native D0 count disagrees with finalized recording manifest")
    try:
        verify_terminal_successor_snapshot(
            artifact.terminal_successor_path,
            expected_artifact_sha256=artifact.terminal_successor_sha256,
            committed_transition=rows[-1],
        )
    except (OSError, TypeError, ValueError) as exc:
        raise MaterializationError(f"terminal successor verification failed: {exc}") from exc
    if _sha256_stable(recording) != artifact.hdf5_sha256:
        raise MaterializationError("native recording changed during extraction")
    session = artifact.manifest.get("session_metadata")
    if not isinstance(session, dict):
        raise MaterializationError("native recording has no session metadata")
    row_episode_id = _decode_text(rows[0]["episode_id"])
    if session.get("episode_id") != row_episode_id:
        raise MaterializationError("native row episode identity disagrees with recording manifest")
    source = {
        "recording": str(recording),
        "recording_sha256": artifact.hdf5_sha256,
        "episode": selected,
        "episode_id": row_episode_id,
        "run_id": _decode_text(rows[0]["run_id"]),
        "session_id": _decode_text(rows[0]["session_id"]),
        "source_profile": session.get("source_profile"),
        "task": session.get("task"),
        "execution_profile": session.get("execution_profile"),
        "outcome": artifact.outcome,
        "stage_snapshot_sha256": artifact.snapshot_sha256,
        "asset_closure_sha256": artifact.asset_closure_sha256,
        "visual_provenance_sha256": artifact.visual_provenance_sha256,
        "terminal_successor_sha256": artifact.terminal_successor_sha256,
        "visual_identity": {
            "camera_roles": {
                str(camera["role"]): {
                    "prim_path": camera["prim_path"],
                    "camera_configuration_sha256": camera["camera_configuration_sha256"],
                    "resolution": camera["resolution"],
                }
                for camera in artifact.visual_provenance["camera_roles"]
            },
            "renderer_configuration_sha256": artifact.visual_provenance["renderer"][
                "renderer_configuration_sha256"
            ],
            "materialization_revision": artifact.visual_provenance["materialization"][
                "materialization_revision"
            ],
        },
    }
    return _write_projection_bundle(output, arrays, source)


def _load_rgb(path: Path, declared_sha256: str,
              image_shape: tuple[int, int, int] = IMAGE_SHAPE) -> np.ndarray:
    if not path.is_file():
        raise MaterializationError(f"materialized RGB file is missing: {path}")
    actual_sha256 = _sha256_stable(path)
    if actual_sha256 != declared_sha256:
        raise MaterializationError(
            f"materialized RGB digest mismatch for {path}: "
            f"expected {declared_sha256}, got {actual_sha256}"
        )
    try:
        from PIL import Image

        with Image.open(path) as image:
            array = np.asarray(image)
    except (OSError, ValueError) as exc:
        raise MaterializationError(f"materialized RGB is unreadable: {path}") from exc
    if array.dtype != np.uint8 or array.shape != image_shape:
        raise MaterializationError(
            f"materialized RGB must be uint8{image_shape}, got {array.dtype}{array.shape}"
        )
    if _sha256_stable(path) != declared_sha256:
        raise MaterializationError(f"materialized RGB changed while it was decoded: {path}")
    return np.array(array, copy=True)


def _validated_image_join(
    report_path: Path,
    bundle_manifest: Mapping[str, Any],
    arrays: Mapping[str, np.ndarray],
) -> tuple[Mapping[tuple[str, str, str], Mapping[str, Any]], dict[str, Any]]:
    """Validate all image identities and file digests without decoding pixels."""
    report_path = report_path.expanduser().resolve()
    report_sha256 = _sha256_stable(report_path)
    report = _load_json_object(report_path, label="replay report")
    if report.get("schema") != REPLAY_SCHEMA:
        raise MaterializationError("replay report is not schema v3")
    if report.get("physics_callbacks") != 0:
        raise MaterializationError("replay report observed physics callbacks")
    if report.get("strict_policy") is not True or report.get("native_action_replay") is not False:
        raise MaterializationError("replay report did not use strict state-only replay")
    frames = _validate_projection_arrays(arrays)
    source = bundle_manifest["source"]
    image_shape = _source_image_shape(source)
    expected_top = {
        "recording_sha256": source["recording_sha256"],
        "stage_snapshot_sha256": source["stage_snapshot_sha256"],
        "asset_closure_sha256": source["asset_closure_sha256"],
        "visual_provenance_sha256": source["visual_provenance_sha256"],
        "terminal_successor_sha256": source["terminal_successor_sha256"],
        "episode": source["episode"],
        "frames_applied": frames,
    }
    for field, expected in expected_top.items():
        if report.get(field) != expected:
            raise MaterializationError(f"replay report {field} does not match projection source")
    renders = report.get("renders")
    if not isinstance(renders, list):
        raise MaterializationError("replay report renders must be a list")
    camera_paths = report.get("camera_paths")
    if not isinstance(camera_paths, dict) or set(camera_paths) != set(CAMERA_ROLES):
        raise MaterializationError("replay report camera role mapping is incomplete")
    visual_identity = source["visual_identity"]
    expected_cameras = visual_identity["camera_roles"]
    expected_renderer = visual_identity["renderer_configuration_sha256"]
    expected_materialization = visual_identity["materialization_revision"]
    if camera_paths != {role: expected_cameras[role]["prim_path"] for role in CAMERA_ROLES}:
        raise MaterializationError("replay report camera paths differ from recorded provenance")

    joined: dict[tuple[str, str, str], Mapping[str, Any]] = {}
    per_role_hashes = {role: set() for role in CAMERA_ROLES}
    for index, raw in enumerate(renders):
        if not isinstance(raw, dict):
            raise MaterializationError(f"replay render {index} is not an object")
        for field in IMAGE_IDENTITY_FIELDS:
            if field not in raw:
                raise MaterializationError(f"replay render {index} lacks identity field {field}")
        role = raw["camera_role"]
        if role not in CAMERA_ROLES or raw.get("role") != role:
            raise MaterializationError(f"replay render {index} has an invalid camera role")
        obs_id = raw["obs_id"]
        snapshot_sha256 = _require_sha256(
            raw["scene_state_snapshot_sha256"],
            field=f"replay.renders[{index}].scene_state_snapshot_sha256",
        )
        if not isinstance(obs_id, str) or not obs_id:
            raise MaterializationError(f"replay render {index} has an invalid obs_id")
        key = (obs_id, snapshot_sha256, role)
        if key in joined:
            raise MaterializationError(f"replay report duplicates immutable image identity {key}")
        for field in (
            "camera_configuration_sha256",
            "renderer_configuration_sha256",
            "stage_snapshot_sha256",
            "asset_closure_sha256",
            "rgb_sha256",
            "sha256",
        ):
            _require_sha256(raw.get(field), field=f"replay.renders[{index}].{field}")
        if raw["rgb_sha256"] != raw["sha256"]:
            raise MaterializationError(f"replay render {index} has divergent RGB digests")
        if raw["stage_snapshot_sha256"] != source["stage_snapshot_sha256"]:
            raise MaterializationError(f"replay render {index} has the wrong stage snapshot")
        if raw["asset_closure_sha256"] != source["asset_closure_sha256"]:
            raise MaterializationError(f"replay render {index} has the wrong asset closure")
        if raw["camera_prim_path"] != camera_paths[role]:
            raise MaterializationError(f"replay render {index} has the wrong camera prim path")
        if (
            raw["camera_configuration_sha256"]
            != expected_cameras[role]["camera_configuration_sha256"]
        ):
            raise MaterializationError(f"replay render {index} has the wrong camera configuration")
        if raw["renderer_configuration_sha256"] != expected_renderer:
            raise MaterializationError(
                f"replay render {index} has the wrong renderer configuration"
            )
        if raw["materialization_revision"] != expected_materialization:
            raise MaterializationError(
                f"replay render {index} has the wrong materialization revision"
            )
        if raw.get("dtype") != "uint8" or raw.get("shape") != list(image_shape):
            raise MaterializationError(f"replay render {index} has the wrong RGB type or shape")
        if (
            not isinstance(raw["scene_state_snapshot_id"], str)
            or not raw["scene_state_snapshot_id"]
        ):
            raise MaterializationError(f"replay render {index} has an invalid snapshot ID")
        if (
            not isinstance(raw["materialization_revision"], str)
            or not raw["materialization_revision"]
        ):
            raise MaterializationError(f"replay render {index} has no materialization revision")
        image_path = Path(raw.get("path", "")).expanduser().resolve()
        if not image_path.is_file():
            raise MaterializationError(f"materialized RGB file is missing: {image_path}")
        actual_sha256 = _sha256_stable(image_path)
        if actual_sha256 != raw["rgb_sha256"]:
            raise MaterializationError(
                f"materialized RGB digest mismatch for {image_path}: "
                f"expected {raw['rgb_sha256']}, got {actual_sha256}"
            )
        joined[key] = MappingProxyType(
            {
                **{field: raw[field] for field in IMAGE_IDENTITY_FIELDS},
                "frame": raw.get("frame"),
                "role": raw["role"],
                "path": str(image_path),
                "dtype": raw["dtype"],
                "shape": tuple(raw["shape"]),
                "sha256": raw["sha256"],
            }
        )
        per_role_hashes[role].add(raw["rgb_sha256"])

    expected_keys: set[tuple[str, str, str]] = set()
    for frame in range(frames):
        obs_id = str(arrays["obs_id"][frame])
        snapshot_id = str(arrays["scene_state_snapshot_id"][frame])
        snapshot_sha256 = str(arrays["scene_state_snapshot_sha256"][frame])
        for role in CAMERA_ROLES:
            key = (obs_id, snapshot_sha256, role)
            expected_keys.add(key)
            item = joined.get(key)
            if item is None:
                continue
            if item["scene_state_snapshot_id"] != snapshot_id:
                raise MaterializationError(f"replay image {key} has a mismatched snapshot ID")
            if item.get("frame") != frame:
                raise MaterializationError(f"replay image {key} has a mismatched diagnostic frame")
    if set(joined) != expected_keys:
        missing = sorted(expected_keys - set(joined))
        extra = sorted(set(joined) - expected_keys)
        raise MaterializationError(
            f"replay RGB identity coverage mismatch: missing={missing}, extra={extra}"
        )
    renderer_digests = {str(item["renderer_configuration_sha256"]) for item in joined.values()}
    materialization_revisions = {str(item["materialization_revision"]) for item in joined.values()}
    if len(renderer_digests) != 1:
        raise MaterializationError("replay images use inconsistent renderer configurations")
    if len(materialization_revisions) != 1:
        raise MaterializationError("replay images use inconsistent materialization revisions")
    for role in CAMERA_ROLES:
        configurations = {
            str(item["camera_configuration_sha256"])
            for item in joined.values()
            if item["camera_role"] == role
        }
        if len(configurations) != 1:
            raise MaterializationError(
                f"replay images use inconsistent camera configurations for {role}"
            )
    # Equal PNG digests are a useful QA lead, not evidence of stale geometry:
    # a static camera facing an unchanged scene may legitimately repeat bytes.
    # The separate spatial alignment assay supplies an independent moving
    # witness when liveness is actually required.
    frozen = [role for role, hashes in per_role_hashes.items() if frames > 1 and len(hashes) == 1]
    report["_identical_rgb_digest_roles"] = frozen
    if _sha256_stable(report_path) != report_sha256:
        raise MaterializationError("replay report changed while its images were verified")
    report["_verified_file_sha256"] = report_sha256
    return MappingProxyType(joined), report


def _add_projection_frame(
    dataset: Any,
    frame: int,
    arrays: Mapping[str, np.ndarray],
    images: Mapping[tuple[str, str, str], Mapping[str, Any]],
    task: str,
) -> None:
    """Decode only this frame's three RGB images, then release caller references."""
    obs_id = str(arrays["obs_id"][frame])
    snapshot_sha256 = str(arrays["scene_state_snapshot_sha256"][frame])
    sample: dict[str, Any] = {
        "observation.state": np.array(arrays["observation_state"][frame], copy=True),
        "action": np.array(arrays["action"][frame], copy=True),
        "task": task,
    }
    for role in CAMERA_ROLES:
        entry = images[(obs_id, snapshot_sha256, role)]
        sample[f"observation.images.{role}"] = _load_rgb(
            Path(entry["path"]), entry["rgb_sha256"], tuple(entry["shape"])
        )
    dataset.add_frame(sample)
    # With the pinned synchronous LeRobot writer, add_frame has persisted each
    # image to a temporary PNG and retains only its path in episode_buffer.
    del sample


def canonical_lerobot_features(
    image_shape: tuple[int, int, int] = IMAGE_SHAPE,
) -> dict[str, dict[str, Any]]:
    features: dict[str, dict[str, Any]] = {
        "observation.state": {
            "dtype": "float32",
            "shape": VECTOR_SHAPE,
            "names": list(JOINT_NAMES),
        }
    }
    for role in CAMERA_ROLES:
        features[f"observation.images.{role}"] = {
            "dtype": "video",
            "shape": image_shape,
            "names": ["height", "width", "channel"],
        }
    features["action"] = {
        "dtype": "float32",
        "shape": VECTOR_SHAPE,
        "names": list(JOINT_NAMES),
    }
    return features


def _qa_lerobot_dataset(
    root: Path,
    *,
    repo_id: str,
    arrays: Mapping[str, np.ndarray],
    task: str,
    image_shape: tuple[int, int, int] = IMAGE_SHAPE,
) -> dict[str, Any]:
    import torch
    from torch.utils.data import DataLoader

    from lerobot.datasets.lerobot_dataset import LeRobotDataset

    dataset = LeRobotDataset(repo_id, root=root, video_backend="pyav")
    frames = _validate_projection_arrays(arrays)
    if len(dataset) != frames:
        raise MaterializationError(
            f"LeRobot full-read frame count mismatch: expected {frames}, got {len(dataset)}"
        )
    expected_features = canonical_lerobot_features()
    for key, expected in expected_features.items():
        actual = dataset.features.get(key)
        if not isinstance(actual, dict):
            raise MaterializationError(f"LeRobot dataset lacks canonical feature {key}")
        for field in ("dtype", "shape", "names"):
            actual_value = tuple(actual[field]) if field == "shape" else actual[field]
            expected_value = tuple(expected[field]) if field == "shape" else expected[field]
            if actual_value != expected_value:
                raise MaterializationError(f"LeRobot feature {key}.{field} differs from schema")

    decoded = 0
    for index in range(frames):
        frame = dataset[index]
        state = frame["observation.state"]
        action = frame["action"]
        if state.dtype != torch.float32 or tuple(state.shape) != VECTOR_SHAPE:
            raise MaterializationError(f"LeRobot frame {index} has an invalid state tensor")
        if action.dtype != torch.float32 or tuple(action.shape) != VECTOR_SHAPE:
            raise MaterializationError(f"LeRobot frame {index} has an invalid action tensor")
        if not torch.isfinite(state).all() or not torch.isfinite(action).all():
            raise MaterializationError(f"LeRobot frame {index} contains NaN or Inf")
        if not np.array_equal(state.numpy(), arrays["observation_state"][index]):
            raise MaterializationError(f"LeRobot frame {index} state changed during persistence")
        if not np.array_equal(action.numpy(), arrays["action"][index]):
            raise MaterializationError(f"LeRobot frame {index} action changed during persistence")
        if frame.get("task") != task:
            raise MaterializationError(f"LeRobot frame {index} task identity mismatch")
        if int(frame["frame_index"].item()) != index:
            raise MaterializationError(f"LeRobot frame {index} has a non-dense logical index")
        expected_time = np.float32(index / FPS)
        if frame["timestamp"].item() != expected_time.item():
            raise MaterializationError(f"LeRobot frame {index} has a wrong logical timestamp")
        for role in CAMERA_ROLES:
            image = frame[f"observation.images.{role}"]
            if image.dtype != torch.float32 or tuple(image.shape) != (3, image_shape[0], image_shape[1]):
                raise MaterializationError(f"LeRobot frame {index} {role} decode shape mismatch")
            if not torch.isfinite(image).all() or image.min().item() < 0 or image.max().item() > 1:
                raise MaterializationError(f"LeRobot frame {index} {role} decode range mismatch")
            decoded += 1

    loader = DataLoader(dataset, batch_size=min(2, frames), shuffle=False, num_workers=0)
    loader_frames = 0
    loader_batches = 0
    for batch in loader:
        batch_size = int(batch["observation.state"].shape[0])
        if tuple(batch["observation.state"].shape[1:]) != VECTOR_SHAPE:
            raise MaterializationError("DataLoader state batch shape mismatch")
        if tuple(batch["action"].shape[1:]) != VECTOR_SHAPE:
            raise MaterializationError("DataLoader action batch shape mismatch")
        for role in CAMERA_ROLES:
            image = batch[f"observation.images.{role}"]
            if tuple(image.shape[1:]) != (3, image_shape[0], image_shape[1]) or image.dtype != torch.float32:
                raise MaterializationError(f"DataLoader {role} batch shape mismatch")
        if list(batch["task"]) != [task] * batch_size:
            raise MaterializationError("DataLoader task batch mismatch")
        loader_frames += batch_size
        loader_batches += 1
    if loader_frames != frames:
        raise MaterializationError("DataLoader did not visit every frame")
    return {
        "all_frames_read": frames,
        "all_video_frames_decoded": decoded,
        "dataloader_batches": loader_batches,
        "dataloader_frames": loader_frames,
    }


def _dataset_file_digests(root: Path) -> list[dict[str, Any]]:
    files: list[dict[str, Any]] = []
    for path in sorted(root.rglob("*")):
        if path.is_symlink():
            raise MaterializationError(f"materialized dataset contains a symlink: {path}")
        if not path.is_file() or path.name == MATERIALIZATION_MANIFEST:
            continue
        files.append(
            {
                "path": path.relative_to(root).as_posix(),
                "size_bytes": path.stat().st_size,
                "sha256": _sha256_stable(path),
            }
        )
    if not files:
        raise MaterializationError("materialized dataset contains no files")
    return files


def verify_materialization_manifest(root: Path) -> dict[str, Any]:
    root = root.expanduser().resolve()
    manifest = _load_json_object(root / MATERIALIZATION_MANIFEST, label="materialization manifest")
    if manifest.get("schema") != MATERIALIZATION_SCHEMA:
        raise MaterializationError("unsupported materialization manifest schema")
    declared_self = _require_sha256(
        manifest.get("manifest_sha256"), field="materialization manifest_sha256"
    )
    payload = dict(manifest)
    del payload["manifest_sha256"]
    if _canonical_sha256(payload) != declared_self:
        raise MaterializationError("materialization manifest self-hash mismatch")
    declared_files = manifest.get("files")
    if not isinstance(declared_files, list):
        raise MaterializationError("materialization manifest files must be a list")
    if declared_files != _dataset_file_digests(root):
        raise MaterializationError("materialized dataset file inventory or digest mismatch")
    return manifest


def materialize_projection(
    *,
    bundle: Path,
    replay_report: Path,
    output: Path,
    repo_id: str,
    task_id: str,
) -> dict[str, Any]:
    if not repo_id or "/" not in repo_id:
        raise MaterializationError("repo_id must be a non-empty namespace/name")
    bundle_path = bundle.expanduser().resolve()
    report_path = replay_report.expanduser().resolve()
    bundle_manifest, arrays = verify_projection_bundle(bundle_path)
    image_shape = _source_image_shape(bundle_manifest["source"])
    source_task_id = bundle_manifest["source"].get("task")
    if task_id != source_task_id:
        raise MaterializationError(
            f"task_id {task_id!r} does not match recorded task {source_task_id!r}"
        )
    task = TASK_LABELS.get(task_id)
    if task is None:
        raise MaterializationError(f"recorded task {task_id!r} has no controlled label mapping")
    images, report = _validated_image_join(report_path, bundle_manifest, arrays)
    frames = _validate_projection_arrays(arrays)

    target = output.expanduser().resolve(strict=False)
    temporary = _atomic_directory(target)
    # LeRobot's create API deliberately requires an absent root.  Reserve a
    # collision-resistant sibling name above, then let LeRobot create it.
    temporary.rmdir()
    try:
        from lerobot.datasets.lerobot_dataset import LeRobotDataset

        dataset = LeRobotDataset.create(
            repo_id=repo_id,
            fps=FPS,
            features=canonical_lerobot_features(image_shape),
            root=temporary,
            use_videos=True,
            video_backend="pyav",
        )
        temporary.chmod(0o700)
        for frame in range(frames):
            _add_projection_frame(dataset, frame, arrays, images, task)
        dataset.save_episode(parallel_encoding=False)
        dataset.finalize()
        qa = _qa_lerobot_dataset(
            temporary,
            repo_id=repo_id,
            arrays=arrays,
            task=task,
            image_shape=image_shape,
        )
        join_ledger = []
        for frame in range(frames):
            obs_id = str(arrays["obs_id"][frame])
            snapshot_sha256 = str(arrays["scene_state_snapshot_sha256"][frame])
            join_ledger.append(
                {
                    "frame_index": int(arrays["frame_index"][frame]),
                    "obs_id": obs_id,
                    "scene_state_snapshot_id": str(arrays["scene_state_snapshot_id"][frame]),
                    "scene_state_snapshot_sha256": snapshot_sha256,
                    "transition_id": str(arrays["transition_id"][frame]),
                    "observation_state_sha256": hashlib.sha256(
                        np.asarray(arrays["observation_state"][frame], dtype="<f4").tobytes()
                    ).hexdigest(),
                    "action_sha256": hashlib.sha256(
                        np.asarray(arrays["action"][frame], dtype="<f4").tobytes()
                    ).hexdigest(),
                    "images": {
                        role: {
                            **{
                                field: images[(obs_id, snapshot_sha256, role)][field]
                                for field in IMAGE_IDENTITY_FIELDS
                            },
                            "source_path": images[(obs_id, snapshot_sha256, role)]["path"],
                        }
                        for role in CAMERA_ROLES
                    },
                }
            )
        report_sha256 = report.pop("_verified_file_sha256")
        identical_digest_roles = report.pop("_identical_rgb_digest_roles")
        manifest: dict[str, Any] = {
            "schema": MATERIALIZATION_SCHEMA,
            "conversion_revision": CONVERSION_REVISION,
            "schema_fingerprint_sha256": bundle_manifest["schema_fingerprint_sha256"],
            "repo_id": repo_id,
            "fps": FPS,
            "frames": frames,
            "episodes": 1,
            "task_id": task_id,
            "task_label": task,
            "task_label_revision": TASK_LABEL_REVISION,
            "task_label_sha256": hashlib.sha256(task.encode("utf-8")).hexdigest(),
            "canonical_feature_order": [
                "observation.state",
                *(f"observation.images.{role}" for role in CAMERA_ROLES),
                "task",
                "action",
            ],
            "source": {
                **bundle_manifest["source"],
                "projection_manifest_sha256": bundle_manifest["manifest_sha256"],
                "projection_payload_sha256": bundle_manifest["projection"]["sha256"],
                "replay_report": str(report_path),
                "replay_report_sha256": report_sha256,
                "replay_schema": report["schema"],
            },
            "admission": {
                "dataset_admissible": False,
                "blocking_reasons": ["requires_demo_admission_decision"],
            },
            "row_outcomes": [
                {
                    "frame_index": int(arrays["frame_index"][frame]),
                    "transition_id": str(arrays["transition_id"][frame]),
                    "transition_outcome": str(arrays["transition_outcome"][frame]),
                    "terminated": bool(arrays["terminated"][frame]),
                    "success": bool(arrays["success"][frame]),
                }
                for frame in range(frames)
            ],
            "image_join": {
                "key": ["obs_id", "scene_state_snapshot_sha256", "camera_role"],
                "positional_join": False,
                "verified_identities": len(images),
                "required_identity_fields": list(IMAGE_IDENTITY_FIELDS),
            },
            "projection_image_join_ledger": join_ledger,
            "qa": {**qa, "identical_rgb_digest_roles": identical_digest_roles},
            "files": _dataset_file_digests(temporary),
        }
        manifest["manifest_sha256"] = _canonical_sha256(manifest)
        _write_json(temporary / MATERIALIZATION_MANIFEST, manifest)
        verify_materialization_manifest(temporary)
        if _sha256_stable(report_path) != report_sha256:
            raise MaterializationError("replay report changed during materialization")
        _publish_directory(temporary, target)
    except BaseException:
        shutil.rmtree(temporary, ignore_errors=True)
        raise
    return verify_materialization_manifest(target)


def _portable_root(value: str) -> tuple[str, Path]:
    if "=" not in value:
        raise argparse.ArgumentTypeError("portable root must be NAME=PATH")
    name, raw_path = value.split("=", 1)
    if not re.fullmatch(r"[a-z0-9][a-z0-9._-]*", name):
        raise argparse.ArgumentTypeError(f"invalid portable root name: {name!r}")
    if not raw_path:
        raise argparse.ArgumentTypeError("portable root path is empty")
    return name, Path(raw_path).expanduser().resolve()


def _portable_root_map(values: Iterable[tuple[str, Path]]) -> dict[str, Path]:
    roots: dict[str, Path] = {}
    for name, path in values:
        if name in roots:
            raise MaterializationError(f"portable root {name!r} was supplied more than once")
        roots[name] = path
    if not roots:
        raise MaterializationError("at least one --portable-root NAME=PATH is required")
    return roots


def _add_extract_arguments(parser: argparse.ArgumentParser) -> None:
    parser.add_argument("--recording", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--episode")
    parser.add_argument(
        "--portable-root",
        action="append",
        default=[],
        type=_portable_root,
        metavar="NAME=PATH",
        help="repeat for every portable asset-closure root",
    )


def _add_materialize_arguments(parser: argparse.ArgumentParser) -> None:
    parser.add_argument("--bundle", type=Path, required=True)
    parser.add_argument("--replay-report", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--repo-id", required=True)
    parser.add_argument("--task-id", required=True)


def parse_args(argv: Sequence[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__, allow_abbrev=False)
    subparsers = parser.add_subparsers(dest="command", required=True)
    extract = subparsers.add_parser("extract", help="verify HDF and emit a projection bundle")
    _add_extract_arguments(extract)
    materialize = subparsers.add_parser(
        "materialize", help="join replay RGB and create a LeRobotDataset v3"
    )
    _add_materialize_arguments(materialize)
    orchestrate = subparsers.add_parser(
        "orchestrate", help="run extraction in an explicit Python, then materialize here"
    )
    orchestrate.add_argument("--extract-python", type=Path, required=True)
    orchestrate.add_argument("--recording", type=Path, required=True)
    orchestrate.add_argument("--replay-report", type=Path, required=True)
    orchestrate.add_argument("--output", type=Path, required=True)
    orchestrate.add_argument("--repo-id", required=True)
    orchestrate.add_argument("--task-id", required=True)
    orchestrate.add_argument("--episode")
    orchestrate.add_argument(
        "--portable-root",
        action="append",
        default=[],
        type=_portable_root,
        metavar="NAME=PATH",
    )
    return parser.parse_args(argv)


def main(argv: Sequence[str] | None = None) -> int:
    args = parse_args(argv)
    if args.command == "extract":
        result = extract_projection(
            recording=args.recording,
            output=args.output,
            portable_roots=_portable_root_map(args.portable_root),
            episode=args.episode,
        )
    elif args.command == "materialize":
        result = materialize_projection(
            bundle=args.bundle,
            replay_report=args.replay_report,
            output=args.output,
            repo_id=args.repo_id,
            task_id=args.task_id,
        )
    else:
        roots = _portable_root_map(args.portable_root)
        # Do not resolve this path: venv ``python`` is commonly a symlink to the
        # base interpreter, and resolving it would silently discard the venv.
        extract_python = args.extract_python.expanduser()
        if not extract_python.is_absolute():
            extract_python = Path.cwd() / extract_python
        if not extract_python.is_file():
            raise MaterializationError(f"extract interpreter does not exist: {extract_python}")
        with tempfile.TemporaryDirectory(prefix="isaac-vr-projection-") as temp:
            bundle = Path(temp) / "bundle"
            command = [
                str(extract_python),
                str(Path(__file__).resolve()),
                "extract",
                "--recording",
                str(args.recording),
                "--output",
                str(bundle),
            ]
            if args.episode is not None:
                command.extend(("--episode", args.episode))
            for name, path in roots.items():
                command.extend(("--portable-root", f"{name}={path}"))
            subprocess.run(command, check=True)
            result = materialize_projection(
                bundle=bundle,
                replay_report=args.replay_report,
                output=args.output,
                repo_id=args.repo_id,
                task_id=args.task_id,
            )
    print("ISAAC_VR_LEROBOT_RESULT=" + json.dumps(result, sort_keys=True), flush=True)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Explicit RTX topology for shared-world SceneUI, Kit >=110.3 only."""
from __future__ import annotations

PREVIEW = "vla_xr_preview"
SENSOR = "vla_sensor_world"


class PreviewPartitions:
    def __init__(self, stage):
        import carb.settings
        import omni.kit.app
        from omni.kit.scene_view.xr import XRSceneView
        from pxr import Sdf

        version = omni.kit.app.get_app().get_kit_version()
        if tuple(int(n) for n in version.split('+')[0].split('.')[:2]) < (110, 3):
            raise RuntimeError(f"Preview isolation requires Kit >=110.3, got {version}")
        self.stage = stage
        self.settings = carb.settings.get_settings()
        self.base = str(XRSceneView.get_base_path())
        path = Sdf.Path(self.base)
        if not path.IsAbsolutePath() or path == Sdf.Path('/') or path.HasPrefix(Sdf.Path('/World')):
            raise RuntimeError(f"Unsafe XR UI partition root: {self.base}")
        self.camera_paths = []
        self.panel_paths = set()
        self.authored_panel_paths = set()

    def bind_sensors(self, cameras, *, concrete_paths=None):
        from pxr import Sdf, Usd, UsdGeom
        for prim in self.stage.Traverse():
            if prim.GetPath().HasPrefix(Sdf.Path('/World')) and prim.IsA(UsdGeom.Gprim):
                pv = UsdGeom.PrimvarsAPI(prim).FindPrimvarWithInheritance('omni:scenePartition')
                if pv and pv.Get():
                    raise RuntimeError(f"Expected unpartitioned demo world: {prim.GetPath()}")
        self.camera_paths = list(concrete_paths) if concrete_paths is not None else [camera.cfg.prim_path for camera in cameras]
        with Usd.EditContext(self.stage, self.stage.GetSessionLayer()):
            for path in self.camera_paths:
                prim = self.stage.GetPrimAtPath(path)
                if not prim or not prim.IsA(UsdGeom.Camera):
                    raise RuntimeError(f"Missing sensor camera: {path}")
                old = prim.GetAttribute('omni:scenePartition')
                if old and old.Get() not in (None, '', SENSOR):
                    raise RuntimeError(f"Conflicting sensor partition: {path}")
                prim.CreateAttribute('omni:scenePartition', Sdf.ValueTypeNames.Token).Set(SENSOR)
        self.assert_valid()

    def assert_valid(self):
        from pxr import Usd, UsdGeom
        for setting in ('/renderer/scenePartitioning/enabled',
                        '/rtx/scenePartitioning/showAllPartitionsByDefault'):
            if self.settings.get(setting) is not True:
                raise RuntimeError(f"Preview isolation setting lost: {setting}")
        for path in self.panel_paths:
            root = self.stage.GetPrimAtPath(path)
            if not root or UsdGeom.PrimvarsAPI(root).GetPrimvar('omni:scenePartition').Get() != PREVIEW:
                raise RuntimeError(f'Preview isolation lost: {path}; rebind before rendering')
            for child in Usd.PrimRange(root):
                if child.IsA(UsdGeom.Gprim):
                    pv = UsdGeom.PrimvarsAPI(child).FindPrimvarWithInheritance('omni:scenePartition')
                    if not pv or pv.Get() != PREVIEW:
                        raise RuntimeError(f'Preview descendant escaped partition: {child.GetPath()}')
        for path in self.camera_paths:
            prim = self.stage.GetPrimAtPath(path)
            if not prim or prim.GetAttribute('omni:scenePartition').Get() != SENSOR:
                raise RuntimeError(f"Sensor isolation lost: {path}; rebind before rendering")
        xr_camera = self.stage.GetPrimAtPath('/_xr/stage/xrCamera')
        if xr_camera:
            token = xr_camera.GetAttribute('omni:scenePartition')
            if token and token.Get() not in (None, '', PREVIEW):
                raise RuntimeError('XR camera partition cannot see preview UI')

    def check_panel(self, panel):
        from pxr import Sdf, Usd, UsdGeom
        view = panel._container.scene_view
        # Public scene-to-USD update, NOT an app/render tick. Bind the concrete
        # draw system before the first render and every time it is shown again.
        # Tagging /ui once was empirically insufficient for dynamic SceneUI.
        view.run_update()
        path = Sdf.Path(str(view.system_path))
        if not path.HasPrefix(Sdf.Path(self.base)) or path == Sdf.Path(self.base):
            raise RuntimeError(f'Unexpected preview draw system: {path}')
        with Usd.EditContext(self.stage, self.stage.GetSessionLayer()):
            root = self.stage.OverridePrim(path)
            UsdGeom.PrimvarsAPI(root).CreatePrimvar('omni:scenePartition',
                Sdf.ValueTypeNames.Token, UsdGeom.Tokens.constant).Set(PREVIEW)
        self.panel_paths.add(str(path))
        self.authored_panel_paths.add(str(path))
        self.assert_valid()

    def release_panel(self, panel):
        # Closing/hiding destroys the draw system. A future show must bind it
        # again before rendering; do not keep asserting a removed resource.
        self.panel_paths.discard(str(panel._container.scene_view.system_path))

    def report(self):
        return {'enabled': True, 'ui_base': self.base, 'panel_roots': sorted(self.authored_panel_paths),
                'active_panel_roots': sorted(self.panel_paths), 'preview_token': PREVIEW,
                'sensor_token': SENSOR, 'sensor_paths': self.camera_paths,
                'world': 'unpartitioned/shared', 'xr': 'unassigned spectator, showAllPartitionsByDefault=true'}

"""Seed the opt-in CPU PhysX worker from the live native scene, without stepping.

Only derived artifacts are written. Native tensors are read once at one frozen
boundary; the exported scene and its Newton mimic schemas remain unchanged.
"""

from __future__ import annotations

import hashlib
import json
from pathlib import Path

import numpy as np

from tools.isaac_vr_standalone_ik import BODIES, DOFS


def _sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def _array(value, shape) -> np.ndarray:
    if hasattr(value, "detach"):
        value = value.detach().cpu().numpy()
    elif hasattr(value, "numpy"):
        value = value.numpy()
    result = np.asarray(value, dtype=np.float32)
    if result.shape != shape or not np.isfinite(result).all():
        raise ValueError(f"Expected finite native array {shape}; got {result.shape}")
    return result.copy()


def _matrix_pose(matrix) -> np.ndarray:
    from pxr import Gf

    m = np.asarray(matrix, dtype=np.float64)
    if (
        m.shape != (4, 4)
        or not np.isfinite(m).all()
        or not np.allclose(m[:3, :3] @ m[:3, :3].T, np.eye(3), atol=1e-5, rtol=0)
        or not np.isclose(np.linalg.det(m[:3, :3]), 1, atol=1e-5)
        or not np.allclose(m[:, 3], [0, 0, 0, 1], atol=1e-7, rtol=0)
    ):
        raise ValueError("Pose mapping requires a rigid, unit-scale USD transform")
    rotation = Gf.Transform(Gf.Matrix4d(m.tolist())).GetRotation().GetQuat()
    return np.asarray([*m[3, :3], rotation.GetReal(), *rotation.GetImaginary()], np.float32)


class SnapshotPoses:
    """Resolve bodies, static containers and fixed camera mounts from one snapshot.

    All matrices use USD row-vector convention. No runtime USD/Fabric pose reads.
    Mutable mount/intrinsics/topology changes require a new seed/epoch.
    """

    def __init__(self, snapshot: Path, rigid_body_paths: list[str]):
        from pxr import Usd, UsdGeom

        if len(set(rigid_body_paths)) != len(rigid_body_paths):
            raise ValueError("Duplicate rigid body paths")
        self.body_paths = tuple(rigid_body_paths)
        self._body_index = {p: i for i, p in enumerate(self.body_paths)}
        stage = Usd.Stage.Open(str(Path(snapshot).resolve()))
        if not stage:
            raise ValueError("Cannot open source snapshot")
        cache = UsdGeom.XformCache()
        self._world = {
            str(prim.GetPath()): np.asarray(cache.GetLocalToWorldTransform(prim), np.float64)
            for prim in stage.Traverse()
            if prim.IsA(UsdGeom.Xformable)
        }
        self._reset_paths = {
            str(prim.GetPath())
            for prim in stage.Traverse()
            if prim.IsA(UsdGeom.Xformable) and UsdGeom.Xformable(prim).GetResetXformStack()
        }
        if not set(self.body_paths).issubset(self._world):
            raise ValueError("Source snapshot lacks required rigid body transforms")
        self._resolved: dict[str, tuple[int | None, np.ndarray]] = {}
        self._batches = {}

    def poses(self, paths, rigid_body_world_pose_xyzw) -> np.ndarray:
        values = _array(rigid_body_world_pose_xyzw, (len(self.body_paths), 7))
        if not np.allclose(np.linalg.norm(values[:, 3:], axis=1), 1, atol=1e-4, rtol=0):
            raise ValueError("Nonunit native world quaternion")
        paths = tuple(map(str, paths))
        if paths not in self._batches:
            for path in paths:
                if path in self._resolved:
                    continue
                if path not in self._world:
                    raise ValueError(f"Unseeded requested pose path: {path}")
                parent = path
                while parent and parent not in self._body_index:
                    if parent in self._reset_paths:
                        raise ValueError(
                            f"Unsupported reset transform in mounted pose path: {path}"
                        )
                    parent = parent.rsplit("/", 1)[0]
                if parent:
                    index = self._body_index[parent]
                    relative = self._world[path] @ np.linalg.inv(self._world[parent])
                else:
                    index, relative = None, self._world[path]
                self._resolved[path] = index, _matrix_pose(relative)
            rows = [self._resolved[p] for p in paths]
            indices = np.array([0 if i is None else i for i, _ in rows], dtype=int)
            dynamic = np.array([i is not None for i, _ in rows], dtype=bool)
            local = np.array([p for _, p in rows], np.float32).reshape(len(paths), 7)
            self._batches[paths] = indices, dynamic, local
        indices, dynamic, local = self._batches[paths]
        base = values[indices]
        q, r = base[:, 3:], local[:, [4, 5, 6, 3]]  # Native xyzw; local wxyz.
        t = 2 * np.cross(q[:, :3], local[:, :3])
        positions = base[:, :3] + local[:, :3] + q[:, 3:] * t + np.cross(q[:, :3], t)
        xyz = q[:, 3:] * r[:, :3] + r[:, 3:] * q[:, :3] + np.cross(q[:, :3], r[:, :3])
        w = q[:, 3:] * r[:, 3:] - np.sum(q[:, :3] * r[:, :3], axis=1, keepdims=True)
        result = np.concatenate([positions, w, xyz], axis=1)
        result[~dynamic] = local[~dynamic]
        return np.ascontiguousarray(result, dtype=np.float32)


def _fixed_base_overlay(snapshot: Path, output: Path, mimics: list[dict]) -> tuple[Path, dict]:
    from pxr import Sdf, Usd, UsdGeom, UsdPhysics

    source_hash = _sha(snapshot)
    source = Usd.Stage.Open(str(snapshot))
    if not source:
        raise ValueError("Cannot open exported source scene")
    if UsdGeom.GetStageMetersPerUnit(source) != 1.0 or UsdGeom.GetStageUpAxis(source) != "Z":
        raise ValueError("Pinned Piper seed requires metre/Z stage metadata")
    overlay = output / "physics_fixed_base.usda"
    if overlay.exists():
        raise FileExistsError(overlay)
    layer = Sdf.Layer.CreateNew(str(overlay))
    layer.subLayerPaths = [str(snapshot)]
    stage = Usd.Stage.Open(layer)
    for key in ("metersPerUnit", "upAxis", "timeCodesPerSecond", "framesPerSecond"):
        if source.HasAuthoredMetadata(key):
            stage.SetMetadata(key, source.GetMetadata(key))
    if source.GetDefaultPrim():
        stage.SetDefaultPrim(stage.GetPrimAtPath(source.GetDefaultPrim().GetPath()))
    edits = []
    for side in ("Left", "Right"):
        base_path = f"/World/{side}Piper/Geometry/world/base_link"
        joint_path = f"/World/{side}Piper/Physics/world_to_base_link"
        base, joint = stage.GetPrimAtPath(base_path), stage.GetPrimAtPath(joint_path)
        if not base.HasAPI(UsdPhysics.ArticulationRootAPI) or not joint.IsA(UsdPhysics.FixedJoint):
            raise ValueError("Unexpected Piper root/world weld authoring")
        body0 = list(joint.GetRelationship("physics:body0").GetTargets())
        body1 = list(joint.GetRelationship("physics:body1").GetTargets())
        if [str(p) for p in body0] != [f"/World/{side}Piper"] or [str(p) for p in body1] != [
            base_path
        ]:
            raise ValueError("Unexpected world weld body relationships")
        old_schemas = base.GetMetadata("apiSchemas").GetAppliedItems()
        root_schemas = ["PhysicsArticulationRootAPI", "PhysxArticulationAPI"]
        if "NewtonArticulationRootAPI" in old_schemas:
            # This API includes PhysicsArticulationRootAPI as a built-in API.
            # Deleting the latter alone leaves a second effective root in Kit.
            root_schemas.append("NewtonArticulationRootAPI")
        newton_root_attributes = {}
        # Exact installed NewtonArticulationRootAPI property inventory; do not
        # move NewtonMassAPI/body/link attributes off their physical link.
        for name in ("newton:selfCollisionEnabled", "newton:jointsAddMobility"):
            attribute = base.GetAttribute(name)
            if attribute and attribute.HasAuthoredValueOpinion() and attribute.Get() is not None:
                newton_root_attributes[name] = (attribute.GetTypeName(), attribute.Get())
        for schema in root_schemas:
            base.RemoveAppliedSchema(schema)
            joint.AddAppliedSchema(schema)
        joint.GetRelationship("physics:body0").SetTargets([])
        for attribute in base.GetAttributes():
            if attribute.GetName().startswith("physxArticulation:") and attribute.Get() is not None:
                joint.CreateAttribute(
                    attribute.GetName(), attribute.GetTypeName(), custom=attribute.IsCustom()
                ).Set(attribute.Get())
        for name, (kind, value) in newton_root_attributes.items():
            joint.CreateAttribute(name, kind, custom=False).Set(value)
        edits.append(
            dict(
                old_root=base_path,
                new_root=joint_path,
                relocated_root_schemas=root_schemas,
                relocated_newton_root_attributes={
                    k: v[1] for k, v in newton_root_attributes.items()
                },
            )
        )
    mimic_edits = []
    for entry in mimics:
        follower = stage.GetPrimAtPath(entry["follower"])
        leader = stage.GetPrimAtPath(entry["leader"])
        if not follower.IsA(UsdPhysics.PrismaticJoint) or not leader.IsA(UsdPhysics.PrismaticJoint):
            raise ValueError("Reviewed mimic translation requires single-DOF prismatic joints")
        schemas = follower.GetMetadata("apiSchemas").GetAppliedItems()
        if any(str(name).startswith("PhysxMimicJointAPI:") for name in schemas):
            raise ValueError("Source already contains PhysX mimic; refusing duplicate constraint")
        # Pinned ovstage population did not enforce the original Newton schema.
        # This equivalent authoring was verified with passive follower drives in
        # a separate CPU-native fixture. Do not claim parity for a new seed yet.
        follower.RemoveAppliedSchema("NewtonMimicAPI")
        follower.AddAppliedSchema("PhysxMimicJointAPI:rotX")
        prefix = "physxMimicJoint:rotX:"
        for name, value in (
            ("gearing", -entry["mimicCoef1"]),
            ("offset", -entry["mimicCoef0"]),
            ("naturalFrequency", 0.0),
            ("dampingRatio", 0.0),
        ):
            follower.CreateAttribute(prefix + name, Sdf.ValueTypeNames.Float, custom=False).Set(
                value
            )
        follower.CreateAttribute(
            prefix + "referenceJointAxis", Sdf.ValueTypeNames.Token, custom=False
        ).Set("rotX")
        follower.CreateRelationship(prefix + "referenceJoint", custom=False).SetTargets(
            [entry["leader"]]
        )
        mimic_edits.append(
            dict(
                follower=entry["follower"],
                leader=entry["leader"],
                gearing=-entry["mimicCoef1"],
                offset=-entry["mimicCoef0"],
                source_equation="follower=coef0+coef1*leader",
                derived_equation="follower+gearing*leader+offset=0",
            )
        )
    layer.Save()
    reloaded = Usd.Stage.Open(str(overlay))
    before, after = UsdGeom.XformCache(), UsdGeom.XformCache()
    count = 0
    for prim in source.Traverse():
        if prim.IsA(UsdGeom.Xformable):
            if before.GetLocalToWorldTransform(prim) != after.GetLocalToWorldTransform(
                reloaded.GetPrimAtPath(prim.GetPath())
            ):
                raise RuntimeError(f"Overlay changed initial world transform: {prim.GetPath()}")
            count += 1
    roots = [
        str(p.GetPath()) for p in reloaded.Traverse() if p.HasAPI(UsdPhysics.ArticulationRootAPI)
    ]
    expected = [entry["new_root"] for entry in edits]
    current_hash = _sha(snapshot)
    if sorted(roots) != sorted(expected) or current_hash != source_hash:
        details = {}
        for path in sorted(set(roots + expected + [entry["old_root"] for entry in edits])):
            prim = reloaded.GetPrimAtPath(path)
            raw = prim.GetMetadata("apiSchemas")
            details[path] = dict(
                raw_tokens=[] if raw is None else list(raw.GetAppliedItems()),
                applied_schemas=list(prim.GetAppliedSchemas()),
            )
        raise RuntimeError(
            f"Derived root inventory or original snapshot changed: roots={roots}, "
            f"expected={expected}, source_before={source_hash}, "
            f"source_after={current_hash}, schemas={details}"
        )
    return overlay, dict(
        edits=edits,
        articulation_roots=expected,
        initial_world_transforms_unchanged=count,
        source_sha256=source_hash,
        mimic_translation=mimic_edits,
        mimic_native_runtime_verified=False,
    )


def _mimics(stage, joint_paths) -> list[dict]:
    result = []
    for paths in joint_paths:
        for path in paths:
            prim = stage.GetPrimAtPath(path)
            schemas = prim.GetMetadata("apiSchemas")
            if schemas is None or "NewtonMimicAPI" not in schemas.GetAppliedItems():
                continue
            leader = [str(p) for p in prim.GetRelationship("newton:mimicJoint").GetTargets()]
            if len(leader) != 1 or leader[0] not in paths or leader[0] == path:
                raise ValueError(f"Invalid Newton mimic leader: {path}")
            entry = dict(follower=path, leader=leader[0])
            for name, default in (("mimicCoef0", 0.0), ("mimicCoef1", 1.0), ("mimicEnabled", True)):
                value = prim.GetAttribute(f"newton:{name}").Get()
                entry[name] = default if value is None else value
            if not all(np.isfinite(entry[n]) for n in ("mimicCoef0", "mimicCoef1")):
                raise ValueError("Nonfinite mimic coefficient")
            result.append(entry)
    if len(result) != 4 or any(not entry["mimicEnabled"] for entry in result):
        raise ValueError("Expected four enabled native Newton mimic followers")
    return result


def build_seed(env, snapshot: Path, output: Path) -> dict:
    """Read one native boundary and write seed.json plus a reversible USD overlay.

    No app.update, physics step, state writes or SDK mutations. Returns the exact
    JSON seed written to output/seed.json. output may already contain receipts.
    """
    from pxr import Usd, UsdPhysics

    snapshot, output = Path(snapshot).resolve(strict=True), Path(output).resolve()
    output.mkdir(parents=True, exist_ok=True)
    seed_path = output / "seed.json"
    if seed_path.exists():
        raise FileExistsError(seed_path)
    step_before = env.sim.get_physics_step_count()
    stage = Usd.Stage.Open(str(snapshot))
    if not stage:
        raise ValueError("Cannot open current exported snapshot")
    views = [robot.root_view for robot in env.robots]
    if len(views) != 2:
        raise ValueError("Require exactly two current native robots")
    body_paths, dof_paths, joint_orders, body_orders = [], [], [], []
    for view in views:
        meta = view.shared_metatype
        metadata = dict(
            fixed_base=bool(meta.fixed_base),
            dof_names=list(meta.dof_names),
            link_names=list(meta.link_names),
            count=int(view.count) if hasattr(view, "count") else None,
        )
        # Kit may expose a floating articulation anchored by an external world
        # weld. The derived overlay relocates the root onto THAT existing weld;
        # _fixed_base_overlay validates both exact body relationships below.
        if len(meta.dof_names) != 9 or len(meta.link_names) != 12:
            raise ValueError(f"Unexpected native Piper topology: {metadata}")
        if tuple(meta.dof_names) != DOFS or tuple(meta.link_names) != BODIES:
            raise ValueError(
                f"Unexpected native Piper names/order; requalification required: {metadata}"
            )
        joints = [list(meta.dof_names).index(name) for name in DOFS]
        bodies = [list(meta.link_names).index(name) for name in BODIES]
        joint_orders.append(joints)
        body_orders.append(bodies)
        dof_paths.append([str(view.dof_paths[0][i]) for i in joints])
        body_paths.extend(str(view.link_paths[0][i]) for i in bodies)

    def joints(getter, width=None):
        shape = (1, 9) if width is None else (1, 9, width)
        return np.stack(
            [
                _array(getattr(v, getter)(), shape)[0, ids]
                for v, ids in zip(views, joint_orders, strict=True)
            ]
        )

    properties = {
        name: joints(getter, 2 if name == "limits" else None)
        for name, getter in (
            ("stiffness", "get_dof_stiffnesses"),
            ("damping", "get_dof_dampings"),
            ("max_force", "get_dof_max_forces"),
            ("max_velocity", "get_dof_max_velocities"),
            ("limits", "get_dof_limits"),
        )
    }
    dynamic = [*env.vr_runtime.dynamic_assets, env.physics_probe]
    if len(dynamic) != 3:
        raise ValueError("Require two cubes and ValidationProbe")
    dynamic_paths = [str(asset.cfg.prim_path) for asset in dynamic]
    dynamic_pose = np.stack([_array(a.root_view.get_transforms(), (1, 7))[0] for a in dynamic])
    dynamic_velocity = np.stack([_array(a.root_view.get_velocities(), (1, 6))[0] for a in dynamic])
    body_paths.extend(dynamic_paths)
    inventory = {str(p.GetPath()) for p in stage.Traverse() if p.HasAPI(UsdPhysics.RigidBodyAPI)}
    if len(body_paths) != 27 or len(set(body_paths)) != 27 or set(body_paths) != inventory:
        raise ValueError(
            f"Dynamic body coverage differs: missing={inventory - set(body_paths)}, extra={set(body_paths) - inventory}"
        )
    link_pose = np.stack(
        [
            _array(v.get_link_transforms(), (1, 12, 7))[0, ids]
            for v, ids in zip(views, body_orders, strict=True)
        ]
    )
    initial = dict(
        q=joints("get_dof_positions"),
        dq=joints("get_dof_velocities"),
        position_target=joints("get_dof_position_targets"),
        velocity_target=joints("get_dof_velocity_targets"),
        external_effort=joints("get_dof_actuation_forces"),
        root_pose=np.stack([_array(v.get_root_transforms(), (1, 7))[0] for v in views]),
        dynamic_body_pose=dynamic_pose,
        dynamic_body_velocity=dynamic_velocity,
        rigid_body_world_pose=np.concatenate([link_pose.reshape(24, 7), dynamic_pose]),
        link_pose=link_pose,
    )
    mimics = _mimics(stage, dof_paths)
    for entry in mimics:
        arm = next(i for i, paths in enumerate(dof_paths) if entry["follower"] in paths)
        index = dof_paths[arm].index(entry["follower"])
        entry["native_follower_stiffness"] = float(properties["stiffness"][arm, index])
        entry["native_follower_damping"] = float(properties["damping"][arm, index])
        if entry["native_follower_stiffness"] != 0 or entry["native_follower_damping"] != 0:
            raise ValueError("Selected canonical mimic followers must remain passive")
    drive_type = joints("get_drive_types").astype(np.uint8)
    if not np.isin(drive_type, [0, 1, 2]).all():
        raise ValueError("Unknown native drive type")
    if env.sim.get_physics_step_count() != step_before:
        raise RuntimeError("Native state changed during seed capture")
    overlay, adaptation = _fixed_base_overlay(snapshot, output, mimics)
    seed = dict(
        schema="standalone_cpu_physx_seed_v1",
        profile="standalone_cpu_physx_diagnostic_v1",
        stage_overlay=str(overlay),
        source_snapshot=str(snapshot),
        files=[dict(path=str(p), sha256=_sha(p)) for p in (snapshot, overlay)],
        articulation_roots=adaptation["articulation_roots"],
        rigid_body_paths=body_paths,
        dynamic_body_paths=dynamic_paths,
        dof_names=list(DOFS),
        body_names=list(BODIES),
        dof_properties={k: v.tolist() for k, v in properties.items()},
        drive_type=drive_type.tolist(),
        initial={k: v.tolist() for k, v in initial.items()},
        mimic_config=mimics,
        adaptation=adaptation,
        native_capture_physics_step=int(step_before),
        native_fixed_base=[bool(v.shared_metatype.fixed_base) for v in views],
        quaternion_order="xyzw",
        physics_dt_s=1 / 120,
        substeps_per_control=4,
        physical=False,
        dataset_admissible=False,
        canonical_physics_parity_verified=False,
    )
    with seed_path.open("x") as stream:
        json.dump(seed, stream, indent=2, allow_nan=False)
        stream.write("\n")
    return seed

"""One-time RECORD suspension; Camera retains all resource/teardown ownership.

Pinned adapter: Isaac Lab 17.0.2 (ae37b028 / materialization 0c2e2c64),
Isaac Sim 6.1 / Kit 110.3, Replicator 1.13.36. Camera has no public
render-resource accessor; its private ``_render_data`` dependency lives here.
Hydra update control and annotator detach/node inspection are public APIs.
No global renderer, viewport/XR enumeration, or per-control observers are used.
"""

from __future__ import annotations

from collections.abc import Mapping
from typing import Any


ROLES = ("left_wrist", "right_wrist", "scene")


def suspend_dataset_camera_rendering(
    cameras: Mapping[str, Any], stage: Any, camera_prim_paths: Mapping[str, str]
) -> None:
    """Suspend only initialized dataset products, after snapshot/Recordable setup."""
    from omni.replicator.core.scripts.annotators import AnnotatorRegistryError

    if set(cameras) != set(ROLES) or set(camera_prim_paths) != set(ROLES):
        raise RuntimeError("Expected exactly the three canonical dataset camera roles")
    if len({id(camera) for camera in cameras.values()}) != 3:
        raise RuntimeError("Expected three distinct canonical dataset cameras")
    resources = {role: cameras[role]._render_data for role in ROLES}
    # Resolve and validate every owned binding before changing any resource.
    for role, data in resources.items():
        if data is None or data.spec is None or data.render_product is None:
            raise RuntimeError(f"{role}: dataset camera render resources are not initialized")
        if tuple(map(str, data.spec.camera_prim_paths)) != (camera_prim_paths[role],):
            raise RuntimeError(f"{role}: render product does not match the recorded camera")
        prim = stage.GetPrimAtPath(camera_prim_paths[role])
        if not prim.IsValid() or prim.GetTypeName() != "Camera":
            raise RuntimeError(f"{role}: recorded camera prim is missing or changed")
        if not stage.GetPrimAtPath(data.render_product.path).IsValid():
            raise RuntimeError(f"{role}: dataset render product is missing")
    if len({str(data.render_product.path) for data in resources.values()}) != 3:
        raise RuntimeError("Expected three distinct dataset render products")

    for data in resources.values():
        data.render_product.hydra_texture.updates_enabled = False
        # State-only recording needs no live annotator, including the RGB reader
        # exposed as 'rgba' by this pin. Keep handles for Camera's own teardown.
        for annotator in data.annotators.values():
            annotator.detach([data.render_product.path])

    for role, data in resources.items():
        if data.render_product.hydra_texture.updates_enabled:
            raise RuntimeError(f"{role}: dataset render product did not suspend")
        for name, annotator in data.annotators.items():
            # is_attached stays stale after detach at this pin; check the graph
            # binding once here, never at a control/observation boundary.
            try:
                active = annotator.get_node().is_valid()
            except AnnotatorRegistryError:
                active = False
            if active:
                raise RuntimeError(f"{role}: live {name} annotator is still bound")

"""Fail-closed paired benchmark contract for the production VR recorder.

The module is deliberately independent of Isaac imports.  The live S2 loop can
feed it precise timing boundaries and resource observations, while the report
builder and validator remain usable in ordinary unit tests and offline review.

One benchmark *pair* is two runs with the same ``pair_id`` and provenance: a
production run with recording disabled and the matching production HDF run.
The raw JSONL files are evidence; the derived JSON report binds them by SHA-256.
No default performance budget is invented.  With no threshold policy the
qualification state is explicitly ``threshold_pending``.  A supplied policy is
accepted only when it covers every required limit.
"""

from __future__ import annotations

from collections.abc import Callable, Iterable, Mapping, Sequence
from contextlib import contextmanager
from dataclasses import dataclass
import argparse
import hashlib
import json
import math
import os
from pathlib import Path
import statistics
import time
from typing import Any, Iterator


SCHEMA_VERSION = "piper_x_isaac_vr_recording_benchmark_v1"
THRESHOLD_SCHEMA_VERSION = "piper_x_isaac_vr_recording_benchmark_thresholds_v1"
REPORT_SCHEMA_VERSION = "piper_x_isaac_vr_recording_benchmark_report_v1"

CONDITIONS = frozenset({"baseline", "recording"})
TIMING_METRICS = (
    "control_loop_ms",
    "state_sampling_ms",
    "hdf_append_ms",
    "hdf_flush_ms",
    "render_ms",
    "xr_ms",
)
RESOURCE_METRICS = (
    "process_cpu_percent",
    "rss_bytes",
    "gpu_utilization_percent",
    "gpu_memory_bytes",
    "disk_read_bytes",
    "disk_write_bytes",
)
PAIRING_FIELDS = (
    "git_commit",
    "dirty_status_sha256",
    "environment_sha256",
    "measurement_provenance_sha256",
    "scene_snapshot_sha256",
    "visual_provenance_sha256",
    "source_profile",
    "quest_session_id",
    "target_hz",
    "warmup_steps",
    "measured_steps",
    "headset_connected",
)
PERCENTILES = ("p50", "p95", "p99")


def _required_threshold_paths() -> tuple[str, ...]:
    paths: list[str] = []
    for name in ("control_loop_ms", "state_sampling_ms", "render_ms", "xr_ms"):
        for percentile in PERCENTILES:
            paths.append(f"overhead.timings.{name}.{percentile}_ratio")
    for name in ("hdf_append_ms", "hdf_flush_ms"):
        for percentile in PERCENTILES:
            paths.append(f"recording.timings.{name}.{percentile}_ms")
    for name in ("process_cpu_percent", "gpu_utilization_percent"):
        paths.append(f"overhead.resources.{name}.p95_delta")
    for name in ("rss_bytes", "gpu_memory_bytes"):
        paths.append(f"overhead.resources.{name}.max_delta")
    paths.extend(
        (
            "recording.disk.read_bytes_per_second",
            "recording.disk.write_bytes_per_second",
            "recording.disk.artifact_bytes_per_committed_frame",
            "recording.outcomes.drop_fraction",
            "recording.outcomes.rejection_fraction",
            "recording.outcomes.deadline_miss_fraction",
        )
    )
    return tuple(paths)


REQUIRED_THRESHOLD_PATHS = _required_threshold_paths()


def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        while chunk := stream.read(1024 * 1024):
            digest.update(chunk)
    return digest.hexdigest()


def _canonical_sha256(payload: Mapping[str, Any]) -> str:
    encoded = json.dumps(payload, allow_nan=False, separators=(",", ":"), sort_keys=True).encode(
        "utf-8"
    )
    return hashlib.sha256(encoded).hexdigest()


def _finite_number(value: Any, label: str, *, minimum: float | None = None) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{label} must be numeric")
    result = float(value)
    if not math.isfinite(result):
        raise ValueError(f"{label} must be finite")
    if minimum is not None and result < minimum:
        raise ValueError(f"{label} must be >= {minimum}")
    return result


def _percentile(values: Sequence[float], fraction: float) -> float:
    ordered = sorted(values)
    if not ordered:
        raise ValueError("cannot summarize an empty sample")
    position = (len(ordered) - 1) * fraction
    lower = math.floor(position)
    upper = math.ceil(position)
    if lower == upper:
        return ordered[lower]
    weight = position - lower
    return ordered[lower] * (1.0 - weight) + ordered[upper] * weight


def _distribution(values: Sequence[float], *, suffix: str = "") -> dict[str, float | int]:
    if not values:
        raise ValueError("cannot summarize an empty sample")
    return {
        "samples": len(values),
        f"mean{suffix}": statistics.fmean(values),
        f"p50{suffix}": _percentile(values, 0.50),
        f"p95{suffix}": _percentile(values, 0.95),
        f"p99{suffix}": _percentile(values, 0.99),
        f"max{suffix}": max(values),
    }


def _validate_digest(value: Any, label: str) -> str:
    text = str(value)
    if len(text) != 64 or any(character not in "0123456789abcdef" for character in text):
        raise ValueError(f"{label} must be lowercase SHA-256 hex")
    return text


def validate_identity(identity: Mapping[str, Any]) -> dict[str, Any]:
    """Validate and canonicalize the immutable header for one raw run."""

    required = {
        "pair_id",
        "condition",
        "run_id",
        "git_commit",
        "dirty_status_sha256",
        "environment_sha256",
        "measurement_provenance_sha256",
        "scene_snapshot_sha256",
        "visual_provenance_sha256",
        "source_profile",
        "quest_session_id",
        "target_hz",
        "warmup_steps",
        "measured_steps",
        "headset_connected",
        "pair_order",
    }
    if set(identity) != required:
        raise ValueError(
            f"identity fields {sorted(identity)} != required fields {sorted(required)}"
        )
    result = dict(identity)
    for field in ("pair_id", "run_id", "source_profile", "quest_session_id"):
        if not isinstance(result[field], str) or not result[field].strip():
            raise ValueError(f"{field} must be a non-empty string")
    if result["condition"] not in CONDITIONS:
        raise ValueError(f"condition must be one of {sorted(CONDITIONS)}")
    git_commit = str(result["git_commit"])
    if len(git_commit) != 40 or any(
        character not in "0123456789abcdef" for character in git_commit
    ):
        raise ValueError("git_commit must be lowercase 40-character hex")
    for field in (
        "dirty_status_sha256",
        "environment_sha256",
        "measurement_provenance_sha256",
        "scene_snapshot_sha256",
        "visual_provenance_sha256",
    ):
        result[field] = _validate_digest(result[field], field)
    result["target_hz"] = _finite_number(result["target_hz"], "target_hz", minimum=0.001)
    for field, minimum in (("warmup_steps", 0), ("measured_steps", 1)):
        if isinstance(result[field], bool) or not isinstance(result[field], int):
            raise ValueError(f"{field} must be an integer")
        if result[field] < minimum:
            raise ValueError(f"{field} must be >= {minimum}")
    if not isinstance(result["headset_connected"], bool):
        raise ValueError("headset_connected must be boolean")
    if result["pair_order"] not in (1, 2):
        raise ValueError("pair_order must be 1 or 2")
    return result


class BenchmarkRunLogger:
    """Write one append-only benchmark evidence JSONL.

    All stage values are per-control-step host-wall milliseconds.  Repeated
    ``stage`` blocks for one metric are additive.  For baseline runs HDF values
    must remain exactly zero; this distinguishes an explicit no-recording
    observation from a missing measurement.
    """

    def __init__(
        self,
        path: Path,
        identity: Mapping[str, Any],
        *,
        unavailable_timing_metrics: Iterable[str] = (),
    ) -> None:
        self.path = path
        self.identity = validate_identity(identity)
        unavailable = frozenset(unavailable_timing_metrics)
        unknown = unavailable.difference(TIMING_METRICS)
        if unknown:
            raise ValueError(f"unknown unavailable timing metrics: {sorted(unknown)}")
        if "control_loop_ms" in unavailable:
            raise ValueError("control_loop_ms cannot be unavailable")
        if self.identity["condition"] == "recording" and unavailable.intersection(
            {"hdf_append_ms", "hdf_flush_ms"}
        ):
            raise ValueError("recording HDF operation timings cannot be unavailable")
        self.unavailable_timing_metrics = unavailable
        path.parent.mkdir(parents=True, exist_ok=True)
        self._stream = path.open("x", encoding="utf-8")
        self._active_step: int | None = None
        self._started_ns = 0
        self._timings: dict[str, float] = {}
        self._written_steps = 0
        self._last_counters = {"committed": 0, "rejected": 0, "dropped": 0}
        self._closed = False
        self._write(
            {
                "event": "benchmark_run_started",
                "schema": SCHEMA_VERSION,
                "identity": self.identity,
                "clock": "time.perf_counter_ns",
                "timing_semantics": "additive_host_wall_per_control_step",
                "unavailable_timing_metrics": sorted(self.unavailable_timing_metrics),
                "resource_semantics": (
                    "CPU is process CPU over the step interval; RSS/GPU are observations; "
                    "disk read/write are process-I/O byte deltas for that step"
                ),
            }
        )
        self._stream.flush()

    def _write(self, payload: Mapping[str, Any]) -> None:
        self._stream.write(
            json.dumps(payload, allow_nan=False, separators=(",", ":"), sort_keys=True) + "\n"
        )

    def begin_step(self, step: int) -> None:
        if self._closed:
            raise RuntimeError("benchmark logger is closed")
        if self._active_step is not None:
            raise RuntimeError("previous benchmark step is still active")
        if isinstance(step, bool) or not isinstance(step, int) or step < 1:
            raise ValueError("step must be a positive integer")
        if step != self._written_steps + 1:
            raise ValueError("benchmark steps must be contiguous and one-based")
        self._active_step = step
        self._started_ns = time.perf_counter_ns()
        self._timings = {name: 0.0 for name in TIMING_METRICS if name != "control_loop_ms"}

    @contextmanager
    def stage(self, name: str) -> Iterator[None]:
        if self._active_step is None:
            raise RuntimeError("begin_step() must precede stage()")
        if name not in self._timings:
            raise ValueError(f"unknown benchmark stage {name!r}")
        started_ns = time.perf_counter_ns()
        try:
            yield
        finally:
            self.add_stage(name, time.perf_counter_ns() - started_ns)

    def add_stage(self, name: str, elapsed_ns: int) -> None:
        if self._active_step is None:
            raise RuntimeError("begin_step() must precede add_stage()")
        if name not in self._timings:
            raise ValueError(f"unknown benchmark stage {name!r}")
        if name in self.unavailable_timing_metrics:
            raise ValueError(f"benchmark stage {name!r} is declared unavailable")
        if isinstance(elapsed_ns, bool) or not isinstance(elapsed_ns, int) or elapsed_ns < 0:
            raise ValueError("elapsed_ns must be a nonnegative integer")
        self._timings[name] += elapsed_ns / 1_000_000.0

    def end_step(
        self,
        *,
        resources: Mapping[str, Any],
        committed: int,
        rejected: int,
        dropped: int,
        deadline_missed: bool,
    ) -> None:
        if self._active_step is None:
            raise RuntimeError("begin_step() must precede end_step()")
        if set(resources) != set(RESOURCE_METRICS):
            raise ValueError("resources must contain exactly the required resource metrics")
        normalized_resources = {
            name: _finite_number(resources[name], f"resources.{name}", minimum=0.0)
            for name in RESOURCE_METRICS
        }
        counters = {"committed": committed, "rejected": rejected, "dropped": dropped}
        for name, value in counters.items():
            if (
                isinstance(value, bool)
                or not isinstance(value, int)
                or value < self._last_counters[name]
            ):
                raise ValueError(f"{name} must be a monotonic nonnegative integer")
        if not isinstance(deadline_missed, bool):
            raise ValueError("deadline_missed must be boolean")
        timings = dict(self._timings)
        timings["control_loop_ms"] = (time.perf_counter_ns() - self._started_ns) / 1_000_000.0
        if self.identity["condition"] == "baseline" and (
            timings["hdf_append_ms"] != 0.0 or timings["hdf_flush_ms"] != 0.0
        ):
            raise ValueError("baseline run cannot contain HDF append or flush work")
        step = self._active_step
        self._write(
            {
                "event": "benchmark_step",
                "schema": SCHEMA_VERSION,
                "step": step,
                "post_warmup": step > self.identity["warmup_steps"],
                "monotonic_ns": time.monotonic_ns(),
                "timings_ms": timings,
                "timing_measurement_status": {
                    name: (
                        "not_measured"
                        if name in self.unavailable_timing_metrics
                        else "not_applicable_baseline"
                        if self.identity["condition"] == "baseline"
                        and name in {"hdf_append_ms", "hdf_flush_ms"}
                        else "measured"
                    )
                    for name in TIMING_METRICS
                },
                "resources": normalized_resources,
                "counters": counters,
                "deadline_missed": deadline_missed,
            }
        )
        self._written_steps += 1
        self._last_counters = counters
        self._active_step = None

    def close(self, *, recording_hdf5: Path | None = None) -> None:
        if self._closed:
            return
        if self._active_step is not None:
            raise RuntimeError("cannot close benchmark logger with an active step")
        total_expected = self.identity["warmup_steps"] + self.identity["measured_steps"]
        if self._written_steps != total_expected:
            raise RuntimeError(f"logged {self._written_steps} steps, expected {total_expected}")
        if self.identity["condition"] == "baseline":
            if recording_hdf5 is not None:
                raise ValueError("baseline must not advertise a recording artifact")
            artifact_path = None
            artifact_bytes = 0
            artifact_sha256 = None
        else:
            if recording_hdf5 is None:
                raise ValueError("recording run requires its finalized HDF5 artifact")
            artifact_path = recording_hdf5.resolve()
            if not artifact_path.is_file() or artifact_path.stat().st_size <= 0:
                raise ValueError("recording HDF5 artifact must be an existing non-empty file")
            artifact_bytes = artifact_path.stat().st_size
            artifact_sha256 = _sha256_file(artifact_path)
        self._write(
            {
                "event": "benchmark_run_completed",
                "schema": SCHEMA_VERSION,
                "steps": self._written_steps,
                "final_counters": self._last_counters,
                "artifact_bytes": artifact_bytes,
                "artifact_path": str(artifact_path) if artifact_path is not None else None,
                "artifact_sha256": artifact_sha256,
            }
        )
        self._stream.flush()
        os.fsync(self._stream.fileno())
        self._stream.close()
        self._closed = True


@dataclass(frozen=True)
class BenchmarkRun:
    path: Path
    sha256: str
    identity: dict[str, Any]
    unavailable_timing_metrics: tuple[str, ...]
    samples: tuple[dict[str, Any], ...]
    completion: dict[str, Any]


class ProcessResourceSampler:
    """Low-overhead Linux process resource sampler with an injected GPU probe.

    ``gpu_probe`` must read an already-running NVML/external sampler and return
    ``gpu_utilization_percent`` plus ``gpu_memory_bytes``.  Spawning
    ``nvidia-smi`` in the control loop is intentionally not implemented because
    it would perturb the latency distribution being qualified.
    """

    def __init__(self, gpu_probe: Callable[[], Mapping[str, Any]]) -> None:
        self.pid = os.getpid()
        self.gpu_probe = gpu_probe
        self._last_wall_ns = time.perf_counter_ns()
        self._last_cpu_ns = time.process_time_ns()
        self._last_io = self._read_io()

    def _read_io(self) -> tuple[int, int]:
        fields: dict[str, int] = {}
        for line in Path(f"/proc/{self.pid}/io").read_text().splitlines():
            name, value = line.split(":", 1)
            fields[name] = int(value.strip())
        return fields["read_bytes"], fields["write_bytes"]

    def _read_rss(self) -> int:
        resident_pages = int(Path(f"/proc/{self.pid}/statm").read_text().split()[1])
        return resident_pages * int(os.sysconf("SC_PAGE_SIZE"))

    def sample(self) -> dict[str, float | int]:
        now_wall_ns = time.perf_counter_ns()
        now_cpu_ns = time.process_time_ns()
        wall_delta = now_wall_ns - self._last_wall_ns
        cpu_delta = now_cpu_ns - self._last_cpu_ns
        current_io = self._read_io()
        gpu = self.gpu_probe()
        if set(gpu) != {"gpu_utilization_percent", "gpu_memory_bytes"}:
            raise ValueError("GPU probe must return utilization and memory exactly")
        result: dict[str, float | int] = {
            "process_cpu_percent": 100.0 * cpu_delta / wall_delta if wall_delta else 0.0,
            "rss_bytes": self._read_rss(),
            "gpu_utilization_percent": _finite_number(
                gpu["gpu_utilization_percent"], "gpu_utilization_percent", minimum=0.0
            ),
            "gpu_memory_bytes": _finite_number(
                gpu["gpu_memory_bytes"], "gpu_memory_bytes", minimum=0.0
            ),
            "disk_read_bytes": max(0, current_io[0] - self._last_io[0]),
            "disk_write_bytes": max(0, current_io[1] - self._last_io[1]),
        }
        self._last_wall_ns = now_wall_ns
        self._last_cpu_ns = now_cpu_ns
        self._last_io = current_io
        return result


def read_benchmark_run(path: Path) -> BenchmarkRun:
    """Read a complete raw log, rejecting partial or semantically incomplete input."""

    records: list[dict[str, Any]] = []
    with path.open(encoding="utf-8") as stream:
        for line_number, line in enumerate(stream, 1):
            try:
                record = json.loads(line)
            except json.JSONDecodeError as exc:
                raise ValueError(f"{path}:{line_number}: invalid JSON: {exc}") from exc
            if not isinstance(record, dict) or record.get("schema") != SCHEMA_VERSION:
                raise ValueError(f"{path}:{line_number}: wrong benchmark schema")
            records.append(record)
    if len(records) < 3:
        raise ValueError(f"{path}: incomplete benchmark log")
    if records[0].get("event") != "benchmark_run_started":
        raise ValueError(f"{path}: first record must be benchmark_run_started")
    if records[-1].get("event") != "benchmark_run_completed":
        raise ValueError(f"{path}: last record must be benchmark_run_completed")
    identity = validate_identity(records[0].get("identity", {}))
    unavailable_raw = records[0].get("unavailable_timing_metrics")
    if not isinstance(unavailable_raw, list) or any(
        not isinstance(name, str) for name in unavailable_raw
    ):
        raise ValueError(f"{path}: unavailable timing metrics must be a string list")
    unavailable = tuple(unavailable_raw)
    if len(unavailable) != len(set(unavailable)) or set(unavailable).difference(TIMING_METRICS):
        raise ValueError(f"{path}: invalid unavailable timing metrics")
    if "control_loop_ms" in unavailable:
        raise ValueError(f"{path}: control_loop_ms cannot be unavailable")
    if identity["condition"] == "recording" and set(unavailable).intersection(
        {"hdf_append_ms", "hdf_flush_ms"}
    ):
        raise ValueError(f"{path}: recording HDF timings cannot be unavailable")
    samples = records[1:-1]
    expected_steps = identity["warmup_steps"] + identity["measured_steps"]
    if len(samples) != expected_steps:
        raise ValueError(f"{path}: sample count does not match identity")
    prior_counters = {"committed": 0, "rejected": 0, "dropped": 0}
    prior_monotonic_ns = -1
    for index, sample in enumerate(samples, 1):
        if sample.get("event") != "benchmark_step" or sample.get("step") != index:
            raise ValueError(f"{path}: benchmark steps must be contiguous")
        if sample.get("post_warmup") is not (index > identity["warmup_steps"]):
            raise ValueError(f"{path}: incorrect post_warmup marker at step {index}")
        monotonic_ns = sample.get("monotonic_ns")
        if isinstance(monotonic_ns, bool) or not isinstance(monotonic_ns, int):
            raise ValueError(f"{path}: invalid monotonic timestamp")
        if monotonic_ns <= prior_monotonic_ns:
            raise ValueError(f"{path}: timestamps are not strictly increasing")
        prior_monotonic_ns = monotonic_ns
        timings = sample.get("timings_ms")
        timing_status = sample.get("timing_measurement_status")
        resources = sample.get("resources")
        counters = sample.get("counters")
        if not isinstance(timings, dict) or set(timings) != set(TIMING_METRICS):
            raise ValueError(f"{path}: incomplete timing sample")
        if not isinstance(timing_status, dict) or set(timing_status) != set(TIMING_METRICS):
            raise ValueError(f"{path}: incomplete timing measurement status")
        if not isinstance(resources, dict) or set(resources) != set(RESOURCE_METRICS):
            raise ValueError(f"{path}: incomplete resource sample")
        if not isinstance(counters, dict) or set(counters) != set(prior_counters):
            raise ValueError(f"{path}: incomplete counter sample")
        for name in TIMING_METRICS:
            _finite_number(timings[name], f"{path}:{index}:{name}", minimum=0.0)
            expected_status = (
                "not_measured"
                if name in unavailable
                else "not_applicable_baseline"
                if identity["condition"] == "baseline" and name in {"hdf_append_ms", "hdf_flush_ms"}
                else "measured"
            )
            if timing_status[name] != expected_status:
                raise ValueError(f"{path}: incorrect timing status for {name}")
            if expected_status != "measured" and timings[name] != 0.0:
                raise ValueError(f"{path}: unavailable timing {name} must have zero placeholder")
        for name in RESOURCE_METRICS:
            _finite_number(resources[name], f"{path}:{index}:{name}", minimum=0.0)
        for name, value in counters.items():
            if (
                isinstance(value, bool)
                or not isinstance(value, int)
                or value < prior_counters[name]
            ):
                raise ValueError(f"{path}: non-monotonic counter {name}")
        if not isinstance(sample.get("deadline_missed"), bool):
            raise ValueError(f"{path}: deadline_missed must be boolean")
        if identity["condition"] == "baseline" and (
            timings["hdf_append_ms"] != 0.0 or timings["hdf_flush_ms"] != 0.0
        ):
            raise ValueError(f"{path}: baseline contains HDF work")
        prior_counters = counters
    completion = records[-1]
    if (
        completion.get("steps") != expected_steps
        or completion.get("final_counters") != prior_counters
    ):
        raise ValueError(f"{path}: completion counters do not match samples")
    artifact_bytes = completion.get("artifact_bytes")
    artifact_path = completion.get("artifact_path")
    artifact_sha256 = completion.get("artifact_sha256")
    if identity["condition"] == "baseline":
        if artifact_bytes != 0 or artifact_path is not None or artifact_sha256 is not None:
            raise ValueError(f"{path}: baseline advertises a recording artifact")
    else:
        if (
            isinstance(artifact_bytes, bool)
            or not isinstance(artifact_bytes, int)
            or artifact_bytes <= 0
        ):
            raise ValueError(f"{path}: recording artifact size is missing")
        _validate_digest(artifact_sha256, f"{path}:artifact_sha256")
        bound_artifact = Path(str(artifact_path))
        if not bound_artifact.is_absolute() or not bound_artifact.is_file():
            raise ValueError(f"{path}: bound recording artifact is missing")
        if bound_artifact.stat().st_size != artifact_bytes:
            raise ValueError(f"{path}: bound recording artifact size changed")
        if _sha256_file(bound_artifact) != artifact_sha256:
            raise ValueError(f"{path}: bound recording artifact hash mismatch")
    return BenchmarkRun(
        path=path.resolve(),
        sha256=_sha256_file(path),
        identity=identity,
        unavailable_timing_metrics=unavailable,
        samples=tuple(samples),
        completion=completion,
    )


def _post_warmup(run: BenchmarkRun) -> tuple[dict[str, Any], ...]:
    samples = tuple(sample for sample in run.samples if sample["post_warmup"])
    if len(samples) != run.identity["measured_steps"]:
        raise ValueError(f"{run.path}: post-warmup sample count changed")
    return samples


def _condition_summary(runs: Sequence[BenchmarkRun]) -> dict[str, Any]:
    samples = tuple(sample for run in runs for sample in _post_warmup(run))
    condition = runs[0].identity["condition"]
    timings: dict[str, Any] = {}
    for name in TIMING_METRICS:
        statuses = {
            sample["timing_measurement_status"][name]
            for run in runs
            for sample in _post_warmup(run)
        }
        if len(statuses) != 1:
            raise ValueError(f"{condition} evidence has inconsistent timing status for {name}")
        measurement_status = statuses.pop()
        values = [float(sample["timings_ms"][name]) for sample in samples]
        # HDF latency is an operation latency, not a zero-padded control-step
        # average.  Per-step disk growth is reported separately below.
        if condition == "recording" and name in {"hdf_append_ms", "hdf_flush_ms"}:
            values = [value for value in values if value > 0.0]
            if not values:
                raise ValueError(f"recording evidence has no measured {name} operation")
        timings[name] = {
            "measurement_status": measurement_status,
            **_distribution(values, suffix="_ms"),
        }
    resources = {
        name: _distribution([float(sample["resources"][name]) for sample in samples])
        for name in RESOURCE_METRICS
    }
    counter_deltas: list[dict[str, int]] = []
    for run in runs:
        warmup_steps = int(run.identity["warmup_steps"])
        before = (
            run.samples[warmup_steps - 1]["counters"]
            if warmup_steps
            else {"committed": 0, "rejected": 0, "dropped": 0}
        )
        final = run.completion["final_counters"]
        counter_deltas.append({name: int(final[name]) - int(before[name]) for name in before})
    attempts = sum(
        int(row["committed"]) + int(row["rejected"]) + int(row["dropped"]) for row in counter_deltas
    )
    rejected = sum(int(row["rejected"]) for row in counter_deltas)
    dropped = sum(int(row["dropped"]) for row in counter_deltas)
    committed = sum(int(row["committed"]) for row in counter_deltas)
    if attempts == 0:
        raise ValueError(f"{condition} evidence has no measured control-boundary attempts")
    if condition == "recording" and committed == 0:
        raise ValueError("recording evidence has no committed HDF frames")
    deadline_misses = sum(bool(sample["deadline_missed"]) for sample in samples)
    elapsed_seconds = sum(
        float(sample["timings_ms"]["control_loop_ms"]) / 1000.0 for sample in samples
    )
    disk_read_bytes = sum(float(sample["resources"]["disk_read_bytes"]) for sample in samples)
    disk_write_bytes = sum(float(sample["resources"]["disk_write_bytes"]) for sample in samples)
    artifact_bytes = sum(int(run.completion["artifact_bytes"]) for run in runs)
    return {
        "run_count": len(runs),
        "sample_count": len(samples),
        "timings": timings,
        "resources": resources,
        "disk": {
            "read_bytes": disk_read_bytes,
            "write_bytes": disk_write_bytes,
            "read_bytes_per_second": disk_read_bytes / elapsed_seconds if elapsed_seconds else 0.0,
            "write_bytes_per_second": disk_write_bytes / elapsed_seconds
            if elapsed_seconds
            else 0.0,
            "artifact_bytes": artifact_bytes,
            "artifact_bytes_per_committed_frame": (
                artifact_bytes / committed if committed else math.inf
            ),
        },
        "outcomes": {
            "attempts": attempts,
            "committed": committed,
            "rejected": rejected,
            "dropped": dropped,
            "rejection_fraction": rejected / attempts if attempts else 0.0,
            "drop_fraction": dropped / attempts if attempts else 0.0,
            "deadline_misses": deadline_misses,
            "deadline_miss_fraction": deadline_misses / len(samples),
        },
    }


def _ratio(recording: float, baseline: float) -> float | None:
    if baseline == 0.0:
        return 1.0 if recording == 0.0 else None
    return recording / baseline


def _overhead(baseline: Mapping[str, Any], recording: Mapping[str, Any]) -> dict[str, Any]:
    timings: dict[str, Any] = {}
    for name in ("control_loop_ms", "state_sampling_ms", "render_ms", "xr_ms"):
        baseline_status = baseline["timings"][name]["measurement_status"]
        recording_status = recording["timings"][name]["measurement_status"]
        measurement_status = (
            "measured" if baseline_status == recording_status == "measured" else "not_measured"
        )
        timings[name] = {"measurement_status": measurement_status}
        for percentile in PERCENTILES:
            key = f"{percentile}_ms"
            base = float(baseline["timings"][name][key])
            recorded = float(recording["timings"][name][key])
            timings[name][f"{percentile}_baseline_ms"] = base
            timings[name][f"{percentile}_recording_ms"] = recorded
            timings[name][f"{percentile}_delta_ms"] = recorded - base
            timings[name][f"{percentile}_ratio"] = _ratio(recorded, base)
    resources: dict[str, Any] = {}
    for name in RESOURCE_METRICS:
        resources[name] = {}
        percentiles = (
            ("p95",)
            if name
            in (
                "process_cpu_percent",
                "gpu_utilization_percent",
            )
            else ("max",)
        )
        for percentile in percentiles:
            base = float(baseline["resources"][name][percentile])
            recorded = float(recording["resources"][name][percentile])
            resources[name][f"{percentile}_baseline"] = base
            resources[name][f"{percentile}_recording"] = recorded
            resources[name][f"{percentile}_delta"] = recorded - base
            resources[name][f"{percentile}_ratio"] = _ratio(recorded, base)
    return {"timings": timings, "resources": resources}


def _value_at_path(payload: Mapping[str, Any], path: str) -> Any:
    value: Any = payload
    for component in path.split("."):
        if not isinstance(value, Mapping) or component not in value:
            raise ValueError(f"report has no threshold metric {path!r}")
        value = value[component]
    return value


def _evaluate_thresholds(report: Mapping[str, Any], policy: Mapping[str, Any]) -> dict[str, Any]:
    if policy.get("schema") != THRESHOLD_SCHEMA_VERSION:
        raise ValueError("wrong benchmark threshold schema")
    if set(policy) != {"schema", "minimum_pairs", "minimum_steps_per_run", "limits"}:
        raise ValueError("threshold policy has unexpected or missing fields")
    minimum_pairs = policy["minimum_pairs"]
    minimum_steps = policy["minimum_steps_per_run"]
    if isinstance(minimum_pairs, bool) or not isinstance(minimum_pairs, int) or minimum_pairs < 1:
        raise ValueError("minimum_pairs must be a positive integer")
    if isinstance(minimum_steps, bool) or not isinstance(minimum_steps, int) or minimum_steps < 1:
        raise ValueError("minimum_steps_per_run must be a positive integer")
    limits = policy["limits"]
    if not isinstance(limits, Mapping) or set(limits) != set(REQUIRED_THRESHOLD_PATHS):
        missing = sorted(set(REQUIRED_THRESHOLD_PATHS).difference(limits or {}))
        extra = sorted(set(limits or {}).difference(REQUIRED_THRESHOLD_PATHS))
        raise ValueError(f"threshold coverage must be exact; missing={missing}, extra={extra}")
    checks: list[dict[str, Any]] = []
    checks.append(
        {
            "metric": "pair_count",
            "observed": report["pair_count"],
            "operator": ">=",
            "limit": minimum_pairs,
            "passed": report["pair_count"] >= minimum_pairs,
        }
    )
    steps = min(
        int(report[condition]["sample_count"] / report[condition]["run_count"])
        for condition in CONDITIONS
    )
    checks.append(
        {
            "metric": "minimum_steps_per_run",
            "observed": steps,
            "operator": ">=",
            "limit": minimum_steps,
            "passed": steps >= minimum_steps,
        }
    )
    for path in REQUIRED_THRESHOLD_PATHS:
        limit = _finite_number(limits[path], f"limits.{path}", minimum=0.0)
        observed = _finite_number(_value_at_path(report, path), path, minimum=0.0)
        checks.append(
            {
                "metric": path,
                "observed": observed,
                "operator": "<=",
                "limit": limit,
                "passed": observed <= limit,
            }
        )
    passed = all(check["passed"] for check in checks)
    return {
        "status": "passed" if passed else "failed",
        "threshold_policy_sha256": _canonical_sha256(policy),
        "checks": checks,
    }


def build_paired_report(
    paths: Iterable[Path], *, threshold_policy: Mapping[str, Any] | None = None
) -> dict[str, Any]:
    """Build a paired report from complete raw logs.

    Inputs are matched by ``pair_id`` rather than CLI order.  Every provenance
    field in :data:`PAIRING_FIELDS` must match within the pair.  Multiple pairs
    may have different Quest session IDs, but each individual pair may not.
    """

    runs = [read_benchmark_run(path) for path in paths]
    if not runs:
        raise ValueError("at least one baseline/recording pair is required")
    by_pair: dict[str, dict[str, BenchmarkRun]] = {}
    for run in runs:
        pair = by_pair.setdefault(run.identity["pair_id"], {})
        condition = run.identity["condition"]
        if condition in pair:
            raise ValueError(f"duplicate {condition} run for pair {run.identity['pair_id']}")
        pair[condition] = run
    for pair_id, pair in by_pair.items():
        if set(pair) != set(CONDITIONS):
            raise ValueError(f"pair {pair_id!r} lacks baseline or recording run")
        for field in PAIRING_FIELDS:
            baseline = pair["baseline"].identity[field]
            recording = pair["recording"].identity[field]
            if baseline != recording:
                raise ValueError(f"pair {pair_id!r} provenance mismatch: {field}")
        orders = {pair[condition].identity["pair_order"] for condition in CONDITIONS}
        if orders != {1, 2}:
            raise ValueError(f"pair {pair_id!r} must retain complementary pair_order values")
        unavailable = {pair[condition].unavailable_timing_metrics for condition in CONDITIONS}
        if len(unavailable) != 1:
            raise ValueError(f"pair {pair_id!r} timing availability mismatch")
    baseline_runs = [pair["baseline"] for pair in by_pair.values()]
    recording_runs = [pair["recording"] for pair in by_pair.values()]
    baseline = _condition_summary(baseline_runs)
    recording = _condition_summary(recording_runs)
    pair_results: list[dict[str, Any]] = []
    for pair_id, pair in sorted(by_pair.items()):
        pair_baseline = _condition_summary([pair["baseline"]])
        pair_recording = _condition_summary([pair["recording"]])
        pair_results.append(
            {
                "pair_id": pair_id,
                "baseline": pair_baseline,
                "recording": pair_recording,
                "overhead": _overhead(pair_baseline, pair_recording),
            }
        )
    report: dict[str, Any] = {
        "schema": REPORT_SCHEMA_VERSION,
        "pair_count": len(by_pair),
        "physical_quest_pair_count": sum(
            bool(pair["baseline"].identity["headset_connected"]) for pair in by_pair.values()
        ),
        "inputs": [
            {
                "path": str(run.path),
                "sha256": run.sha256,
                "pair_id": run.identity["pair_id"],
                "condition": run.identity["condition"],
                "run_id": run.identity["run_id"],
            }
            for run in sorted(
                runs, key=lambda item: (item.identity["pair_id"], item.identity["condition"])
            )
        ],
        "pairing": [
            {
                "pair_id": pair_id,
                "provenance": {field: pair["baseline"].identity[field] for field in PAIRING_FIELDS},
                "order": {
                    condition: pair[condition].identity["pair_order"]
                    for condition in sorted(CONDITIONS)
                },
            }
            for pair_id, pair in sorted(by_pair.items())
        ],
        "pair_results": pair_results,
        "baseline": baseline,
        "recording": recording,
        "overhead": _overhead(baseline, recording),
    }
    unavailable_metrics = sorted(
        {metric for run in runs for metric in run.unavailable_timing_metrics}
    )
    report["measurement_completeness"] = {
        "complete": not unavailable_metrics,
        "unavailable_timing_metrics": unavailable_metrics,
    }
    evaluated_thresholds = (
        _evaluate_thresholds(report, threshold_policy)
        if threshold_policy is not None and not unavailable_metrics
        else None
    )
    if unavailable_metrics:
        report["qualification"] = {
            "status": "failed",
            "reason": "one or more required timing metrics were explicitly not measured",
            "unavailable_timing_metrics": unavailable_metrics,
            "threshold_status": "threshold_pending"
            if threshold_policy is None
            else "not_evaluated",
            "required_threshold_paths": list(REQUIRED_THRESHOLD_PATHS),
        }
    elif report["physical_quest_pair_count"] != report["pair_count"]:
        report["qualification"] = {
            "status": "failed",
            "reason": "one or more pairs lack a connected physical Quest session",
            "threshold_status": "threshold_pending" if threshold_policy is None else "supplied",
            "required_threshold_paths": list(REQUIRED_THRESHOLD_PATHS),
            **({"threshold_evaluation": evaluated_thresholds} if evaluated_thresholds else {}),
        }
    else:
        report["qualification"] = (
            {
                "status": "threshold_pending",
                "reason": "no complete reviewed VRR-070 threshold policy was supplied",
                "required_threshold_paths": list(REQUIRED_THRESHOLD_PATHS),
            }
            if threshold_policy is None
            else evaluated_thresholds
        )
    report["report_sha256"] = _canonical_sha256(report)
    return report


def validate_paired_report(report: Mapping[str, Any]) -> None:
    """Verify the derived report self-hash and its bound raw evidence files."""

    if report.get("schema") != REPORT_SCHEMA_VERSION:
        raise ValueError("wrong paired benchmark report schema")
    digest = report.get("report_sha256")
    unsigned = dict(report)
    unsigned.pop("report_sha256", None)
    if digest != _canonical_sha256(unsigned):
        raise ValueError("paired benchmark report self-hash mismatch")
    inputs = report.get("inputs")
    if not isinstance(inputs, list) or not inputs:
        raise ValueError("paired benchmark report has no inputs")
    for entry in inputs:
        path = Path(entry["path"])
        if _sha256_file(path) != entry["sha256"]:
            raise ValueError(f"raw benchmark evidence hash mismatch: {path}")
    rebuilt = build_paired_report([Path(entry["path"]) for entry in inputs])
    for field in (
        "pair_count",
        "physical_quest_pair_count",
        "inputs",
        "pairing",
        "pair_results",
        "baseline",
        "recording",
        "overhead",
        "measurement_completeness",
    ):
        if report.get(field) != rebuilt[field]:
            raise ValueError(f"paired benchmark derived field mismatch: {field}")
    qualification = report.get("qualification", {})
    if qualification.get("status") not in {"threshold_pending", "passed", "failed"}:
        raise ValueError("unknown benchmark qualification status")
    checks = qualification.get("checks")
    if checks is not None:
        if not isinstance(checks, list):
            raise ValueError("benchmark qualification checks must be a list")
        expected_metrics = {
            "pair_count",
            "minimum_steps_per_run",
            *REQUIRED_THRESHOLD_PATHS,
        }
        if {check.get("metric") for check in checks} != expected_metrics:
            raise ValueError("benchmark qualification check coverage changed")
        for check in checks:
            metric = check.get("metric")
            if metric in REQUIRED_THRESHOLD_PATHS:
                observed = _value_at_path(report, metric)
                if check.get("observed") != observed:
                    raise ValueError(f"threshold check observation changed: {metric}")
            if check.get("operator") == "<=":
                passed = check.get("observed") <= check.get("limit")
            elif check.get("operator") == ">=":
                passed = check.get("observed") >= check.get("limit")
            else:
                raise ValueError(f"unknown threshold operator for {metric}")
            if check.get("passed") is not passed:
                raise ValueError(f"threshold check result changed: {metric}")
        expected_status = "passed" if all(check["passed"] for check in checks) else "failed"
        if qualification.get("status") != expected_status:
            raise ValueError("benchmark qualification aggregate status changed")


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("logs", nargs="+", type=Path, help="Raw baseline/recording JSONL logs")
    parser.add_argument("--thresholds", type=Path, help="Reviewed complete threshold policy JSON")
    parser.add_argument("--output", required=True, type=Path, help="Derived paired report JSON")
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = _parser().parse_args(argv)
    thresholds = json.loads(args.thresholds.read_text()) if args.thresholds else None
    report = build_paired_report(args.logs, threshold_policy=thresholds)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    temporary = args.output.with_name(f".{args.output.name}.{os.getpid()}.tmp")
    temporary.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    os.replace(temporary, args.output)
    validate_paired_report(report)
    print(json.dumps({"output": str(args.output), "qualification": report["qualification"]}))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""In-memory Isaac human decision receipts; no acquisition clock or storage."""

from __future__ import annotations

from dataclasses import asdict, dataclass, replace
from hashlib import sha256
import json
from typing import Any

import numpy as np

from tools.d0_causal import (
    CausalTransactionValidator,
    CompletedTransition,
    Epoch,
    PayloadIdentity,
    PreparedTransaction,
    SourceIdentity,
)
from tools.isaac_vr_capture import ObservationCapture

DECISION_REVISION = "piper_x_xr_preclip_decision_v1"
RECORDABLE_ARM_TRANSITIONS = frozenset(
    {"motion", "clutch_engaged", "clutch_held", "clutch_release_rebased"}
)


def recordable_teleop_command(command: Any) -> bool:
    """Admit known, tracked motion and intentional clutch transitions per arm."""
    return bool(
        command.session_active
        and all(
            arm.tracking_valid
            and arm.transition in RECORDABLE_ARM_TRANSITIONS
            and arm.rebased == (arm.transition == "clutch_release_rebased")
            and arm.clutch_active == (arm.transition in {"clutch_engaged", "clutch_held"})
            for arm in (command.left, command.right)
        )
    )


def _is_live_observation(observation: Any) -> bool:
    """Recognize the live capture structurally across supported import aliases.

    Isaac's script entrypoint can load ``isaac_vr_capture`` while the shared
    decision module is imported as ``tools.isaac_vr_decision``.  Those aliases
    create distinct Python class objects even though they describe the same
    frozen receipt, so runtime identity must not depend on ``isinstance``.
    """

    return hasattr(observation, "producer")


def _observation_reset_epoch(
    observation: ObservationCapture | StateSnapshotObservation,
) -> int:
    if _is_live_observation(observation):
        return int(observation.producer.reset_epoch)
    return int(observation.reset_epoch)


def payload(value: Any) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()


def _float32_vector(value: Any, *, size: int, field: str) -> np.ndarray:
    array = np.asarray(value, dtype="<f4")
    if array.shape != (size,) or not np.isfinite(array).all():
        raise ValueError(f"{field} must be finite float32[{size}]")
    return array


def _sha256_hex(value: str, *, field: str) -> str:
    if len(value) != 64 or any(character not in "0123456789abcdef" for character in value):
        raise ValueError(f"{field} must be lowercase SHA-256 hex")
    return value


def canonical_state_snapshot_payload(
    *,
    reset_epoch: int,
    physics_step: int,
    state_generation: int,
    capture_sequence: int,
    scene_state_snapshot_id: str,
    scene_state_snapshot_sha256: str,
    state: Any,
) -> bytes:
    """Canonical payload shared by the validator identity and stored HDF row."""
    values = {
        "reset_epoch": reset_epoch,
        "physics_step": physics_step,
        "state_generation": state_generation,
        "capture_sequence": capture_sequence,
    }
    if any(type(value) is not int or value < 0 for value in values.values()):
        raise ValueError("state snapshot boundary fields must be nonnegative integers")
    if not scene_state_snapshot_id:
        raise ValueError("scene_state_snapshot_id must be non-empty")
    digest = _sha256_hex(scene_state_snapshot_sha256, field="scene_state_snapshot_sha256")
    state_f32 = _float32_vector(state, size=14, field="observation_state")
    return payload(
        {
            "capture_sequence": capture_sequence,
            "physics_step": physics_step,
            "reset_epoch": reset_epoch,
            "scene_state_snapshot_id": scene_state_snapshot_id,
            "scene_state_snapshot_sha256": digest,
            "schema": "piper_x_scene_state_observation_v1",
            "state": state_f32.tolist(),
            "state_dtype": "<f4",
            "state_generation": state_generation,
            "state_units": "ordered_joint_degrees_gripper_millimetres",
        }
    )


def canonical_action_payload(
    dataset_action: Any,
    *,
    processor_revision: str,
    provenance_revision: str,
    processor_generation: int,
    arm_transitions: tuple[str, str] | None = None,
) -> bytes:
    if not processor_revision or not provenance_revision or processor_generation < 0:
        raise ValueError("invalid action processor identity")
    action_f32 = _float32_vector(dataset_action, size=14, field="dataset_action")
    fields = {
        "action": action_f32.tolist(),
        "action_dtype": "<f4",
        "action_units": "ordered_joint_degrees_gripper_millimetres",
        "processor_generation": processor_generation,
        "processor_revision": processor_revision,
        "provenance_revision": provenance_revision,
        "schema": "piper_x_dataset_action_v1",
    }
    if arm_transitions is not None:
        if len(arm_transitions) != 2 or any(
            transition not in RECORDABLE_ARM_TRANSITIONS for transition in arm_transitions
        ):
            raise ValueError("invalid recorded arm transitions")
        fields["schema"] = "piper_x_dataset_action_v2"
        fields["arm_transitions"] = list(arm_transitions)
    return payload(fields)


def canonical_native_command_payload(
    *, preclip: Any, clipped: Any, residual: Any, saturation: Any
) -> bytes:
    preclip_f32 = _float32_vector(preclip, size=14, field="native_preclip")
    clipped_f32 = _float32_vector(clipped, size=14, field="native_clipped")
    residual_f32 = _float32_vector(residual, size=14, field="native_residual")
    saturation_u8 = np.asarray(saturation, dtype=np.uint8)
    if saturation_u8.shape != (14,) or not np.isin(saturation_u8, (0, 1)).all():
        raise ValueError("saturation must be uint8[14] boolean flags")
    expected_residual = clipped_f32 - preclip_f32
    if not np.array_equal(residual_f32, expected_residual):
        raise ValueError("native residual must be the exact stored float32 clipped-preclip delta")
    if not np.array_equal(saturation_u8, (residual_f32 != 0).astype(np.uint8)):
        raise ValueError("native saturation must match the exact stored float32 residual")
    return payload(
        {
            "clipped": clipped_f32.tolist(),
            "dtype": "<f4",
            "preclip": preclip_f32.tolist(),
            "residual": residual_f32.tolist(),
            "saturation": saturation_u8.tolist(),
            "schema": "piper_x_native_command_v1",
            "units": "ordered_joint_radians_gripper_metres",
        }
    )


def canonical_native_command_fields(*, preclip: Any, clipped: Any) -> dict[str, np.ndarray]:
    preclip_f32 = _float32_vector(preclip, size=14, field="native_preclip")
    clipped_f32 = _float32_vector(clipped, size=14, field="native_clipped")
    residual_f32 = clipped_f32 - preclip_f32
    return {
        "preclip": preclip_f32,
        "clipped": clipped_f32,
        "residual": residual_f32,
        "saturation": (residual_f32 != 0).astype(np.uint8),
    }


def canonical_hands_sha256(hands: Any) -> str:
    return sha256(payload(hands)).hexdigest()


def canonical_xr_payload_from_fields(
    *,
    session_epoch: int,
    control_reference_epoch: int,
    deviceio_update_epoch: int,
    submitted_frame_id: int,
    returned_frame_id: int,
    ran_synchronously: bool,
    rebased: bool,
    tracking_valid: Any,
    world_transform: Any,
    hands_sha256: str,
) -> bytes:
    counters = {
        "session_epoch": session_epoch,
        "control_reference_epoch": control_reference_epoch,
        "deviceio_update_epoch": deviceio_update_epoch,
        "submitted_frame_id": submitted_frame_id,
        "returned_frame_id": returned_frame_id,
    }
    if any(type(value) is not int or value < 0 for value in counters.values()):
        raise ValueError("XR counters must be nonnegative integers")
    tracking = np.asarray(tracking_valid, dtype=np.uint8)
    if tracking.shape != (2,) or not np.isin(tracking, (0, 1)).all():
        raise ValueError("tracking_valid must be two boolean flags")
    transform = _float32_vector(world_transform, size=16, field="xr_world_transform")
    return payload(
        {
            **counters,
            "hands_sha256": _sha256_hex(hands_sha256, field="hands_sha256"),
            "ran_synchronously": bool(ran_synchronously),
            "rebased": bool(rebased),
            "schema": "piper_x_resolved_xr_input_v1",
            "tracking_valid": tracking.tolist(),
            "world_transform": transform.tolist(),
            "world_transform_dtype": "<f4",
        }
    )


def canonical_xr_payload(xr: "ResolvedXrInput") -> bytes:
    return canonical_xr_payload_from_fields(
        session_epoch=xr.session_epoch,
        control_reference_epoch=xr.control_reference_epoch,
        deviceio_update_epoch=xr.deviceio_update_epoch,
        submitted_frame_id=xr.submitted_frame_id,
        returned_frame_id=xr.returned_frame_id,
        ran_synchronously=xr.ran_synchronously,
        rebased=xr.rebased,
        tracking_valid=xr.tracking_valid,
        world_transform=xr.world_transform,
        hands_sha256=canonical_hands_sha256(xr.hands),
    )


def _payload_id(epoch: Epoch, role: str, tick: int) -> str:
    return ":".join(
        (
            epoch.run_id,
            epoch.episode_id,
            epoch.source_id,
            str(epoch.reset_epoch),
            str(epoch.control_reference_epoch),
            epoch.source_epoch,
            role,
            str(tick),
        )
    )


@dataclass(frozen=True)
class ResolvedXrInput:
    session_epoch: int
    control_reference_epoch: int
    deviceio_update_epoch: int
    submitted_frame_id: int
    returned_frame_id: int
    ran_synchronously: bool
    hands: tuple  # per-hand None or ordered (ControllerInputIndex.name, owned value) pairs
    world_transform: tuple[float, ...]
    rebased: bool
    tracking_valid: tuple[bool, bool]


@dataclass(frozen=True)
class StateSnapshotObservation:
    """Immutable native state boundary used by the offline-RGB recording profile."""

    reset_epoch: int
    physics_step: int
    state_generation: int
    state: tuple[float, ...]
    capture_sequence: int | None = None
    scene_state_snapshot_id: str | None = None
    scene_state_snapshot_sha256: str | None = None

    def __post_init__(self) -> None:
        if any(
            type(value) is not int or value < 0
            for value in (self.reset_epoch, self.physics_step, self.state_generation)
        ):
            raise ValueError("invalid state snapshot identity")
        if len(self.state) != 14 or not np.isfinite(self.state).all():
            raise ValueError("invalid state snapshot payload")
        binding = (
            self.capture_sequence,
            self.scene_state_snapshot_id,
            self.scene_state_snapshot_sha256,
        )
        if any(value is not None for value in binding):
            if (
                type(self.capture_sequence) is not int
                or self.capture_sequence < 0
                or not self.scene_state_snapshot_id
                or self.scene_state_snapshot_sha256 is None
            ):
                raise ValueError("state snapshot recording binding must be complete")
            _sha256_hex(self.scene_state_snapshot_sha256, field="scene_state_snapshot_sha256")

    @property
    def recording_bound(self) -> bool:
        return self.capture_sequence is not None

    def bind_recording_snapshot(
        self, *, capture_sequence: int, snapshot_id: str, snapshot_sha256: str
    ) -> "StateSnapshotObservation":
        if self.recording_bound:
            raise ValueError("state observation is already bound to a recorder snapshot")
        return replace(
            self,
            capture_sequence=capture_sequence,
            scene_state_snapshot_id=snapshot_id,
            scene_state_snapshot_sha256=snapshot_sha256,
        )

    def canonical_payload(self) -> bytes:
        if not self.recording_bound:
            raise RuntimeError("state observation is not bound to a full recorder snapshot")
        assert self.capture_sequence is not None
        assert self.scene_state_snapshot_id is not None
        assert self.scene_state_snapshot_sha256 is not None
        return canonical_state_snapshot_payload(
            reset_epoch=self.reset_epoch,
            physics_step=self.physics_step,
            state_generation=self.state_generation,
            capture_sequence=self.capture_sequence,
            scene_state_snapshot_id=self.scene_state_snapshot_id,
            scene_state_snapshot_sha256=self.scene_state_snapshot_sha256,
            state=self.state,
        )


def capture_state_snapshot(env: Any) -> StateSnapshotObservation:
    """Capture one stable native state generation without reading live RGB."""

    physics_step, state = env.capture_measured_state()
    reset_epoch = int(env.camera.reset_epoch)
    state_generation = int(env._state_physics_step)
    snapshot = StateSnapshotObservation(
        reset_epoch, int(physics_step), state_generation, tuple(float(value) for value in state)
    )
    check_observation(env, snapshot)
    return snapshot


class XrInputReceipt:
    """One source receipt. Poll is reached only after upstream DeviceIO.update returns."""

    def __init__(self) -> None:
        self.session: Any = None
        self.session_epoch = 0
        self.reference_epoch = 0
        self.update_epoch = 0
        self.frame = -1
        self.hands: tuple | None = None
        self.transform: tuple[float, ...] = ()
        self.rebased = False
        self.tracking_valid = (False, False)
        self.last_consumed = 0
        self.session_provider: Any = None

    def polled(self, session: Any, frame: int) -> None:
        if session is not self.session:
            self.session = session
            self.session_epoch += 1
            self.reference_epoch += 1
        self.update_epoch += 1
        self.frame = frame
        self.hands = None

    def transformed(self, hands: tuple, matrix: Any, reset: bool, tracking=(True, True)) -> None:
        transform = tuple(float(v) for v in np.from_dlpack(matrix).reshape(-1))
        if reset or transform != self.transform or tracking != self.tracking_valid:
            self.reference_epoch += 1
        self.transform, self.hands, self.rebased = transform, hands, reset
        self.tracking_valid = tracking

    def resolve(self, info: Any, previous_update: int) -> ResolvedXrInput:
        if (
            self.update_epoch != previous_update + 1
            or self.hands is None
            or not info.ran_synchronously
            or info.worker_exception is not None
            or info.submitted_frame_id != self.frame
            or info.returned_frame_id != self.frame
        ):
            raise RuntimeError("XR update/request/result mismatch")
        return ResolvedXrInput(
            self.session_epoch,
            self.reference_epoch,
            self.update_epoch,
            self.frame,
            self.frame,
            True,
            self.hands,
            self.transform,
            self.rebased,
            self.tracking_valid,
        )

    def validate(self, xr: ResolvedXrInput) -> None:
        if (
            xr.session_epoch != self.session_epoch
            or xr.control_reference_epoch != self.reference_epoch
            or xr.deviceio_update_epoch != self.update_epoch
            or xr.deviceio_update_epoch <= self.last_consumed
        ):
            raise RuntimeError("XR session/reference/update changed or reused")


def check_observation(
    env: Any, observation: ObservationCapture | StateSnapshotObservation | None
) -> None:
    if observation is None:
        return
    if isinstance(observation, StateSnapshotObservation):
        physics_step, state = env.capture_measured_state()
        if (
            int(env.camera.reset_epoch) != observation.reset_epoch
            or int(physics_step) != observation.physics_step
            or int(env._state_physics_step) != observation.state_generation
            or env.sim.get_physics_step_count() != observation.physics_step
            or tuple(float(value) for value in state) != observation.state
        ):
            raise RuntimeError("IK observation/state generation mismatch")
        return
    if (
        env.latest_observation_capture() is not observation
        or env._state_physics_step != observation.producer.physics_step
        or env.sim.get_physics_step_count() != observation.producer.physics_step
    ):
        raise RuntimeError("IK observation/state generation mismatch")


@dataclass(frozen=True)
class SolvedControlDecision:
    control_tick_id: int | None  # None for ordinary RUN holds outside D0 admission.
    observation_identity: ObservationCapture | StateSnapshotObservation | None
    xr_identity: ResolvedXrInput | None
    cartesian_intent: Any  # frozen BimanualTeleopCommand includes processor identity
    native_preclip: tuple[float, ...]
    native_clipped: tuple[float, ...]
    canonical_d0_action: bytes  # exactly little-endian float32[14], immutable

    @property
    def processor_identity(self) -> tuple[str, str, int]:
        command = self.cartesian_intent
        return command.processor_revision, command.provenance_revision, command.processor_generation

    @property
    def dataset_action(self) -> np.ndarray:
        return np.frombuffer(self.canonical_d0_action, dtype="<f4")

    @property
    def residual(self) -> tuple[float, ...]:
        return tuple(c - p for p, c in zip(self.native_preclip, self.native_clipped, strict=True))

    @property
    def saturation(self) -> tuple[bool, ...]:
        return tuple(v != 0 for v in self.residual)

    @property
    def saturated(self) -> bool:
        return any(self.saturation)

    @classmethod
    def from_native(cls, tick, observation, xr, command, preclip, clipped):
        label = np.asarray(preclip, dtype=np.float64).reshape(2, 7).copy()
        label[:, :6] = np.rad2deg(label[:, :6])
        label[:, 6] *= 1000.0
        if not np.isfinite(label).all() or not np.isfinite(clipped).all():
            raise RuntimeError("Non-finite control solution")
        with np.errstate(over="ignore"):
            canonical = label.astype("<f4")
        if not np.isfinite(canonical).all():
            raise RuntimeError("Non-finite float32 D0 label")
        return cls(
            tick,
            observation,
            xr,
            command,
            tuple(float(v) for v in preclip),
            tuple(float(v) for v in clipped),
            canonical.tobytes(),
        )

    def prepare(self, validator: CausalTransactionValidator):
        """Bind the selected live-camera or immutable-state observation profile."""
        observation, xr = self.observation_identity, self.xr_identity
        if (
            observation is None
            or xr is None
            or xr.rebased
            or not xr.ran_synchronously
            or not all(xr.tracking_valid)
            or (_is_live_observation(observation) and not observation.eligible)
        ):
            raise RuntimeError("Decision has no eligible observation/XR receipt")
        command = self.cartesian_intent
        if not recordable_teleop_command(command):
            raise RuntimeError("Processor decision is not D0 eligible")
        if validator.profile == "isaac_human_vr_offline_rgb_v1" and any(
            arm.transition != "motion" for arm in (command.left, command.right)
        ):
            raise RuntimeError("Motion-only offline-RGB V1 profile rejects clutch")
        epoch, tick = validator.epoch, self.control_tick_id
        if tick is None:
            raise RuntimeError("Decision has no eligible control tick")
        reset_epoch = _observation_reset_epoch(observation)
        if (
            epoch.reset_epoch != reset_epoch
            or epoch.control_reference_epoch != xr.control_reference_epoch
            or epoch.source_epoch != str(xr.session_epoch)
        ):
            raise RuntimeError("Decision epoch mismatch")
        obs_bytes = self.observation_payload
        action_bytes = self.action_payload_for_profile(validator.profile)
        xr_bytes = canonical_xr_payload(xr)
        if isinstance(observation, StateSnapshotObservation):
            if validator.profile not in {
                "isaac_human_vr_offline_rgb_v1", "isaac_human_vr_offline_rgb_v2"
            }:
                raise RuntimeError("State snapshot observation requires offline-RGB profile")
            sequences = [
                observation.state_generation,
                xr.deviceio_update_epoch,
                xr.submitted_frame_id,
                xr.returned_frame_id,
                xr.deviceio_update_epoch,
            ]
            names = (
                "simulation.scene_state_snapshot",
                "xr.device_io_update",
                "xr.submitted_frame",
                "xr.returned_frame",
                "xr.resolved_input",
            )
            source_payloads = (obs_bytes, xr_bytes, xr_bytes, xr_bytes, xr_bytes)
        else:
            if validator.profile != "isaac_human_vr_v4":
                raise RuntimeError("Live camera observation requires live-camera profile")
            sequences = [
                observation.producer.physics_step,
                *(c.data_generation for c in observation.cameras),
                xr.deviceio_update_epoch,
                xr.submitted_frame_id,
                xr.returned_frame_id,
                xr.deviceio_update_epoch,
            ]
            names = (
                "simulation.state_generation",
                "camera.left_wrist",
                "camera.right_wrist",
                "camera.scene",
                "xr.device_io_update",
                "xr.submitted_frame",
                "xr.returned_frame",
                "xr.resolved_input",
            )
            source_payloads = (
                obs_bytes,
                obs_bytes,
                obs_bytes,
                obs_bytes,
                xr_bytes,
                xr_bytes,
                xr_bytes,
                xr_bytes,
            )

        def bind(name, data):
            return PayloadIdentity.bind(epoch, tick, _payload_id(epoch, name, tick), data)

        return validator.prepare(
            bind("observation", obs_bytes),
            bind("action", action_bytes),
            tuple(
                SourceIdentity(name, bind(name, source_payload), sequence)
                for name, sequence, source_payload in zip(
                    names, sequences, source_payloads, strict=True
                )
            ),
            observation_payload=obs_bytes,
            action_payload=action_bytes,
            tracking_valid=True,
        )

    @property
    def observation_payload(self) -> bytes:
        if self.observation_identity is None:
            raise RuntimeError("Decision has no observation payload")
        if isinstance(self.observation_identity, StateSnapshotObservation):
            return self.observation_identity.canonical_payload()
        return payload(asdict(self.observation_identity))

    @property
    def action_payload(self) -> bytes:
        return self.action_payload_for_profile("isaac_human_vr_offline_rgb_v2")

    def action_payload_for_profile(self, profile: str) -> bytes:
        processor_revision, provenance_revision, generation = self.processor_identity
        return canonical_action_payload(
            self.dataset_action,
            processor_revision=processor_revision,
            provenance_revision=provenance_revision,
            processor_generation=generation,
            arm_transitions=(
                (self.cartesian_intent.left.transition, self.cartesian_intent.right.transition)
                if isinstance(self.observation_identity, StateSnapshotObservation)
                and profile == "isaac_human_vr_offline_rgb_v2"
                else None
            ),
        )


@dataclass(frozen=True)
class CommittedRecordingTransition:
    """Validated transition plus the exact payloads needed by the HDF writer."""

    prepared: PreparedTransaction
    completed: CompletedTransition
    successor_observation: StateSnapshotObservation
    observation_payload: bytes
    action_payload: bytes
    native_command_payload: bytes
    successor_payload: bytes


def commit_recording_transition(
    validator: CausalTransactionValidator,
    decision: SolvedControlDecision,
    prepared: PreparedTransaction,
    successor: StateSnapshotObservation,
    *,
    physics_steps: int = 4,
) -> CommittedRecordingTransition:
    """Complete and commit one applied offline-RGB transition, fail closed."""

    observation = decision.observation_identity
    if not isinstance(observation, StateSnapshotObservation):
        raise RuntimeError("Recording commit requires a state snapshot observation")
    if prepared.observation.control_tick_id != decision.control_tick_id:
        raise RuntimeError("Prepared transaction does not belong to decision")
    if (
        successor.reset_epoch != observation.reset_epoch
        or successor.physics_step != observation.physics_step + physics_steps
        or successor.state_generation != successor.physics_step
    ):
        raise RuntimeError("Successor does not match the applied physics transition")
    tick = prepared.observation.control_tick_id
    epoch = validator.epoch
    native_fields = canonical_native_command_fields(
        preclip=decision.native_preclip, clipped=decision.native_clipped
    )
    native_command_payload = canonical_native_command_payload(**native_fields)
    successor_payload = successor.canonical_payload()
    native = PayloadIdentity.bind(
        epoch, tick, _payload_id(epoch, "native", tick), native_command_payload
    )
    successor_identity = PayloadIdentity.bind(
        epoch,
        tick + 1,
        _payload_id(epoch, "observation", tick + 1),
        successor_payload,
    )
    completed = validator.complete_transition(
        prepared,
        native,
        _payload_id(epoch, "transition", tick),
        successor_identity,
        successful=True,
    )
    observation_payload = decision.observation_payload
    action_payload = decision.action_payload_for_profile(validator.profile)
    validator.commit(
        prepared,
        observation_payload=observation_payload,
        action_payload=action_payload,
    )
    return CommittedRecordingTransition(
        prepared,
        completed,
        successor,
        observation_payload,
        action_payload,
        native_command_payload,
        successor_payload,
    )


def decision_epoch(
    run_id: str,
    observation: ObservationCapture | StateSnapshotObservation,
    xr: ResolvedXrInput,
    *,
    episode_id: str = "unrecorded",
) -> Epoch:
    reset_epoch = _observation_reset_epoch(observation)
    return Epoch(
        run_id,
        episode_id,
        "isaac_human_vr",
        reset_epoch,
        xr.control_reference_epoch,
        str(xr.session_epoch),
    )

"""Fail-closed, portable asset closure for an exported Isaac USD stage.

The core of this module deliberately has no Kit or USD imports.  Production uses
``pxr.UsdUtils.ComputeAllDependencies`` through a lazy adapter, while unit tests
can supply a dependency provider without importing Isaac Sim.

Resolved host paths are never serialized.  Each file must be below one of the
explicitly named portable roots and is recorded as ``<root-name>/<relative-path>``.
Replay can therefore bind the same names to different local roots without
depending on the recording host's absolute directory layout.
"""

from __future__ import annotations

from collections.abc import Callable, Iterable, Mapping
import hashlib
import json
import os
from pathlib import Path
from pathlib import PurePosixPath
import re
from typing import Any
from urllib.parse import urlsplit


SCHEMA_VERSION = "piper_x_isaac_vr_asset_closure_v1"
_PORTABLE_ROOT_NAME = re.compile(r"[a-z0-9][a-z0-9._-]*\Z")


class AssetClosureError(RuntimeError):
    """The saved stage does not have a complete, portable local closure."""


DependencyProvider = Callable[[str], tuple[Iterable[Any], Iterable[Any], Iterable[Any]]]


def _usd_dependencies(snapshot: str) -> tuple[Iterable[Any], Iterable[Any], Iterable[Any]]:
    """Load the pinned USD API only inside an initialized Kit process."""

    try:
        from pxr import UsdUtils  # type: ignore[import-not-found]
    except ImportError as exc:  # pragma: no cover - exercised in the Isaac environment
        raise AssetClosureError(
            "pxr.UsdUtils is unavailable; asset closure must run in the declared Isaac "
            "environment"
        ) from exc
    return UsdUtils.ComputeAllDependencies(snapshot)


def _dependency_path(value: Any, *, kind: str) -> str:
    """Extract a resolved filesystem path from an Sdf layer/asset or a test fake."""

    if kind == "layer":
        candidate = getattr(value, "realPath", None)
    else:
        candidate = getattr(value, "resolvedPath", None)
        if not candidate:
            candidate = getattr(value, "path", None)
    if not candidate:
        candidate = value if isinstance(value, (str, os.PathLike)) else None
    if candidate is None or not str(candidate).strip():
        raise AssetClosureError(f"resolved {kind} has no local filesystem path: {value!r}")
    return os.fspath(candidate)


def _reject_uri(path: str, *, kind: str) -> None:
    parsed = urlsplit(path)
    if parsed.scheme:
        raise AssetClosureError(
            f"resolved {kind} is not a portable local file: {path!r} "
            f"(URI scheme {parsed.scheme!r})"
        )


def _resolved_file(path: str, *, snapshot_directory: Path, kind: str) -> Path:
    _reject_uri(path, kind=kind)
    candidate = Path(path)
    if not candidate.is_absolute():
        candidate = snapshot_directory / candidate
    try:
        resolved = candidate.resolve(strict=True)
    except (OSError, RuntimeError) as exc:
        raise AssetClosureError(f"resolved {kind} is missing or inaccessible: {path!r}") from exc
    if not resolved.is_file():
        raise AssetClosureError(f"resolved {kind} is not a regular file: {resolved}")
    return resolved


def _portable_roots(
    snapshot: Path | None, roots: Mapping[str, str | os.PathLike[str]] | None
) -> tuple[tuple[str, Path], ...]:
    if roots is not None:
        configured = roots
    elif snapshot is not None:
        configured = {"recording": snapshot.parent}
    else:
        raise AssetClosureError("portable root bindings are required for verification")
    if not configured:
        raise AssetClosureError("at least one portable root is required")

    normalized: list[tuple[str, Path]] = []
    names: set[str] = set()
    for raw_name, raw_root in configured.items():
        name = str(raw_name)
        if not _PORTABLE_ROOT_NAME.fullmatch(name) or name in {".", ".."}:
            raise AssetClosureError(f"invalid portable root name: {name!r}")
        folded = name.casefold()
        if folded in names:
            raise AssetClosureError(f"portable root names collide case-insensitively: {name!r}")
        names.add(folded)
        try:
            root = Path(raw_root).resolve(strict=True)
        except (OSError, RuntimeError) as exc:
            raise AssetClosureError(
                f"portable root is missing or inaccessible: {raw_root!r}"
            ) from exc
        if not root.is_dir():
            raise AssetClosureError(f"portable root is not a directory: {root}")
        normalized.append((name, root))

    # Most-specific root wins for nested declarations.  Name is the stable tie breaker.
    return tuple(sorted(normalized, key=lambda item: (-len(item[1].parts), item[0])))


def _portable_path(path: Path, roots: tuple[tuple[str, Path], ...]) -> str:
    for name, root in roots:
        try:
            relative = path.relative_to(root)
        except ValueError:
            continue
        if not relative.parts or any(part in {"", ".", ".."} for part in relative.parts):
            raise AssetClosureError(f"path cannot be represented portably: {path}")
        result = f"{name}/{relative.as_posix()}"
        if Path(result).is_absolute() or ".." in Path(result).parts:
            raise AssetClosureError(f"path cannot be represented portably: {path}")
        return result
    declared = ", ".join(f"{name}={root}" for name, root in roots)
    raise AssetClosureError(f"dependency is outside declared portable roots: {path} ({declared})")


def _resolve_portable_path(path: str, roots: tuple[tuple[str, Path], ...]) -> Path:
    """Resolve one serialized alias/path while rejecting traversal and symlink escape."""

    portable = PurePosixPath(path)
    if (
        not path
        or portable.is_absolute()
        or len(portable.parts) < 2
        or any(part in {"", ".", ".."} for part in portable.parts)
        or "\\" in path
        or portable.as_posix() != path
    ):
        raise AssetClosureError(f"invalid portable dependency path: {path!r}")
    bindings = dict(roots)
    alias, relative_parts = portable.parts[0], portable.parts[1:]
    root = bindings.get(alias)
    if root is None:
        raise AssetClosureError(f"portable dependency path uses unbound root {alias!r}: {path!r}")
    candidate = root.joinpath(*relative_parts)
    try:
        resolved = candidate.resolve(strict=True)
    except (OSError, RuntimeError, ValueError) as exc:
        raise AssetClosureError(f"portable dependency is missing or inaccessible: {path!r}") from exc
    try:
        resolved.relative_to(root)
    except ValueError as exc:
        raise AssetClosureError(f"portable dependency escapes root {alias!r}: {path!r}") from exc
    if not resolved.is_file():
        raise AssetClosureError(f"portable dependency is not a regular file: {path!r}")
    return resolved


def _hash_stable_file(path: Path) -> tuple[int, str]:
    """Hash a file and reject mutation during the read."""

    try:
        before = path.stat()
        digest = hashlib.sha256()
        with path.open("rb") as stream:
            for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                digest.update(chunk)
        after = path.stat()
    except OSError as exc:
        raise AssetClosureError(f"dependency is unreadable: {path}") from exc

    identity_before = (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns)
    identity_after = (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
    if identity_before != identity_after:
        raise AssetClosureError(f"dependency changed while it was hashed: {path}")
    return before.st_size, digest.hexdigest()


def _canonical_sha256(value: object) -> str:
    encoded = json.dumps(
        value,
        ensure_ascii=True,
        allow_nan=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def build_asset_closure_manifest(
    stage_snapshot: str | os.PathLike[str],
    *,
    portable_roots: Mapping[str, str | os.PathLike[str]] | None = None,
    dependency_provider: DependencyProvider | None = None,
) -> dict[str, object]:
    """Return the complete deterministic manifest for a saved USD snapshot.

    ``portable_roots`` maps stable logical names to recording-host directories.
    With no explicit mapping, only files beside/below the snapshot are accepted.
    All transitive layers and assets returned by USD must fit one of these roots.

    The aggregate digest covers the schema, portable snapshot identity and every
    sorted entry (including its kinds, size and content digest).  It intentionally
    excludes absolute paths and therefore remains stable after relocating roots.
    """

    snapshot_input = Path(stage_snapshot)
    try:
        snapshot = snapshot_input.resolve(strict=True)
    except (OSError, RuntimeError) as exc:
        raise AssetClosureError(
            f"stage snapshot is missing or inaccessible: {stage_snapshot!r}"
        ) from exc
    if not snapshot.is_file():
        raise AssetClosureError(f"stage snapshot is not a regular file: {snapshot}")

    roots = _portable_roots(snapshot, portable_roots)
    provider = dependency_provider or _usd_dependencies
    try:
        layers, assets, unresolved = provider(str(snapshot))
    except AssetClosureError:
        raise
    except Exception as exc:
        raise AssetClosureError(f"USD dependency traversal failed for {snapshot}") from exc

    unresolved_items = sorted({str(item) for item in unresolved})
    if unresolved_items:
        raise AssetClosureError(
            "USD dependency traversal reported unresolved references: "
            + ", ".join(repr(item) for item in unresolved_items)
        )

    paths: dict[Path, set[str]] = {snapshot: {"snapshot"}}
    for kind, dependencies in (("layer", layers), ("asset", assets)):
        for dependency in dependencies:
            raw_path = _dependency_path(dependency, kind=kind)
            resolved = _resolved_file(
                raw_path,
                snapshot_directory=snapshot.parent,
                kind=kind,
            )
            paths.setdefault(resolved, set()).add(kind)

    entries: list[dict[str, object]] = []
    portable_names: dict[str, Path] = {}
    for path, kinds in paths.items():
        portable_path = _portable_path(path, roots)
        collision_key = portable_path.casefold()
        previous = portable_names.get(collision_key)
        if previous is not None and previous != path:
            raise AssetClosureError(
                "portable dependency paths collide case-insensitively: "
                f"{previous} and {path}"
            )
        portable_names[collision_key] = path
        size, sha256 = _hash_stable_file(path)
        entries.append(
            {
                "path": portable_path,
                "kinds": sorted(kinds),
                "size_bytes": size,
                "sha256": sha256,
            }
        )

    entries.sort(key=lambda entry: str(entry["path"]))
    snapshot_path = _portable_path(snapshot, roots)
    payload: dict[str, object] = {
        "schema_version": SCHEMA_VERSION,
        "stage_snapshot_path": snapshot_path,
        "entry_count": len(entries),
        "entries": entries,
    }
    payload["asset_closure_sha256"] = _canonical_sha256(payload)
    return payload


def _required_sha256(value: object, *, field: str) -> str:
    if not isinstance(value, str) or re.fullmatch(r"[0-9a-f]{64}", value) is None:
        raise AssetClosureError(f"asset closure {field} must be a lowercase SHA-256 digest")
    return value


def verify_asset_closure_manifest(
    sidecar: str | os.PathLike[str],
    *,
    portable_roots: Mapping[str, str | os.PathLike[str]],
    expected_stage_snapshot: str | os.PathLike[str] | None = None,
) -> dict[str, object]:
    """Verify a closure sidecar and re-hash every bound file.

    Root bindings are mandatory and there is deliberately no absolute-path or
    sidecar-directory fallback.  A verifier on another host must explicitly bind
    every logical root used by the recording.
    """

    sidecar_path = Path(sidecar)
    try:
        document = json.loads(sidecar_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise AssetClosureError(f"asset closure sidecar is unreadable: {sidecar_path}") from exc
    if not isinstance(document, dict):
        raise AssetClosureError("asset closure sidecar root must be an object")
    required_fields = {
        "schema_version",
        "stage_snapshot_path",
        "entry_count",
        "entries",
        "asset_closure_sha256",
    }
    if set(document) != required_fields:
        raise AssetClosureError(
            "asset closure sidecar fields differ from schema: "
            f"missing={sorted(required_fields - set(document))}, "
            f"extra={sorted(set(document) - required_fields)}"
        )
    if document["schema_version"] != SCHEMA_VERSION:
        raise AssetClosureError(
            f"unsupported asset closure schema: {document['schema_version']!r}"
        )

    declared_aggregate = _required_sha256(
        document["asset_closure_sha256"], field="asset_closure_sha256"
    )
    aggregate_payload = dict(document)
    del aggregate_payload["asset_closure_sha256"]
    actual_aggregate = _canonical_sha256(aggregate_payload)
    if actual_aggregate != declared_aggregate:
        raise AssetClosureError(
            "asset closure aggregate digest mismatch: "
            f"expected {declared_aggregate}, got {actual_aggregate}"
        )

    entries = document["entries"]
    count = document["entry_count"]
    if isinstance(count, bool) or not isinstance(count, int) or count < 1:
        raise AssetClosureError("asset closure entry_count must be a positive integer")
    if not isinstance(entries, list) or len(entries) != count:
        raise AssetClosureError("asset closure entry_count does not match entries")
    stage_path = document["stage_snapshot_path"]
    if not isinstance(stage_path, str):
        raise AssetClosureError("asset closure stage_snapshot_path must be a string")

    roots = _portable_roots(None, portable_roots)
    seen_paths: dict[str, str] = {}
    seen_files: dict[Path, str] = {}
    snapshot_entries = 0
    resolved_stage: Path | None = None
    for index, raw_entry in enumerate(entries):
        if not isinstance(raw_entry, dict) or set(raw_entry) != {
            "path",
            "kinds",
            "size_bytes",
            "sha256",
        }:
            raise AssetClosureError(f"asset closure entry {index} does not match schema")
        path = raw_entry["path"]
        if not isinstance(path, str):
            raise AssetClosureError(f"asset closure entry {index} path must be a string")
        collision_key = path.casefold()
        if collision_key in seen_paths:
            raise AssetClosureError(
                "asset closure paths are duplicate or collide case-insensitively: "
                f"{seen_paths[collision_key]!r}, {path!r}"
            )
        seen_paths[collision_key] = path
        kinds = raw_entry["kinds"]
        if (
            not isinstance(kinds, list)
            or not kinds
            or not all(isinstance(kind, str) for kind in kinds)
            or kinds != sorted(set(kinds))
            or not set(kinds) <= {"snapshot", "layer", "asset"}
        ):
            raise AssetClosureError(f"asset closure entry {path!r} has invalid kinds")
        size = raw_entry["size_bytes"]
        if isinstance(size, bool) or not isinstance(size, int) or size < 0:
            raise AssetClosureError(f"asset closure entry {path!r} has invalid size_bytes")
        declared_sha256 = _required_sha256(raw_entry["sha256"], field=f"{path}.sha256")
        resolved = _resolve_portable_path(path, roots)
        previous_path = seen_files.get(resolved)
        if previous_path is not None:
            raise AssetClosureError(
                "asset closure maps multiple portable paths to one file: "
                f"{previous_path!r}, {path!r}"
            )
        seen_files[resolved] = path
        actual_size, actual_sha256 = _hash_stable_file(resolved)
        if actual_size != size:
            raise AssetClosureError(
                f"asset closure size mismatch for {path!r}: expected {size}, got {actual_size}"
            )
        if actual_sha256 != declared_sha256:
            raise AssetClosureError(
                f"asset closure digest mismatch for {path!r}: "
                f"expected {declared_sha256}, got {actual_sha256}"
            )
        if "snapshot" in kinds:
            snapshot_entries += 1
            if path != stage_path:
                raise AssetClosureError(
                    "asset closure snapshot entry does not match stage_snapshot_path"
                )
            resolved_stage = resolved

    if snapshot_entries != 1 or resolved_stage is None:
        raise AssetClosureError("asset closure must contain exactly one stage snapshot entry")
    if expected_stage_snapshot is not None:
        try:
            expected = Path(expected_stage_snapshot).resolve(strict=True)
        except (OSError, RuntimeError) as exc:
            raise AssetClosureError("expected stage snapshot is missing or inaccessible") from exc
        if resolved_stage != expected:
            raise AssetClosureError(
                f"asset closure stage snapshot {resolved_stage} != expected {expected}"
            )
    return document

"""Fail-closed NVIDIA Episode Recorder replay and offline RGB materialization.

Filesystem validation intentionally has no Kit dependency so corrupt or
incomplete artifacts are rejected before a USD stage is touched.  The
``replay_from_snapshot`` entry point runs immediately after AppLauncher creates
Kit and before the current task scene is constructed.
"""

from __future__ import annotations

from dataclasses import dataclass
import hashlib
import json
from pathlib import Path
from typing import Any, Callable, Mapping, Sequence

import numpy as np

try:
    from .isaac_vr_asset_closure import AssetClosureError, verify_asset_closure_manifest
except ImportError:  # Runtime imports tools directly from its source directory.
    from isaac_vr_asset_closure import AssetClosureError, verify_asset_closure_manifest
try:
    from .isaac_vr_visual_provenance import (
        VisualProvenanceError,
        assert_visual_provenance_matches,
        verify_visual_provenance,
    )
except ImportError:  # Runtime imports tools directly from its source directory.
    from isaac_vr_visual_provenance import (
        VisualProvenanceError,
        assert_visual_provenance_matches,
        verify_visual_provenance,
    )


CANONICAL_CAMERA_ROLES = ("left_wrist", "right_wrist", "scene")
REQUIRED_TRACKS = frozenset(
    {
        "state/left_robot",
        "state/right_robot",
        "state/camera/left_wrist",
        "state/camera/right_wrist",
        "state/camera/scene",
        "d0/committed_transition",
    }
)
REQUIRED_TRACK_TYPES = {
    "state/left_robot": "articulation",
    "state/right_robot": "articulation",
    "state/camera/left_wrist": "camera",
    "state/camera/right_wrist": "camera",
    "state/camera/scene": "camera",
    "d0/committed_transition": "piper_x_committed_transition_v3",
}
# Version 1 encoded O_n beside A_(n-1), so it is deliberately unsupported.
SUPPORTED_RECORDING_SCHEMAS = frozenset({"piper_x_isaac_vr_recording_manifest_v2"})


@dataclass(frozen=True)
class ReplayArtifact:
    """Verified immutable inputs required before Kit opens the snapshot."""

    recording: Path
    snapshot: Path
    manifest_path: Path
    manifest: Mapping[str, Any]
    hdf5_sha256: str
    snapshot_sha256: str
    asset_closure_path: Path
    asset_closure_sha256: str
    visual_provenance: Mapping[str, Any]
    visual_provenance_sha256: str
    terminal_successor_path: Path
    terminal_successor_sha256: str
    camera_paths: Mapping[str, str]
    committed_frames: int
    outcome: str


@dataclass(frozen=True)
class ReplaySession:
    """Validated HDF episode identity and transaction summary."""

    episode_name: str
    frames: int
    tracks: tuple[Mapping[str, Any], ...]
    observation_ids: tuple[str, ...]
    scene_state_snapshot_ids: tuple[str, ...]
    scene_state_snapshot_sha256: tuple[str, ...]
    committed_count: int


def _sha256(path: Path, *, chunk_size: int = 1024 * 1024) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        while chunk := stream.read(chunk_size):
            digest.update(chunk)
    return digest.hexdigest()


def _required_digest(manifest: Mapping[str, Any], key: str) -> str:
    value = manifest.get(key)
    if not isinstance(value, str) or len(value) != 64:
        raise ValueError(f"recording manifest requires a SHA-256 value for {key}")
    try:
        int(value, 16)
    except ValueError as exc:
        raise ValueError(f"recording manifest has invalid SHA-256 for {key}") from exc
    return value.lower()


def verify_recording_artifact(
    recording: Path,
    *,
    portable_roots: Mapping[str, str | Path],
) -> ReplayArtifact:
    """Verify the finalized HDF, snapshot and camera bindings without importing Kit."""
    recording = recording.expanduser().resolve()
    if not recording.is_file():
        raise FileNotFoundError(f"recording HDF5 not found: {recording}")
    artifact_dir = recording.parent
    manifest_path = artifact_dir / "manifest.json"
    if not manifest_path.is_file():
        raise FileNotFoundError(f"recording manifest not found: {manifest_path}")
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError(f"recording manifest is unreadable: {manifest_path}") from exc
    if not isinstance(manifest, dict):
        raise ValueError("recording manifest root must be an object")
    schema = manifest.get("schema")
    if schema not in SUPPORTED_RECORDING_SCHEMAS:
        raise ValueError(
            f"unsupported recording manifest schema {schema!r}; "
            f"expected one of {sorted(SUPPORTED_RECORDING_SCHEMAS)}"
        )
    if manifest.get("artifact_state") != "finalized":
        raise ValueError("recording artifact is not finalized")
    state_path = artifact_dir / "recording_state.json"
    if not state_path.is_file():
        raise FileNotFoundError(f"recording finalization marker not found: {state_path}")
    try:
        finalization = json.loads(state_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError(f"recording finalization marker is unreadable: {state_path}") from exc
    if finalization.get("artifact_state") != "finalized":
        raise ValueError("recording finalization marker is not finalized")
    committed_frames = manifest.get("committed_frames")
    if type(committed_frames) is not int or committed_frames <= 0:
        raise ValueError("finalized recording must declare a positive committed_frames count")
    if finalization.get("committed_frames") != committed_frames:
        raise ValueError("recording manifest and finalization marker frame counts differ")
    outcome = manifest.get("outcome")
    if outcome not in {"success", "operator_stopped"}:
        raise ValueError("finalized recording has no accepted terminal outcome")
    if finalization.get("outcome") != outcome:
        raise ValueError("recording manifest and finalization marker outcomes differ")
    if (
        manifest.get("pose_backend_requested") != "fabric"
        or manifest.get("pose_backend_effective") != "fabric"
    ):
        raise ValueError("recording did not prove the required Fabric pose backend")
    profile_schemas = {
        "isaac_human_vr_offline_rgb_v1": "piper_x_committed_transition_v2",
        "isaac_human_vr_offline_rgb_v2": "piper_x_committed_transition_v3",
    }
    session_metadata = manifest.get("session_metadata")
    if (
        not isinstance(session_metadata, dict)
        or manifest.get("transition_schema") != profile_schemas.get(
            session_metadata.get("source_profile")
        )
    ):
        raise ValueError("recording manifest has an unsupported source profile")

    declared_hdf = manifest.get("hdf5")
    if declared_hdf is not None and declared_hdf != recording.name:
        raise ValueError(
            f"recording filename {recording.name!r} does not match manifest {declared_hdf!r}"
        )
    hdf5_sha256 = _required_digest(manifest, "hdf5_sha256")
    if finalization.get("hdf5_sha256") != hdf5_sha256:
        raise ValueError("recording manifest and finalization marker HDF hashes differ")
    actual_hdf5_sha256 = _sha256(recording)
    if actual_hdf5_sha256 != hdf5_sha256:
        raise ValueError(
            f"recording HDF5 digest mismatch: expected {hdf5_sha256}, got {actual_hdf5_sha256}"
        )

    snapshot_name = manifest.get("stage_snapshot")
    if not isinstance(snapshot_name, str) or not snapshot_name:
        raise ValueError("recording manifest requires stage_snapshot")
    snapshot_relative = Path(snapshot_name)
    if snapshot_relative.is_absolute() or ".." in snapshot_relative.parts:
        raise ValueError("stage_snapshot must be a safe artifact-relative path")
    snapshot = (artifact_dir / snapshot_relative).resolve()
    if not snapshot.is_relative_to(artifact_dir):
        raise ValueError("stage_snapshot escapes the recording artifact directory")
    if not snapshot.is_file():
        raise FileNotFoundError(f"recording stage snapshot not found: {snapshot}")
    snapshot_sha256 = _required_digest(manifest, "stage_snapshot_sha256")
    actual_snapshot_sha256 = _sha256(snapshot)
    if actual_snapshot_sha256 != snapshot_sha256:
        raise ValueError(
            f"stage snapshot digest mismatch: expected {snapshot_sha256}, got {actual_snapshot_sha256}"
        )

    asset_closure_name = manifest.get("asset_closure")
    if not isinstance(asset_closure_name, str) or not asset_closure_name:
        raise ValueError("recording manifest requires asset_closure")
    asset_closure_relative = Path(asset_closure_name)
    if asset_closure_relative.is_absolute() or ".." in asset_closure_relative.parts:
        raise ValueError("asset_closure must be a safe artifact-relative path")
    asset_closure_path = (artifact_dir / asset_closure_relative).resolve()
    if not asset_closure_path.is_relative_to(artifact_dir):
        raise ValueError("asset_closure escapes the recording artifact directory")
    if not asset_closure_path.is_file():
        raise FileNotFoundError(f"recording asset closure not found: {asset_closure_path}")
    asset_closure_sha256 = _required_digest(manifest, "asset_closure_sha256")
    try:
        asset_closure = verify_asset_closure_manifest(
            asset_closure_path,
            portable_roots=portable_roots,
            expected_stage_snapshot=snapshot,
        )
    except AssetClosureError as exc:
        raise ValueError(f"recording asset closure verification failed: {exc}") from exc
    if asset_closure["asset_closure_sha256"] != asset_closure_sha256:
        raise ValueError("recording manifest and asset closure aggregate hashes differ")

    visual_provenance = manifest.get("visual_provenance")
    if not isinstance(visual_provenance, dict):
        raise ValueError("recording manifest requires visual_provenance")
    visual_provenance_sha256 = _required_digest(manifest, "visual_provenance_sha256")
    try:
        verified_visual_provenance = verify_visual_provenance(visual_provenance)
    except VisualProvenanceError as exc:
        raise ValueError(f"recording visual provenance verification failed: {exc}") from exc
    if verified_visual_provenance["visual_provenance_sha256"] != visual_provenance_sha256:
        raise ValueError("recording manifest and visual provenance hashes differ")

    camera_paths = manifest.get("camera_roles")
    if not isinstance(camera_paths, dict) or set(camera_paths) != set(CANONICAL_CAMERA_ROLES):
        raise ValueError(
            f"recording camera_roles must contain exactly {list(CANONICAL_CAMERA_ROLES)}"
        )
    normalized_camera_paths: dict[str, str] = {}
    for role in CANONICAL_CAMERA_ROLES:
        path = camera_paths[role]
        if not isinstance(path, str) or not path.startswith("/") or "//" in path:
            raise ValueError(f"recording camera path for {role} is not an absolute USD prim path")
        normalized_camera_paths[role] = path
    if len(set(normalized_camera_paths.values())) != len(normalized_camera_paths):
        raise ValueError("recording camera prim paths must be unique")
    provenance_camera_paths = {
        str(entry["role"]): str(entry["prim_path"])
        for entry in verified_visual_provenance["camera_roles"]
    }
    if provenance_camera_paths != normalized_camera_paths:
        raise ValueError("recording camera roles disagree with visual provenance")

    terminal = manifest.get("terminal_successor")
    if not isinstance(terminal, dict):
        raise ValueError("finalized recording requires a terminal successor artifact")
    if terminal.get("file") != "terminal_successor.npz":
        raise ValueError("recording terminal successor has an unsupported filename")
    terminal_path = (artifact_dir / "terminal_successor.npz").resolve()
    if not terminal_path.is_relative_to(artifact_dir):
        raise ValueError("terminal successor escapes the recording artifact directory")
    terminal_sha256 = _required_digest(terminal, "sha256")
    try:
        from isaac_vr_recording import verify_terminal_successor_snapshot
    except ImportError:
        from tools.isaac_vr_recording import verify_terminal_successor_snapshot
    try:
        verified_terminal = verify_terminal_successor_snapshot(
            terminal_path,
            expected_artifact_sha256=terminal_sha256,
        )
    except (OSError, TypeError, ValueError) as exc:
        raise ValueError(f"recording terminal successor verification failed: {exc}") from exc
    if terminal.get("schema") != "piper_x_terminal_successor_v1":
        raise ValueError("recording terminal successor schema is unsupported")
    if terminal.get("scene_state_snapshot_id") != verified_terminal.token.scene_state_snapshot_id:
        raise ValueError("recording manifest terminal successor identity mismatch")
    if (
        terminal.get("scene_state_snapshot_sha256")
        != verified_terminal.token.scene_state_snapshot_sha256
    ):
        raise ValueError("recording manifest terminal successor digest mismatch")
    if terminal.get("capture_sequence") != verified_terminal.token.capture_sequence:
        raise ValueError("recording manifest terminal successor sequence mismatch")

    return ReplayArtifact(
        recording=recording,
        snapshot=snapshot,
        manifest_path=manifest_path,
        manifest=manifest,
        hdf5_sha256=hdf5_sha256,
        snapshot_sha256=snapshot_sha256,
        asset_closure_path=asset_closure_path,
        asset_closure_sha256=asset_closure_sha256,
        visual_provenance=verified_visual_provenance,
        visual_provenance_sha256=visual_provenance_sha256,
        terminal_successor_path=terminal_path,
        terminal_successor_sha256=terminal_sha256,
        camera_paths=normalized_camera_paths,
        committed_frames=committed_frames,
        outcome=outcome,
    )


def _validate_session(reader: Any, artifact: ReplayArtifact, episode: int) -> ReplaySession:
    episodes = reader.list_episodes()
    if not episodes:
        raise RuntimeError("recording contains no episodes")
    episode_name = reader.normalize_episode(episode)
    frames = reader.num_frames(episode_name)
    if frames <= 0:
        raise RuntimeError("recording episode contains no committed frames")
    if frames != artifact.committed_frames:
        raise RuntimeError(
            f"HDF frame count {frames} != finalized manifest {artifact.committed_frames}"
        )
    manifest = reader.manifest()
    tracks = tuple(dict(track) for track in manifest.tracks)
    track_groups = {str(track.get("group")) for track in tracks}
    if len(track_groups) != len(tracks):
        raise RuntimeError("recording manifest contains duplicate track groups")
    missing = REQUIRED_TRACKS - track_groups
    if missing:
        raise RuntimeError(f"recording missing required tracks: {sorted(missing)}")
    track_types = {str(track.get("group")): track.get("type") for track in tracks}
    expected_types = dict(REQUIRED_TRACK_TYPES)
    expected_types["d0/committed_transition"] = artifact.manifest["transition_schema"]
    mismatched_types = {
        group: {"expected": expected, "actual": track_types.get(group)}
        for group, expected in expected_types.items()
        if track_types.get(group) != expected
    }
    if mismatched_types:
        raise RuntimeError(f"recording required track types mismatch: {mismatched_types}")

    hdf_session = dict(manifest.session)
    external_session = artifact.manifest["session_metadata"]
    for key in ("run_id", "session_id", "episode_id", "source_profile"):
        if hdf_session.get(key) != external_session.get(key):
            raise RuntimeError(f"HDF/public manifest session identity mismatch for {key}")
    if hdf_session.get("stage_snapshot") != artifact.snapshot.name:
        raise RuntimeError("HDF public manifest does not bind the verified stage snapshot")
    if hdf_session.get("stage_snapshot_sha256") != artifact.snapshot_sha256:
        raise RuntimeError("HDF public manifest does not bind the verified snapshot digest")
    if hdf_session.get("asset_closure_sha256") != artifact.asset_closure_sha256:
        raise RuntimeError("HDF public manifest does not bind the verified asset closure")
    if hdf_session.get("visual_provenance_sha256") != artifact.visual_provenance_sha256:
        raise RuntimeError("HDF public manifest does not bind the verified visual provenance")
    sampling = dict(manifest.sampling)
    if (
        sampling.get("pose_backend") != "fabric"
        or sampling.get("mode") != "explicit_committed_control_boundary"
    ):
        raise RuntimeError("HDF public manifest has unsupported sampling provenance")
    attrs = reader.episode_attrs(episode_name)
    if int(attrs.get("num_frames", frames)) != frames:
        raise RuntimeError("HDF episode attributes disagree with the frame count")

    d0 = reader.read_group_all_frames(episode_name, "d0/committed_transition")
    try:
        from isaac_vr_recording import (
            _empty_d0_sample,
            canonical_committed_transition,
            verify_committed_transition_sample,
        )
    except ImportError:  # Unit tests import through the repository package.
        from tools.isaac_vr_recording import (
            _empty_d0_sample,
            canonical_committed_transition,
            verify_committed_transition_sample,
        )
    schema_version = 2 if artifact.manifest["transition_schema"].endswith("_v2") else 3
    expected_channels = set(_empty_d0_sample(schema_version=schema_version))
    if set(d0) != expected_channels:
        missing_channels = expected_channels - set(d0)
        extra_channels = set(d0) - expected_channels
        raise RuntimeError(
            "canonical D0 transition channels mismatch; "
            f"missing={sorted(missing_channels)}, extra={sorted(extra_channels)}"
        )
    arrays = {name: np.asarray(values) for name, values in d0.items()}
    malformed = sorted(name for name, values in arrays.items() if values.shape[:1] != (frames,))
    if malformed:
        raise RuntimeError(f"D0 channel frame dimensions are malformed: {malformed}")
    rows: list[dict[str, Any]] = []
    for frame in range(frames):
        raw = {name: values[frame] for name, values in arrays.items()}
        try:
            canonical = canonical_committed_transition(raw)
            verify_committed_transition_sample(canonical)
        except (TypeError, ValueError) as exc:
            raise RuntimeError(f"D0 frame {frame} failed canonical verification: {exc}") from exc
        if int(canonical["frame_index"]) != frame:
            raise RuntimeError(f"D0 frame {frame} has a non-dense committed index")
        rows.append(canonical)

    def text(value: Any) -> str:
        return bytes(np.asarray(value).tobytes()).rstrip(b"\0").decode("utf-8")

    def digest(value: Any) -> bytes:
        return np.asarray(value, dtype=np.uint8).tobytes()

    observation_ids = tuple(text(row["obs_id"]) for row in rows)
    scene_state_snapshot_ids = tuple(text(row["scene_state_snapshot_id"]) for row in rows)
    scene_state_snapshot_sha256 = tuple(
        digest(row["scene_state_snapshot_sha256"]).hex() for row in rows
    )
    for field in ("obs_id", "dataset_action_id", "native_command_id", "transition_id"):
        identities = [text(row[field]) for row in rows]
        if len(identities) != len(set(identities)):
            raise RuntimeError(f"D0 reuses {field} within one episode")
    terminated_at = [index for index, row in enumerate(rows) if int(row["terminated"])]
    if terminated_at and terminated_at != [frames - 1]:
        raise RuntimeError("D0 terminal transition must be the final committed row")

    for index, (current, following) in enumerate(zip(rows, rows[1:], strict=False)):
        exact_text_pairs = (
            ("next_obs_id", "obs_id"),
            ("next_scene_state_snapshot_id", "scene_state_snapshot_id"),
        )
        for left, right in exact_text_pairs:
            if text(current[left]) != text(following[right]):
                raise RuntimeError(f"D0 successor continuity mismatch at frame {index}: {left}")
        exact_digest_pairs = (
            ("next_scene_state_snapshot_sha256", "scene_state_snapshot_sha256"),
            ("successor_payload_sha256", "observation_payload_sha256"),
        )
        for left, right in exact_digest_pairs:
            if digest(current[left]) != digest(following[right]):
                raise RuntimeError(f"D0 successor continuity mismatch at frame {index}: {left}")
        exact_numeric_pairs = (
            ("successor_observation_state", "observation_state"),
            ("successor_physics_step", "observation_physics_step"),
            ("successor_capture_sequence", "observation_capture_sequence"),
            ("successor_state_generation", "simulation_state_generation"),
            ("successor_reset_epoch", "reset_epoch"),
        )
        for left, right in exact_numeric_pairs:
            if not np.array_equal(current[left], following[right]):
                raise RuntimeError(f"D0 successor continuity mismatch at frame {index}: {left}")
        for counter in (
            "control_tick_id",
            "deviceio_update_epoch",
            "submitted_frame_id",
            "returned_frame_id",
        ):
            if int(following[counter]) != int(current[counter]) + 1:
                raise RuntimeError(f"D0 {counter} is not dense at frame {index}")
        for epoch_field in (
            "run_id",
            "session_id",
            "episode_id",
            "source_id",
            "source_epoch",
            "reset_epoch",
            "control_reference_epoch",
            "session_epoch",
        ):
            if not np.array_equal(current[epoch_field], following[epoch_field]):
                raise RuntimeError(f"D0 crosses {epoch_field} within one episode")

    committed = np.asarray([int(row["committed"]) for row in rows], dtype=bool)
    try:
        from isaac_vr_recording import verify_terminal_successor_snapshot
    except ImportError:
        from tools.isaac_vr_recording import verify_terminal_successor_snapshot
    try:
        verify_terminal_successor_snapshot(
            artifact.terminal_successor_path,
            expected_artifact_sha256=artifact.terminal_successor_sha256,
            committed_transition=rows[-1],
        )
    except (OSError, TypeError, ValueError) as exc:
        raise RuntimeError(
            f"terminal successor does not close the final D0 transition: {exc}"
        ) from exc
    return ReplaySession(
        episode_name=episode_name,
        frames=frames,
        tracks=tracks,
        observation_ids=observation_ids,
        scene_state_snapshot_ids=scene_state_snapshot_ids,
        scene_state_snapshot_sha256=scene_state_snapshot_sha256,
        committed_count=int(committed.sum()),
    )


def apply_replay_frames(
    replayer: Any,
    frames: int,
    *,
    pump: Callable[[], None],
    physics_steps: Callable[[], int] | None = None,
    materialize: Callable[[int], None] | None = None,
    assert_quiescent: Callable[[], None] | None = None,
) -> None:
    """Apply frames in order and fail at the first sign of simulation advancement."""
    before = physics_steps() if physics_steps is not None else None
    for frame in range(frames):
        replayer.apply_frame(frame)
        pump()
        if materialize is not None:
            materialize(frame)
        if assert_quiescent is not None:
            assert_quiescent()
    after = physics_steps() if physics_steps is not None else None
    if before is not None and after != before:
        raise RuntimeError(f"replay advanced physics: {before} -> {after}")


def _validate_render_coverage(rendered: list[dict[str, Any]], frames: int) -> None:
    expected = {(frame, role) for frame in range(frames) for role in CANONICAL_CAMERA_ROLES}
    actual = {(int(item["frame"]), str(item["role"])) for item in rendered}
    if actual != expected or len(rendered) != len(expected):
        raise RuntimeError(
            "offline RGB materialization is incomplete: "
            f"expected={len(expected)}, actual={len(rendered)}"
        )


def _bind_render_identity(
    rendered: list[dict[str, Any]],
    *,
    frame: int,
    session: ReplaySession,
    artifact: ReplayArtifact,
) -> None:
    """Bind every RGB to immutable D0, camera, renderer, and stage identities."""

    if not 0 <= frame < session.frames:
        raise IndexError(f"render frame {frame} is outside the replay session")
    cameras = {str(camera["role"]): camera for camera in artifact.visual_provenance["camera_roles"]}
    renderer_sha256 = artifact.visual_provenance["renderer"]["renderer_configuration_sha256"]
    materialization_revision = artifact.visual_provenance["materialization"][
        "materialization_revision"
    ]
    for item in rendered:
        role = str(item.get("role"))
        if int(item.get("frame", -1)) != frame or role not in cameras:
            raise RuntimeError("render output cannot be bound to the requested frame and camera")
        rgb_sha256 = item.get("sha256")
        if not isinstance(rgb_sha256, str) or len(rgb_sha256) != 64:
            raise RuntimeError("render output has no RGB SHA-256")
        camera = cameras[role]
        width, height = camera["resolution"]
        if item.get("shape") != [height, width, 3] or item.get("dtype") != "uint8":
            raise RuntimeError("render geometry differs from recorded camera provenance")
        item.update(
            {
                "asset_closure_sha256": artifact.asset_closure_sha256,
                "camera_configuration_sha256": camera["camera_configuration_sha256"],
                "camera_prim_path": camera["prim_path"],
                "camera_role": role,
                "materialization_revision": materialization_revision,
                "obs_id": session.observation_ids[frame],
                "renderer_configuration_sha256": renderer_sha256,
                "rgb_sha256": rgb_sha256,
                "scene_state_snapshot_id": session.scene_state_snapshot_ids[frame],
                "scene_state_snapshot_sha256": session.scene_state_snapshot_sha256[frame],
                "stage_snapshot_sha256": artifact.snapshot_sha256,
            }
        )


class ReplayRuntimeGuard:
    """Stop automatic simulation and count every PhysX callback during replay."""

    def __init__(self) -> None:
        self._timeline: Any = None
        self._subscription: Any = None
        self.physics_callbacks: list[float] = []

    def configure(self) -> None:
        import carb.settings
        import omni.replicator.core as rep
        import omni.timeline

        settings = carb.settings.get_settings()
        settings.set("/app/player/playSimulations", False)
        rep.orchestrator.set_capture_on_play(False)
        self._timeline = omni.timeline.get_timeline_interface()
        self._timeline.stop()
        if self._timeline.is_playing():
            raise RuntimeError("failed to stop timeline before replay")

    def start_monitoring(self) -> None:
        import omni.physx

        if self._subscription is not None:
            raise RuntimeError("replay physics monitoring already started")
        self.physics_callbacks.clear()
        self._subscription = omni.physx.get_physx_interface().subscribe_physics_step_events(
            lambda dt: self.physics_callbacks.append(float(dt))
        )

    def assert_quiescent(self) -> None:
        if self._timeline is None or self._timeline.is_playing():
            raise RuntimeError("timeline started during state-only replay")
        if self.physics_callbacks:
            raise RuntimeError(f"replay emitted {len(self.physics_callbacks)} physics callbacks")

    def close(self) -> None:
        subscription, self._subscription = self._subscription, None
        if subscription is not None and hasattr(subscription, "unsubscribe"):
            subscription.unsubscribe()


class ReplayCameraMaterializer:
    """Own one persistent render product/annotator per recorded camera role."""

    def __init__(self, camera_paths: Mapping[str, str], output_dir: Path, *,
                 resolutions: Mapping[str, Sequence[int]] | None = None) -> None:
        self.camera_paths = dict(camera_paths)
        self.resolutions = dict(resolutions or {role: (640, 480) for role in CANONICAL_CAMERA_ROLES})
        if set(self.resolutions) != set(CANONICAL_CAMERA_ROLES) or any(
            tuple(size) not in ((640, 480), (960, 600)) for size in self.resolutions.values()
        ):
            raise ValueError("Replay camera resolutions must match a supported recorded schema")
        self.output_dir = output_dir
        self.products: dict[str, Any] = {}
        self.annotators: dict[str, Any] = {}
        self.attached_roles: set[str] = set()
        self._settings: Any = None
        self._previous_orchestrator_enabled: bool | None = None

    def open(self) -> None:
        import carb.settings
        import omni.replicator.core as rep

        if self.output_dir.exists() or self.output_dir.is_symlink():
            raise FileExistsError(f"render output directory already exists: {self.output_dir}")
        self.output_dir.mkdir(parents=True, mode=0o700)
        self.output_dir.chmod(0o700)
        self._settings = carb.settings.get_settings()
        self._previous_orchestrator_enabled = self._settings.get_as_bool(
            "/exts/omni.replicator.core/Orchestrator/enabled"
        )
        # State-only replay has no live Fabric simulation-time producer.  Turn
        # off the reference-time gate so attached RGB annotators expose each
        # explicitly rendered Hydra update without Replicator scheduling.
        self._settings.set("/exts/omni.replicator.core/Orchestrator/enabled", False)
        for role in CANONICAL_CAMERA_ROLES:
            self.products[role] = rep.create.render_product(
                self.camera_paths[role], tuple(self.resolutions[role]), force_new=True
            )
            annotator = rep.AnnotatorRegistry.get_annotator("rgb")
            self.annotators[role] = annotator
            annotator.attach(self.products[role])
            self.attached_roles.add(role)
        # Render products and SyntheticData graphs are initialized lazily.  A
        # bounded stopped-timeline warm-up mirrors the pinned Replicator's own
        # async-rendering integration test and prevents the first capture from
        # racing graph creation.
        import omni.kit.app

        for _ in range(3):
            omni.kit.app.get_app().update()

    def render(self, frame: int) -> list[dict[str, Any]]:
        import omni.kit.app
        from PIL import Image

        if set(self.annotators) != set(CANONICAL_CAMERA_ROLES):
            raise RuntimeError("all three canonical replay cameras must be prepared")
        for _ in range(4):
            omni.kit.app.get_app().update()
        rendered: list[dict[str, Any]] = []
        for role in CANONICAL_CAMERA_ROLES:
            image = np.asarray(self.annotators[role].get_data())
            width, height = self.resolutions[role]
            if image.shape not in ((height, width, 4), (height, width, 3)) or image.dtype != np.uint8:
                raise RuntimeError(f"{role}: unexpected RGB buffer {image.shape} {image.dtype}")
            path = self.output_dir / f"frame_{frame:06d}_{role}.png"
            Image.fromarray(image[..., :3]).save(path)
            path.chmod(0o600)
            rendered.append(
                {
                    "dtype": "uint8",
                    "frame": frame,
                    "path": str(path),
                    "role": role,
                    "sha256": _sha256(path),
                    "shape": [height, width, 3],
                }
            )
        return rendered

    def close(self) -> None:
        for role in tuple(self.attached_roles):
            self.annotators[role].detach()
            self.attached_roles.remove(role)
        for product in self.products.values():
            product.destroy()
        if self._settings is not None and self._previous_orchestrator_enabled is not None:
            self._settings.set(
                "/exts/omni.replicator.core/Orchestrator/enabled",
                self._previous_orchestrator_enabled,
            )
        self._settings = None
        self._previous_orchestrator_enabled = None
        self.annotators.clear()
        self.products.clear()


def _open_verified_snapshot(artifact: ReplayArtifact, simulation_app: Any) -> None:
    """Open and settle the verified snapshot before any Recordable is prepared."""
    import omni.usd

    context = omni.usd.get_context()
    result = context.open_stage(str(artifact.snapshot))
    if result is False:
        raise RuntimeError(f"failed to open recorded stage: {artifact.snapshot}")
    # Opening and renderer initialization are asynchronous in Kit.  These updates
    # happen with playSimulations=false and before replay monitoring starts.
    for _ in range(20):
        simulation_app.update()
    stage = context.get_stage()
    if stage is None:
        raise RuntimeError(f"recorded stage did not open: {artifact.snapshot}")
    root_identifier = Path(stage.GetRootLayer().realPath or stage.GetRootLayer().identifier)
    if root_identifier.resolve() != artifact.snapshot:
        raise RuntimeError(
            f"opened USD root {root_identifier} != verified snapshot {artifact.snapshot}"
        )
    try:
        assert_visual_provenance_matches(artifact.visual_provenance, stage)
    except VisualProvenanceError as exc:
        raise RuntimeError(f"replay visual provenance mismatch: {exc}") from exc


def replay_from_snapshot(
    simulation_app: Any,
    *,
    recording: Path,
    episode: int,
    render_cameras: Path | None,
    report_path: Path,
    portable_roots: Mapping[str, str | Path],
    physics_steps: Callable[[], int] | None = None,
) -> int:
    """Replay a verified artifact in Kit without constructing a current task scene."""
    artifact = verify_recording_artifact(recording, portable_roots=portable_roots)
    report_candidate = report_path.expanduser().resolve(strict=False)
    protected_inputs = {
        artifact.recording,
        artifact.snapshot,
        artifact.manifest_path,
        artifact.asset_closure_path,
        artifact.terminal_successor_path,
        artifact.recording.parent / "recording_state.json",
    }
    if report_candidate in protected_inputs:
        raise ValueError("replay report path would overwrite a verified input artifact")
    if report_candidate.exists() or report_candidate.is_symlink():
        raise FileExistsError(f"replay report path already exists: {report_candidate}")
    report_path = report_candidate

    from isaacsim.replicator.episode_recorder import (
        EpisodeReplayer,
        ReplayPolicy,
        SessionReader,
    )
    from isaac_vr_recording import ensure_d0_recordable

    ensure_d0_recordable()
    with SessionReader(str(artifact.recording)) as reader:
        session = _validate_session(reader, artifact, episode)

    guard = ReplayRuntimeGuard()
    replayer: Any = None
    materializer: ReplayCameraMaterializer | None = None
    rendered: list[dict[str, Any]] = []
    prepared_groups: tuple[str, ...] = ()
    try:
        guard.configure()
        _open_verified_snapshot(artifact, simulation_app)
        guard.start_monitoring()
        replayer = EpisodeReplayer(
            str(artifact.recording),
            policy=ReplayPolicy(strictness="strict"),
            pose_backend="usd",
        )
        replayer.prepare_episode(session.episode_name)
        # Pinned Episode Recorder 0.1.6 exposes the prepared list as a public
        # property, not a callable accessor.
        prepared_groups = tuple(recordable.group for recordable in replayer.prepared_recordables)
        recorded_groups = {str(track["group"]) for track in session.tracks}
        if set(prepared_groups) != recorded_groups or len(prepared_groups) != len(
            set(prepared_groups)
        ):
            raise RuntimeError(
                "strict replay did not prepare every recorded group exactly once: "
                f"prepared={sorted(prepared_groups)}, recorded={sorted(recorded_groups)}"
            )
        if render_cameras is not None:
            materializer = ReplayCameraMaterializer(
                artifact.camera_paths, render_cameras, resolutions={
                    entry["role"]: entry["resolution"]
                    for entry in artifact.visual_provenance["camera_roles"]
                },
            )
            materializer.open()

        def materialize(frame: int) -> None:
            if materializer is not None:
                frame_renders = materializer.render(frame)
                _bind_render_identity(
                    frame_renders,
                    frame=frame,
                    session=session,
                    artifact=artifact,
                )
                rendered.extend(frame_renders)

        apply_replay_frames(
            replayer,
            session.frames,
            pump=simulation_app.update,
            physics_steps=physics_steps,
            materialize=materialize,
            assert_quiescent=guard.assert_quiescent,
        )
        guard.assert_quiescent()
    finally:
        if materializer is not None:
            materializer.close()
        if replayer is not None:
            replayer.close()
        guard.close()

    if render_cameras is not None:
        _validate_render_coverage(rendered, session.frames)

    report = {
        "schema": "piper_x_isaac_vr_replay_report_v3",
        "recording": str(artifact.recording),
        "recording_sha256": artifact.hdf5_sha256,
        "stage_snapshot": str(artifact.snapshot),
        "stage_snapshot_sha256": artifact.snapshot_sha256,
        "asset_closure": str(artifact.asset_closure_path),
        "asset_closure_sha256": artifact.asset_closure_sha256,
        "visual_provenance_sha256": artifact.visual_provenance_sha256,
        "terminal_successor": str(artifact.terminal_successor_path),
        "terminal_successor_sha256": artifact.terminal_successor_sha256,
        "episode": session.episode_name,
        "frames_applied": session.frames,
        "physics_callbacks": len(guard.physics_callbacks),
        "native_action_replay": False,
        "strict_policy": True,
        "required_tracks": sorted(REQUIRED_TRACKS),
        "tracks": list(session.tracks),
        "prepared_groups": list(prepared_groups),
        "applied_group_frames": {group: session.frames for group in prepared_groups},
        "camera_paths": dict(artifact.camera_paths),
        "renders": rendered,
        "d0": {
            "observation_ids": list(session.observation_ids),
            "committed_count": session.committed_count,
        },
    }
    report_path.parent.mkdir(parents=True, exist_ok=True)
    report_path.write_text(json.dumps(report, indent=2, sort_keys=True) + "\n")
    print("REPLAY_RESULT_JSON=" + json.dumps(report, sort_keys=True), flush=True)
    return 0


def replay(
    env: Any,
    simulation_app: Any,
    *,
    recording: Path,
    episode: int,
    render_cameras: Path | None,
    report_path: Path,
    portable_roots: Mapping[str, str | Path],
) -> int:
    """Compatibility wrapper pending the runtime's pre-scene integration."""
    return replay_from_snapshot(
        simulation_app,
        recording=recording,
        episode=episode,
        render_cameras=render_cameras,
        report_path=report_path,
        portable_roots=portable_roots,
        physics_steps=env.sim.get_physics_step_count,
    )

#!/usr/bin/env python3
"""Host-side, bimanual Quest controller diagnostics for Gate B.

This module owns one NVIDIA ``TeleopSession`` per process and exposes the two
outputs of one ``ControllersSource``.  It deliberately has no Robot, CAN, IK,
frame-calibration, dataset, or action-send dependency.
"""

from __future__ import annotations

import argparse
import json
from importlib.metadata import version
import socket
import time
from dataclasses import asdict, dataclass
from pathlib import Path
from typing import Any, Callable, Literal

import numpy as np

from isaacteleop.cloudxr import CloudXRLauncher
from isaacteleop.cloudxr.oob_teleop_env import versioned_web_client_url
from isaacteleop.retargeting_engine.deviceio_source_nodes import ControllersSource
from isaacteleop.retargeting_engine.interface import ExecutionEvents, ExecutionState, OutputCombiner
from isaacteleop.retargeting_engine.tensor_types.indices import ControllerInputIndex
from isaacteleop.teleop_session_manager import TeleopSession, TeleopSessionConfig

Hand = Literal["left", "right"]

_CLOUDXR_WSS_PORT = 48322


@dataclass(frozen=True)
class ControllerDiagnostic:
    """One raw controller sample, with validity kept distinct from availability."""

    hand: Hand
    availability: Literal["available", "unavailable", "malformed"]
    host_receipt_monotonic_ns: int
    grip_position: list[float] | None
    grip_orientation_xyzw: list[float] | None
    tracking: dict[str, bool | None]
    controls: dict[str, float | None]


class SharedQuestSession:
    """The sole Gate-B construction path for a shared left/right TeleopSession.

    ``ControllersSource`` creates one NVIDIA controller tracker and offers both
    outputs.  This class blocks a second live project instance in the process;
    it never creates a per-hand session.
    """

    _active_owner: "SharedQuestSession | None" = None
    _session_instances_created = 0

    def __init__(
        self,
        *,
        app_name: str = "PiperXQuest3BimanualDiagnostics",
        cloudxr_env_file: str | None = None,
        auto_launch_cloudxr: bool = True,
        monotonic_ns: Callable[[], int] = time.monotonic_ns,
    ) -> None:
        self.app_name = app_name
        self.cloudxr_env_file = cloudxr_env_file
        self.auto_launch_cloudxr = auto_launch_cloudxr
        self._monotonic_ns = monotonic_ns
        self._cloudxr_launcher: CloudXRLauncher | None = None
        self._controllers: ControllersSource | None = None
        self._session: TeleopSession | None = None
        self._state = "new"
        self.events: list[dict[str, Any]] = []

    @property
    def session_instances_created(self) -> int:
        """Count of project TeleopSession constructions in this process."""
        return type(self)._session_instances_created

    @property
    def is_running(self) -> bool:
        return self._session is not None

    def lifecycle_status(self) -> dict[str, Any]:
        """Return only lifecycle facts observable by this host-side code."""
        return {
            "cloudxr_auto_launch": self.auto_launch_cloudxr,
            "cloudxr_launcher_owned": self._cloudxr_launcher is not None,
            "nvidia_client_connection_state": "not_exposed_by_pinned_api",
            "process_local_session_instances_created": self.session_instances_created,
            "session_state": self._state,
            "shared_controller_source": self._controllers is not None,
        }

    def start(self) -> None:
        """Start CloudXR (if owned) then construct and enter one shared session."""
        if self._session is not None:
            raise RuntimeError("Quest diagnostic session is already running.")
        if type(self)._active_owner not in (None, self):
            raise RuntimeError("A Gate-B TeleopSession is already live in this process.")

        self._state = "starting"
        try:
            if self.auto_launch_cloudxr:
                self._cloudxr_launcher = CloudXRLauncher(
                    install_dir=str(Path.home() / ".cloudxr"),
                    env_config=self.cloudxr_env_file,
                    accept_eula=False,
                )
                self._event("cloudxr_launcher_created")

            self._controllers = ControllersSource(name="quest_bimanual_controllers")
            pipeline = OutputCombiner(
                {
                    "left": self._controllers.output(ControllersSource.LEFT),
                    "right": self._controllers.output(ControllersSource.RIGHT),
                }
            )
            self._session = TeleopSession(TeleopSessionConfig(app_name=self.app_name, pipeline=pipeline))
            type(self)._session_instances_created += 1
            self._event("teleop_session_constructed")
            self._session.__enter__()
            type(self)._active_owner = self
            self._state = "running"
            self._event("teleop_session_started")
        except Exception:
            self._state = "failed"
            self._stop_after_failed_start()
            raise

    def poll(self) -> dict[str, Any]:
        """Read both streams from one session and stamp their host receipt time."""
        if self._session is None:
            raise RuntimeError("Quest diagnostic session is not running.")

        result = self._session.step(
            execution_events=ExecutionEvents(execution_state=ExecutionState.RUNNING, reset=False)
        )
        receipt_ns = self._monotonic_ns()
        left = self._extract_controller("left", result["left"], receipt_ns)
        right = self._extract_controller("right", result["right"], receipt_ns)
        step_info = self._session.last_step_info
        snapshot = {
            "event": "controller_sample",
            "lifecycle": self.lifecycle_status(),
            "left": asdict(left),
            "right": asdict(right),
            "session_step": {
                "frame_deadline_miss": getattr(step_info, "frame_deadline_miss", None),
                "returned_age_frames": getattr(step_info, "returned_age_frames", None),
            },
        }
        return snapshot

    def close(self) -> None:
        """Tear down the OpenXR session before the CloudXR runtime."""
        session, self._session = self._session, None
        try:
            if session is not None:
                session.__exit__(None, None, None)
                self._event("teleop_session_stopped")
        finally:
            if type(self)._active_owner is self:
                type(self)._active_owner = None
            self._stop_cloudxr()
            if self._state != "failed":
                self._state = "stopped"
                self._event("diagnostic_stopped")

    def _stop_after_failed_start(self) -> None:
        session, self._session = self._session, None
        try:
            if session is not None:
                session.__exit__(None, None, None)
        finally:
            self._stop_cloudxr()

    def _stop_cloudxr(self) -> None:
        launcher, self._cloudxr_launcher = self._cloudxr_launcher, None
        if launcher is not None:
            launcher.stop()
            self._event("cloudxr_launcher_stopped")

    def _event(self, event: str) -> None:
        self.events.append(
            {
                "event": event,
                "process_local_session_instances_created": self.session_instances_created,
                "session_state": self._state,
            }
        )

    @staticmethod
    def _extract_controller(hand: Hand, controller: Any, receipt_ns: int) -> ControllerDiagnostic:
        controls: dict[str, float | None] = {
            "primary_click": None,
            "secondary_click": None,
            "thumbstick_x": None,
            "thumbstick_y": None,
            "thumbstick_click": None,
            "menu_click": None,
            "squeeze_value": None,
            "trigger_value": None,
        }
        tracking: dict[str, bool | None] = {
            "controller_available": False,
            "grip_pose_valid": None,
            "aim_pose_valid": None,
        }
        if getattr(controller, "is_none", False):
            return ControllerDiagnostic(hand, "unavailable", receipt_ns, None, None, tracking, controls)

        tracking["controller_available"] = True
        try:
            position = np.asarray(controller[ControllerInputIndex.GRIP_POSITION], dtype=float).tolist()
            orientation = np.asarray(
                controller[ControllerInputIndex.GRIP_ORIENTATION], dtype=float
            ).tolist()
            tracking["grip_pose_valid"] = bool(controller[ControllerInputIndex.GRIP_IS_VALID])
            tracking["aim_pose_valid"] = bool(controller[ControllerInputIndex.AIM_IS_VALID])
            for name, index in (
                ("primary_click", ControllerInputIndex.PRIMARY_CLICK),
                ("secondary_click", ControllerInputIndex.SECONDARY_CLICK),
                ("thumbstick_x", ControllerInputIndex.THUMBSTICK_X),
                ("thumbstick_y", ControllerInputIndex.THUMBSTICK_Y),
                ("thumbstick_click", ControllerInputIndex.THUMBSTICK_CLICK),
                ("menu_click", ControllerInputIndex.MENU_CLICK),
                ("squeeze_value", ControllerInputIndex.SQUEEZE_VALUE),
                ("trigger_value", ControllerInputIndex.TRIGGER_VALUE),
            ):
                controls[name] = float(controller[index])
        except (IndexError, KeyError, TypeError, ValueError):
            return ControllerDiagnostic(hand, "malformed", receipt_ns, None, None, tracking, controls)
        return ControllerDiagnostic(hand, "available", receipt_ns, position, orientation, tracking, controls)


def _print_json(value: dict[str, Any]) -> None:
    print(json.dumps(value, sort_keys=True, separators=(",", ":")))


def _host_connection_hint() -> dict[str, Any]:
    """Reuse the official example's primary-IPv4 discovery for the CloudXR client."""
    with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
        try:
            sock.connect(("8.8.8.8", 80))
            host_ipv4: str | None = sock.getsockname()[0]
        except OSError:
            host_ipv4 = None
    return {
        "cloudxr_web_client_url": versioned_web_client_url(version("isaacteleop")),
        "host_ipv4": host_ipv4,
        "self_signed_certificate_url": (
            f"https://{host_ipv4}:{_CLOUDXR_WSS_PORT}/" if host_ipv4 is not None else None
        ),
    }


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--cloudxr-env-file", default=None)
    parser.add_argument("--no-auto-launch-cloudxr", action="store_true")
    parser.add_argument("--sample-period-s", type=float, default=0.25)
    parser.add_argument("--max-samples", type=int, default=0, help="0 means run until Ctrl-C.")
    args = parser.parse_args()

    diagnostic = SharedQuestSession(
        cloudxr_env_file=args.cloudxr_env_file,
        auto_launch_cloudxr=not args.no_auto_launch_cloudxr,
    )
    _print_json(
        {
            "event": "diagnostic_created",
            "lifecycle": diagnostic.lifecycle_status(),
            "quest_connection": _host_connection_hint(),
        }
    )
    diagnostic.start()
    for event in diagnostic.events:
        _print_json(event)
    samples = 0
    try:
        while args.max_samples == 0 or samples < args.max_samples:
            _print_json(diagnostic.poll())
            samples += 1
            time.sleep(args.sample_period_s)
    except KeyboardInterrupt:
        _print_json({"event": "keyboard_interrupt"})
    finally:
        diagnostic.close()
        for event in diagnostic.events:
            if event["event"] in {"teleop_session_stopped", "cloudxr_launcher_stopped", "diagnostic_stopped"}:
                _print_json(event)


if __name__ == "__main__":
    main()

"""Selected VR composition and explicit, opt-in external asset qualification."""

from __future__ import annotations

import hashlib
import math
from pathlib import Path
from typing import TYPE_CHECKING

import yaml

if TYPE_CHECKING or __package__:
    from .isaac_demo_launch import git
else:
    from isaac_demo_launch import git

ROOT = Path(__file__).resolve().parents[1]
CONFIG_PATH = ROOT / "configs/isaac61_vr_runtime.yaml"
ASSET_LAB_CONFIG = ROOT / "configs/experiments/robosyn_asset_lab.yaml"
XR_RESOLUTION_SETTING = "/persistent/xr/profile/ar/render/resolutionMultiplier"


def xr_render_readback(config: dict, settings) -> dict:
    """Check Kit's host render-buffer scale; never change spatial/camera scale."""
    requested = config.get("xr_render")
    if requested is None:
        return {}
    effective = settings.get(XR_RESOLUTION_SETTING)
    if effective is None or not math.isclose(
        float(effective), requested["resolution_scale"], rel_tol=1e-6
    ):
        raise RuntimeError(f"XR resolution override not effective: {requested}; readback={effective}")
    return {**requested, "effective_resolution_scale": float(effective)}


def load_composition(profile: str) -> dict:
    config = yaml.safe_load(CONFIG_PATH.read_text())
    if profile in config["profiles"]["available"]:
        return config
    if profile != "robosyn_asset_lab":
        raise ValueError(f"Unknown VR profile: {profile}")
    overlay = yaml.safe_load(ASSET_LAB_CONFIG.read_text())
    if overlay["status"] != "EXPERIMENTAL_TEST_ONLY_NOT_A_GATE":
        raise RuntimeError("asset lab must remain experimental")
    manifest_path = ROOT / overlay["asset_manifest"]
    manifest = yaml.safe_load(manifest_path.read_text())
    checkout = Path(manifest["source_checkout"])
    if git(checkout, "rev-parse", "HEAD") != manifest["source_commit"] or git(
        checkout, "status", "--porcelain", "--untracked-files=all"
    ):
        raise RuntimeError(f"RoboSyn test checkout is not clean/pinned: {checkout}")
    for item in manifest["assets"]:
        path = checkout / item["source_path"]
        if hashlib.sha256(path.read_bytes()).hexdigest() != item["sha256"]:
            raise RuntimeError(f"RoboSyn test asset hash mismatch: {path}")
    config["asset_lab"] = {**overlay, "source_checkout": str(checkout)}
    return config

#!/usr/bin/env python3
from __future__ import annotations
import re
from pathlib import Path
import yaml

GATE_RE = re.compile(r"\[\[gate:([A-Za-z0-9_]+)\]\]")
PROFILE_RE = re.compile(r"\[\[profile:([A-Za-z0-9_]+)\]\]")
SOURCE_RE = re.compile(r"\[\[source:([A-Za-z0-9_]+)\]\]")


def check_references(
    text: str, name: str, gates: set[str], profiles: set[str], sources: set[str]
) -> list[str]:
    errors: list[str] = []
    # Mentions explaining why v5.2 bans old magic placeholders are allowed only in README/NORMATIVE/MIGRATION.
    if name not in {"README.md", "NORMATIVE_MODEL.md", "MIGRATION_V4_3_V5_1_TO_V5_2.md"}:
        if "DECIDE/PIN" in text or "MIGRATE/PRESERVE" in text:
            errors.append(f"{name}: legacy magic placeholder text forbidden")

    for st in re.findall(r"\bstatus\.[A-Za-z0-9_]+", text):
        errors.append(f"{name}: stale/unknown status reference {st}")
    for x in GATE_RE.findall(text):
        if x not in gates:
            errors.append(f"{name}: unknown gate {x}")
    for x in PROFILE_RE.findall(text):
        if x not in profiles:
            errors.append(f"{name}: unknown profile {x}")
    for x in SOURCE_RE.findall(text):
        if x not in sources:
            errors.append(f"{name}: unknown source {x}")
    return errors


def main():
    root = Path(__file__).resolve().parent.parent
    c = yaml.safe_load((root / "configs/resolved_contract.yaml").read_text(encoding="utf-8"))
    r = yaml.safe_load((root / "configs/gate_rules.yaml").read_text(encoding="utf-8"))
    gates = set(r)
    profiles = set(c["execution_profiles"])
    sources = set(c["taxonomy"]["source_classes"])
    errors = []
    spec_paths = [*root.glob("*.md"), *(root / "docs").glob("*.md")]
    for p in sorted(spec_paths):
        errors.extend(
            check_references(p.read_text(encoding="utf-8"), p.name, gates, profiles, sources)
        )
    if errors:
        print("SPEC REFERENCE LINT FAILED")
        [print("-", e) for e in errors]
        return 1
    print("SPEC REFERENCE LINT OK")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""D0 transaction identities; no simulator, dataset, or physical-clock dependency."""

from __future__ import annotations

from collections import Counter
from dataclasses import dataclass
from hashlib import sha256
from typing import Mapping

from tools.d0_temporal import PhysicalTimingValidator, PreparedTemporalFrame, SourceTiming
from tools.d0_temporal import TemporalContractViolation


CAMERAS = ("left_wrist", "right_wrist", "scene")
SIM_SOURCES = ("simulation.state_generation", *(f"camera.{role}" for role in CAMERAS))
OFFLINE_RGB_SIM_SOURCES = ("simulation.scene_state_snapshot",)
XR_SOURCES = ("xr.device_io_update", "xr.submitted_frame", "xr.returned_frame", "xr.resolved_input")
AUTOMATED = frozenset(("scripted_expert", "planner", "datagen", "policy_generated"))
ISAAC_HUMAN_PROFILES = frozenset((
    "isaac_human_vr_v4", "isaac_human_vr_offline_rgb_v1", "isaac_human_vr_offline_rgb_v2"
))


def select_temporal_profile(
    runtime: str, source_class: str, *, requested: str | None = None
) -> str:
    if requested is not None:
        if runtime == "isaac" and source_class == "human_vr" and requested in ISAAC_HUMAN_PROFILES:
            return requested
        raise ValueError(f"temporal profile {requested!r} is not valid for {runtime}/{source_class}")
    if runtime == "isaac" and source_class in AUTOMATED:
        return "isaac_automated_v4"
    if source_class == "human_vr" and runtime in ("isaac", "real"):
        return "isaac_human_vr_v4" if runtime == "isaac" else "real_human_vr_physical_v4"
    raise ValueError(f"no admitted temporal profile for {runtime}/{source_class}")


@dataclass(frozen=True)
class Epoch:
    run_id: str
    episode_id: str
    source_id: str
    reset_epoch: int
    control_reference_epoch: int
    source_epoch: str  # XR session epoch or generator/source lifecycle epoch.

    def __post_init__(self) -> None:
        if not all(
            isinstance(v, str) and v
            for v in (self.run_id, self.episode_id, self.source_id, self.source_epoch)
        ) or any(
            type(v) is not int or v < 0 for v in (self.reset_epoch, self.control_reference_epoch)
        ):
            raise ValueError("invalid epoch identity")


@dataclass(frozen=True)
class PayloadIdentity:
    epoch: Epoch
    control_tick_id: int
    payload_id: str
    sha256: str

    def __post_init__(self) -> None:
        if (
            type(self.control_tick_id) is not int
            or self.control_tick_id < 0
            or not self.payload_id
            or len(self.sha256) != 64
            or any(c not in "0123456789abcdef" for c in self.sha256)
        ):
            raise ValueError("invalid payload identity")

    @classmethod
    def bind(cls, epoch: Epoch, tick: int, payload_id: str, payload: bytes) -> PayloadIdentity:
        return cls(epoch, tick, payload_id, sha256(payload).hexdigest())


@dataclass(frozen=True)
class SourceIdentity:
    name: str
    sample: PayloadIdentity
    sequence: int

    def __post_init__(self) -> None:
        if not self.name or type(self.sequence) is not int or self.sequence < 0:
            raise ValueError("invalid source identity")


@dataclass(frozen=True)
class PreparedTransaction:
    observation: PayloadIdentity
    dataset_action: PayloadIdentity
    sources: tuple[SourceIdentity, ...]
    physical: PreparedTemporalFrame | None
    generator: tuple[str | None, str | None, int | None]


@dataclass(frozen=True)
class CompletedTransition:
    native_command: PayloadIdentity
    transition_id: str
    successor: PayloadIdentity


class CausalTransactionValidator:
    """One pending transaction; identities retained for the lifetime of one run.

    Bytes are an edge-owned canonical serialization (including dtype/shape/role),
    or immutable content-addressed references. Images are never retained here.
    Real persistence at send-return remains a separate compatibility seam; full
    transition proof requires a subsequent observation and does not prove motion.
    """

    def __init__(
        self,
        runtime: str,
        source_class: str,
        epoch: Epoch,
        *,
        physical: PhysicalTimingValidator | None = None,
        profile: str | None = None,
    ) -> None:
        self.profile = select_temporal_profile(runtime, source_class, requested=profile)
        if (physical is not None) != (runtime == "real"):
            raise ValueError("only the real profile requires a physical timing validator")
        if physical is not None and set(physical.required_sources) != {
            "observation.state",
            *(f"observation.images.{role}" for role in CAMERAS),
            "xr.left_pose",
            "xr.right_pose",
            "source_action",
        }:
            raise ValueError("real profile requires all seven physical source streams")
        self.epoch = epoch
        self.physical = physical
        self._epochs = {epoch}
        self._expected_observation: PayloadIdentity | None = None
        self._pending: PreparedTransaction | None = None
        self._completion: CompletedTransition | None = None
        self._persisted = False
        self._ticks: dict[Epoch, int] = {}
        self._sequences: dict[tuple[Epoch, str], int] = {}
        self._ids: set[tuple[str, str]] = set()
        self.accepted_transactions = 0
        self.rejected: Counter[str] = Counter()

    def _reject(self, reason: str) -> None:
        self.rejected[reason] += 1
        raise TemporalContractViolation(reason, "causal transaction rejected")

    def begin_epoch(self, epoch: Epoch) -> None:
        if epoch in self._epochs or epoch.run_id != self.epoch.run_id:
            self._reject("epoch_reuse")
        self.abort()
        self.epoch = epoch
        self._expected_observation = None
        self._epochs.add(epoch)
        if self.physical:
            self.physical.reset_episode()

    def _at(self, item: PayloadIdentity, tick: int) -> None:
        if item.epoch != self.epoch:
            self._reject("epoch_crossing")
        if item.control_tick_id != tick:
            self._reject("tick_mismatch")

    def prepare(
        self,
        observation: PayloadIdentity,
        dataset_action: PayloadIdentity,
        sources: tuple[SourceIdentity, ...],
        *,
        observation_payload: bytes,
        action_payload: bytes,
        tracking_valid: bool | None = None,
        generator_revision: str | None = None,
        generator_state: str | None = None,
        generator_seed: int | None = None,
        source_timing: Mapping[str, SourceTiming] | None = None,
        selection_timestamp: float | None = None,
    ) -> PreparedTransaction:
        if self._pending is not None:
            self._reject("transaction_pending")
        tick = observation.control_tick_id
        self._at(observation, tick)
        self._at(dataset_action, tick)
        if self._expected_observation is not None and observation != self._expected_observation:
            self._reject("successor_pairing_mismatch")
        if tick <= self._ticks.get(self.epoch, -1):
            self._reject("tick_reuse")
        self.verify_payload(observation, observation_payload)
        self.verify_payload(dataset_action, action_payload)
        if "human_vr" in self.profile and tracking_valid is not True:
            self._reject("tracking_invalid")
        names = tuple(source.name for source in sources)
        expected = SIM_SOURCES
        if self.profile == "isaac_human_vr_v4":
            expected += XR_SOURCES
            if tracking_valid is not True:
                self._reject("tracking_invalid")
        elif self.profile in {"isaac_human_vr_offline_rgb_v1", "isaac_human_vr_offline_rgb_v2"}:
            expected = OFFLINE_RGB_SIM_SOURCES + XR_SOURCES
            if tracking_valid is not True:
                self._reject("tracking_invalid")
        elif self.profile == "isaac_automated_v4":
            expected += ("generator.decision",)
            if not generator_revision or not generator_state:
                self._reject("generator_provenance_missing")
            if tracking_valid is not None or any(n.startswith("xr.") for n in names):
                self._reject("unexpected_xr")
        else:
            assert self.physical is not None
            expected = self.physical.required_sources
        if set(names) != set(expected) or len(names) != len(set(names)):
            self._reject("source_identity_set")
        for source in sources:
            self._at(source.sample, tick)
            if (source.name, source.sample.payload_id) in self._ids:
                self._reject("source_identity_reuse")
            key = (self.epoch, source.name)
            if source.sequence <= self._sequences.get(key, -1):
                self._reject("source_identity_reuse")
        physical = None
        if self.physical:
            if source_timing is None or selection_timestamp is None:
                self._reject("missing_timing_metadata")
            assert source_timing is not None and selection_timestamp is not None
            physical = self.physical.prepare_frame(
                source_timing, selection_timestamp=selection_timestamp
            )
            if any(s.sequence != source_timing[s.name].sequence for s in sources):
                self._reject("physical_identity_mismatch")
        elif source_timing is not None or selection_timestamp is not None:
            self._reject("unexpected_physical_timing")
        # Provenance values are immutable and bound into the decision identity by the edge.
        if generator_seed is not None and type(generator_seed) is not int:
            self._reject("invalid_generator_seed")
        for role, item in (("observation", observation), ("action", dataset_action)):
            if (role, item.payload_id) in self._ids:
                self._reject("payload_identity_reuse")
        prepared = PreparedTransaction(
            observation,
            dataset_action,
            tuple(sources),
            physical,
            (generator_revision, generator_state, generator_seed),
        )
        self._pending = prepared
        self._ticks[self.epoch] = tick
        for role, item in (("observation", observation), ("action", dataset_action)):
            self._ids.add((role, item.payload_id))
        for source in sources:
            self._ids.add((source.name, source.sample.payload_id))
            self._sequences[(self.epoch, source.name)] = source.sequence
        return prepared

    def _require_pending(self, prepared: PreparedTransaction) -> None:
        if prepared is not self._pending:
            self._reject("transaction_not_pending")
        self._at(prepared.observation, prepared.observation.control_tick_id)

    def complete_transition(
        self,
        prepared: PreparedTransaction,
        native_command: PayloadIdentity,
        transition_id: str,
        successor: PayloadIdentity,
        *,
        successful: bool,
    ) -> CompletedTransition:
        self._require_pending(prepared)
        tick = prepared.observation.control_tick_id
        self._at(native_command, tick)
        self._at(successor, tick + 1)
        if self._completion is not None or successful is not True or not transition_id:
            self._reject("transition_incomplete_or_repeated")
        for role, identity in (
            ("native", native_command.payload_id),
            ("transition", transition_id),
        ):
            if (role, identity) in self._ids:
                self._reject("transition_reuse")
        if ("observation", successor.payload_id) in self._ids:
            self._reject("successor_reuse")
        self._ids.update((("native", native_command.payload_id), ("transition", transition_id)))
        self._completion = CompletedTransition(native_command, transition_id, successor)
        return self._completion

    def verify_payload(self, identity: PayloadIdentity, payload: bytes) -> None:
        if sha256(payload).hexdigest() != identity.sha256:
            self._reject("payload_substitution")

    def validate_persistence(
        self, prepared: PreparedTransaction, *, observation_payload: bytes, action_payload: bytes
    ) -> None:
        """Real-only pre-successor write seam; this is not a causal commit."""
        self._require_pending(prepared)
        if self.physical is None or self._persisted:
            self._reject("invalid_persistence_phase")
        self.verify_payload(prepared.observation, observation_payload)
        self.verify_payload(prepared.dataset_action, action_payload)

    def mark_persisted(self, prepared: PreparedTransaction) -> None:
        """Called by the compatibility facade only after its writer succeeds."""
        self._require_pending(prepared)
        self._persisted = True

    def commit(
        self, prepared: PreparedTransaction, *, observation_payload: bytes, action_payload: bytes
    ) -> CompletedTransition:
        self._require_pending(prepared)
        if self._completion is None:
            self._reject("transition_not_completed")
        self.verify_payload(prepared.observation, observation_payload)
        self.verify_payload(prepared.dataset_action, action_payload)
        assert self._completion is not None
        result = self._completion
        if self.physical and not self._persisted:
            assert prepared.physical is not None
            self.physical.accept(prepared.physical)
        self._expected_observation = result.successor
        self.accepted_transactions += 1
        self.abort()
        return result

    def abort(self) -> None:
        self._pending = None
        self._completion = None
        self._persisted = False

"""Human demonstration state and publication, above recorder-owned episodes."""

from __future__ import annotations

from enum import Enum
import json
import os
from pathlib import Path
from typing import Callable
from uuid import uuid4


class RecordingState(str, Enum):
    WAITING = "waiting"
    RECORDING = "recording"
    REVIEW = "review"
    CLASSIFY_OUTCOME = "classify_outcome"
    RESETTING = "resetting"
    FAILED = "failed"
    INTERRUPTED = "interrupted"


class RecordingLifecycle:
    """Interpret button edges; callbacks retain recorder and environment ownership."""

    def __init__(
        self,
        *,
        seal: Callable[[str], None],
        publish: Callable[[str, str], None],
        reset: Callable[[], None],
        discard: Callable[[str], None] | None = None,
        interrupted: Callable[[str], None] | None = None,
        identity: Callable[[], str] = lambda: uuid4().hex,
    ) -> None:
        self.seal, self.publish, self.reset = seal, publish, reset
        self.discard, self.interrupted = discard, interrupted
        self.identity = identity
        self.state = RecordingState.WAITING
        self.demo_id: str | None = None
        self.error: str | None = None
        self._held = {"x": False, "y": False, "b": False}

    @property
    def admits_recording(self) -> bool:
        return self.state is RecordingState.RECORDING

    def buttons(self, *, x: bool, y: bool, b: bool) -> str | None:
        values = {"x": x, "y": y, "b": b}
        edges = {key: value and not self._held[key] for key, value in values.items()}
        self._held.update(values)
        if self.state is RecordingState.WAITING and edges["x"]:
            self.demo_id = self.identity()
            self.state = RecordingState.RECORDING
            return "start"
        if self.state is RecordingState.RECORDING and edges["y"]:
            self._seal("explicit_stop")
            self.state = RecordingState.REVIEW
            return "stop"
        if self.state is RecordingState.REVIEW:
            if edges["x"]:
                self.state = RecordingState.CLASSIFY_OUTCOME
                return "save"
            if edges["b"]:
                self._finish(outcome=None)
                return "discard"
        if self.state is RecordingState.CLASSIFY_OUTCOME:
            for button, outcome in (("x", "success"), ("y", "failure"), ("b", "incomplete")):
                if edges[button]:
                    self._finish(outcome=outcome)
                    return outcome
        return None

    def disconnect(self) -> None:
        self.interrupt("xr_disconnect")

    def interrupt(self, reason: str) -> None:
        if self.state not in (
            RecordingState.RECORDING, RecordingState.REVIEW, RecordingState.CLASSIFY_OUTCOME
        ):
            return
        if self.state is RecordingState.RECORDING:
            self._seal(reason)
        try:
            if self.interrupted is not None:
                assert self.demo_id is not None
                self.interrupted(self.demo_id)
        except Exception as exc:
            self.fail(exc)
            raise
        self.state = RecordingState.INTERRUPTED

    def external_reset(self) -> None:
        if self.state is RecordingState.RECORDING:
            self._seal("environment_reset_requested")
            self._finish(outcome=None)
        elif self.state is RecordingState.REVIEW:
            self._finish(outcome=None)
        elif self.state is RecordingState.CLASSIFY_OUTCOME:
            self.interrupt("environment_reset_requested")

    def fail(self, exc: Exception) -> None:
        self.error = f"{type(exc).__name__}: {exc}"
        self.state = RecordingState.FAILED

    def _seal(self, reason: str) -> None:
        # Admission closes before any recorder finalization is attempted.
        self.state = RecordingState.RESETTING
        try:
            self.seal(reason)
        except Exception as exc:
            self.fail(exc)
            raise

    def _finish(self, *, outcome: str | None) -> None:
        self.state = RecordingState.RESETTING
        try:
            if outcome is not None:
                assert self.demo_id is not None
                self.publish(self.demo_id, outcome)
            elif self.discard is not None:
                assert self.demo_id is not None
                self.discard(self.demo_id)
            self.reset()
        except Exception as exc:
            self.fail(exc)
            raise
        self.demo_id = None
        self.state = RecordingState.WAITING


def publish_saved_demo(
    root: Path,
    *,
    demo_id: str,
    episodes: list[dict],
    profile: str,
    start_tick: int,
    stop_tick: int,
    task_outcome: str,
) -> Path:
    """Atomically publish a classified demo without editing canonical manifests."""
    if task_outcome not in {"success", "failure", "incomplete"}:
        raise ValueError("task outcome must be success, failure, or incomplete")
    root.mkdir(parents=True, exist_ok=True)
    destination = root / f"{demo_id}.json"
    if destination.exists():
        raise FileExistsError(destination)
    source_schema = None
    row_schema = None
    for episode in episodes:
        manifest = Path(episode["output_dir"]) / "manifest.json"
        value = json.loads(manifest.read_text(encoding="utf-8"))
        if value["artifact_state"] != "finalized" or value["outcome"] != "operator_stopped":
            raise RuntimeError(f"episode is not conservatively finalized: {manifest}")
        marker = json.loads((manifest.parent / "recording_state.json").read_text(encoding="utf-8"))
        if (
            marker.get("artifact_state") != "finalized"
            or not isinstance(value.get("hdf5_sha256"), str)
            or len(value["hdf5_sha256"]) != 64
            or marker.get("hdf5_sha256") != value.get("hdf5_sha256")
        ):
            raise RuntimeError(f"episode has no matching finalized marker: {manifest}")
        identity = (value["schema"], value["transition_schema"])
        if source_schema is not None and identity != (source_schema, row_schema):
            raise RuntimeError(f"technical episode schema differs: {manifest}")
        source_schema, row_schema = identity
    if source_schema is None:
        raise RuntimeError("saved demonstration has no technical episodes")
    document = {
        "schema": "piper_x_isaac_vr_human_demo_v2",
        "demo_id": demo_id,
        "save_classification": "saved",
        "task_outcome": task_outcome,
        "lifecycle_disposition": "saved_and_classified",
        "source_profile": profile,
        "source_manifest_schema": source_schema,
        "committed_row_schema": row_schema,
        "start_control_tick": start_tick,
        "stop_control_tick": stop_tick,
        "technical_episodes": [
            {"episode_id": item["episode_id"], "output_dir": item["output_dir"]}
            for item in episodes
        ],
    }
    temporary = root / f".{demo_id}.{uuid4().hex}.tmp"
    try:
        temporary.write_text(
            json.dumps(document, indent=2, sort_keys=True) + "\n", encoding="utf-8"
        )
        os.link(temporary, destination)  # exclusive; never replace a prior classification
    finally:
        temporary.unlink(missing_ok=True)
    return destination


def publish_unsaved_demo(
    root: Path, *, demo_id: str, classification: str, episodes: list[dict]
) -> Path:
    """Keep conservative operator disposition apart from saved demonstrations."""
    if classification not in {"discarded", "interrupted"}:
        raise ValueError("unsaved demonstration classification must be discarded or interrupted")
    destination_root = root / f"{classification}_demos"
    destination_root.mkdir(parents=True, exist_ok=True)
    destination = destination_root / f"{demo_id}.json"
    document = {
        "schema": "piper_x_isaac_vr_human_demo_v1",
        "demo_id": demo_id,
        "classification": classification,
        "technical_episodes": [
            {"episode_id": item["episode_id"], "output_dir": item["output_dir"]}
            for item in episodes
        ],
    }
    temporary = destination_root / f".{demo_id}.{uuid4().hex}.tmp"
    try:
        temporary.write_text(
            json.dumps(document, indent=2, sort_keys=True) + "\n", encoding="utf-8"
        )
        os.link(temporary, destination)
    finally:
        temporary.unlink(missing_ok=True)
    return destination


def technical_episode_output_dir(
    *,
    first_dir: Path,
    recordings_root: Path | None,
    demo_id: str,
    episode_index: int,
    prior_episodes: bool,
    repository: Path,
    min_free_bytes: int = 1 << 30,
) -> Path:
    """Allocate only the demo parent; the current recorder owns episode dirs."""
    episode_id = f"episode_{episode_index:06d}"
    if episode_index == 0 and not prior_episodes:
        return first_dir
    if recordings_root is None:
        return Path(f"{first_dir}-{demo_id}-{episode_id}")
    demo_parent = recordings_root / demo_id
    if not demo_parent.exists():
        from tools.isaac_vr_recording import prepare_private_output_dir

        prepare_private_output_dir(
            demo_parent, repository=repository, min_free_bytes=min_free_bytes
        )
    return demo_parent / episode_id

"""One current three-camera boundary; no rendering, episode storage, or recorder."""

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass
from typing import Any

import numpy as np

ROLES = ("left_wrist", "right_wrist", "scene")


@dataclass(frozen=True)
class ProducerBoundary:
    reset_epoch: int
    physics_step: int
    render_generation: int


@dataclass(frozen=True)
class CameraIdentity:
    role: str
    frame: int
    data_generation: int


@dataclass(frozen=True)
class ObservationCapture:
    producer: ProducerBoundary
    capture_cycle: int
    cameras: tuple[CameraIdentity, ...]
    state: tuple[float, ...]
    eligible: bool


def tensor(value: Any) -> Any:
    return getattr(value, "torch", value)


def frame(camera: Any) -> int:
    return int(tensor(camera.frame).reshape(-1)[0].item())


class ThreeCameraCapture:
    """Qualify synchronous upstream extraction, then lend only its current boundary.

    SensorBase's completed data generation is checked before accessing ``data``:
    consumers must never trigger its lazy camera update. Buffers stay upstream-owned;
    only ``freeze`` requests three CPU RGB copies. Callers serialize physics/reset
    and capture/consumption on the simulation thread.
    """

    def __init__(
        self,
        cameras: dict[str, Any],
        boundary: Callable[[], ProducerBoundary],
        read_state: Callable[[], tuple[int, tuple[float, ...]]],
    ) -> None:
        if tuple(cameras) != ROLES:
            raise ValueError("Expected ordered left_wrist, right_wrist, scene")
        self.cameras = cameras
        self.boundary = boundary
        self.read_state = read_state
        self.successful_capture_cycle = 0
        self.failed_attempts = 0
        self.last_error: str | None = None
        self._latest: ObservationCapture | None = None
        self._buffers: dict[str, Any] = {}

    def invalidate(self) -> None:
        self._latest = None
        self._buffers.clear()

    @staticmethod
    def _output(camera: Any) -> Any:
        # Pinned SensorBase sets this receipt only AFTER extraction returns.
        if camera._data_generation_last_update != camera._data_generation:
            raise RuntimeError("Camera output has no completed producer generation")
        output = camera.data.output
        value = output.get("rgba", output.get("rgb"))
        cfg = getattr(camera, "cfg", None)
        height, width = (cfg.height, cfg.width) if cfg else (480, 640)
        if (height, width) not in ((480, 640), (600, 960)):
            raise RuntimeError("Unsupported source camera resolution")
        if value is None or tuple(value.shape) not in ((1, height, width, 3), (1, height, width, 4)):
            raise RuntimeError("Camera output missing or wrong shape")
        if str(tensor(value).dtype).split(".")[-1] != "uint8":
            raise RuntimeError("Camera output must be uint8")
        return value

    def capture(self, dt: float, *, eligible: bool = True) -> ObservationCapture | None:
        self.invalidate()
        try:
            producer = self.boundary()
            state_step, state = self.read_state()
            if state_step != producer.physics_step or self.boundary() != producer:
                raise RuntimeError("Measured state does not belong to capture boundary")
            if len(state) != 14 or not np.isfinite(state).all():
                raise RuntimeError("Invalid measured state")
            identities = []
            buffers = {}
            for role, camera in self.cameras.items():
                previous_frame, generation = frame(camera), camera._data_generation
                camera.update(dt, force_recompute=True)
                if frame(camera) != previous_frame + 1 or camera._data_generation <= generation:
                    raise RuntimeError(f"{role}: camera producer did not advance exactly once")
                buffers[role] = self._output(camera)
                identities.append(CameraIdentity(role, frame(camera), camera._data_generation))
            if self.boundary() != producer:
                raise RuntimeError("Producer changed during three-camera extraction")
            self._buffers = buffers
            candidate = ObservationCapture(
                producer, self.successful_capture_cycle + 1, tuple(identities), state, eligible
            )
            self._check_current(candidate)
            self._latest = candidate
            self.successful_capture_cycle += 1
            self.last_error = None
            return candidate
        except Exception as error:  # Reject the bundle; RUN policy belongs to its caller.
            self.invalidate()
            self.failed_attempts += 1
            self.last_error = str(error)
            return None

    def _check_current(self, capture: ObservationCapture) -> None:
        if self.boundary() != capture.producer:
            raise RuntimeError("Capture is no longer at the current producer boundary")
        for identity in capture.cameras:
            camera = self.cameras[identity.role]
            if frame(camera) != identity.frame or camera._data_generation != identity.data_generation:
                raise RuntimeError("Camera source identity changed after capture")
            if self._output(camera) is not self._buffers[identity.role]:
                raise RuntimeError("Camera buffer replaced after capture")
        if self.boundary() != capture.producer:
            raise RuntimeError("Producer changed while reading current capture")

    def latest(self, *, require_eligible: bool = True) -> ObservationCapture:
        if self._latest is None:
            raise RuntimeError(self.last_error or "No successful observation capture")
        self._check_current(self._latest)
        if require_eligible and not self._latest.eligible:
            raise RuntimeError("Startup settling is not an eligible observation")
        return self._latest

    def freeze(self) -> dict[str, np.ndarray]:
        """Optional owned CPU snapshot; no physics, camera update, or render call."""
        capture = self.latest()
        result = {"observation.state": np.asarray(capture.state, dtype=np.float32)}
        for role, buffer in self._buffers.items():
            rgb = tensor(buffer)[0, ..., :3]
            if hasattr(rgb, "detach"):
                rgb = rgb.detach().cpu().numpy()
            result[f"observation.images.{role}"] = np.array(rgb, dtype=np.uint8, copy=True)
        self._check_current(capture)
        return result

"""Thin production integration between LeRobot recording and the D0 temporal envelope.

The upstream ``record_loop`` remains responsible for observation/action processing,
actuation, pacing, and episode lifecycle.  This module only supplies timing at its
existing dataset boundary and delegates accepted frames to ``LeRobotDataset``.
"""

from __future__ import annotations

from collections.abc import Callable, Mapping
from dataclasses import dataclass
import time
from typing import Any, Protocol

from lerobot.teleoperators.teleoperator import Teleoperator

from tools.d0_temporal import PreparedTemporalFrame, SourceTiming, TemporalFrameRecorder


class ObservationTimingSource(Protocol):
    """Robot side-channel populated by the same ``get_observation`` call."""

    def latest_observation_timing(self) -> Mapping[str, SourceTiming]: ...


class FrameTimingProvider(Protocol):
    def current_frame_timing(self) -> Mapping[str, SourceTiming]: ...

    def reset_episode(self) -> None: ...


@dataclass(frozen=True)
class TimedTeleopAction:
    """An action and the exact XR pose identities used to produce it."""

    action: Mapping[str, Any]
    pose_timing: Mapping[str, SourceTiming]


TimedActionReader = Callable[[], TimedTeleopAction]


class TimestampedTeleoperator(Teleoperator):
    """Delegate an upstream teleoperator while exposing action/XR acquisition timing.

    ``source_action`` is born when ``get_action`` returns, so stamping that event with
    the same host monotonic clock is acquisition time, not a fallback.  XR pose timing
    must be supplied by the XR source itself; host receipt time is deliberately not
    substituted when that metadata is absent.
    """

    def __init__(
        self,
        teleop: Teleoperator,
        *,
        timed_action_reader: TimedActionReader | None,
        require_xr: bool,
        monotonic: Callable[[], float] = time.perf_counter,
    ) -> None:
        if require_xr and timed_action_reader is None:
            raise ValueError(
                "human_vr recording requires an atomic action/XR acquisition reader; "
                "a separate host receipt-time callback is not accepted"
            )
        self.teleop = teleop
        self.timed_action_reader = timed_action_reader
        self.require_xr = require_xr
        self.monotonic = monotonic
        self._action_sequence = 0
        self._latest_timing: dict[str, SourceTiming] | None = None
        self._before_action_return: Callable[[], None] | None = None

    @property
    def action_features(self) -> dict:
        return self.teleop.action_features

    @property
    def feedback_features(self) -> dict:
        return self.teleop.feedback_features

    @property
    def is_connected(self) -> bool:
        return self.teleop.is_connected

    @property
    def is_calibrated(self) -> bool:
        return self.teleop.is_calibrated

    def connect(self, calibrate: bool = True) -> None:
        self.teleop.connect(calibrate=calibrate)

    def calibrate(self) -> None:
        self.teleop.calibrate()

    def configure(self) -> None:
        self.teleop.configure()

    def get_action(self) -> dict[str, Any]:
        if self.require_xr:
            assert self.timed_action_reader is not None
            timed_action = self.timed_action_reader()
            if not isinstance(timed_action, TimedTeleopAction):
                raise ValueError("timed action reader must return TimedTeleopAction")
            action = dict(timed_action.action)
            pose_timing = dict(timed_action.pose_timing)
        else:
            action = self.teleop.get_action()
            pose_timing = {}
        action_timestamp = self.monotonic()
        self._action_sequence += 1
        timing: dict[str, SourceTiming] = {
            "source_action": SourceTiming(
                self._action_sequence,
                action_timestamp,
                "host_monotonic",
            )
        }
        if self.require_xr:
            expected = {"xr.left_pose", "xr.right_pose"}
            if set(pose_timing) != expected:
                raise ValueError(
                    "XR timing provider must return exactly xr.left_pose and xr.right_pose"
                )
            if not all(isinstance(value, SourceTiming) for value in pose_timing.values()):
                raise ValueError("XR timing provider returned incomplete timing metadata")
            timing.update(pose_timing)
        self._latest_timing = timing
        if self._before_action_return is not None:
            self._before_action_return()
        return action

    def set_before_action_return(self, callback: Callable[[], None]) -> None:
        if self._before_action_return is not None:
            raise RuntimeError("pre-actuation temporal callback is already configured")
        self._before_action_return = callback

    def send_feedback(self, feedback: dict[str, Any]) -> None:
        self.teleop.send_feedback(feedback)

    def disconnect(self) -> None:
        self.teleop.disconnect()

    def latest_action_timing(self) -> Mapping[str, SourceTiming]:
        if self._latest_timing is None:
            raise RuntimeError("no teleoperator action has been acquired for the current frame")
        return dict(self._latest_timing)

    def reset_episode(self) -> None:
        self._latest_timing = None


class LeRobotFrameTimingProvider:
    """Join the timing emitted by the real Robot and Teleoperator calls."""

    def __init__(
        self,
        robot: ObservationTimingSource,
        teleop: TimestampedTeleoperator,
        required_sources: tuple[str, ...],
    ) -> None:
        if not callable(getattr(robot, "latest_observation_timing", None)):
            raise ValueError("robot does not expose acquisition timing for get_observation")
        self.robot = robot
        self.teleop = teleop
        self.required_sources = required_sources

    def current_frame_timing(self) -> Mapping[str, SourceTiming]:
        raw_timing = {
            **dict(self.robot.latest_observation_timing()),
            **dict(self.teleop.latest_action_timing()),
        }
        timing: dict[str, SourceTiming] = {}
        for source, sample in raw_timing.items():
            if isinstance(sample, SourceTiming):
                timing[source] = sample
                continue
            try:
                timing[source] = SourceTiming(
                    sequence=sample.sequence,
                    source_timestamp=sample.source_timestamp,
                    clock_domain=sample.clock_domain,
                )
            except (AttributeError, TypeError, ValueError) as exc:
                raise ValueError(f"{source} returned incomplete source timing") from exc
        return timing

    def reset_episode(self) -> None:
        self.teleop.reset_episode()


class TemporalLeRobotDatasetAdapter:
    """Dataset-compatible proxy used directly by upstream ``record_loop``."""

    def __init__(
        self,
        dataset: Any,
        recorder: TemporalFrameRecorder,
        timing_provider: FrameTimingProvider,
        *,
        monotonic: Callable[[], float] = time.perf_counter,
    ) -> None:
        self.dataset = dataset
        self.recorder = recorder
        self.timing_provider = timing_provider
        self.monotonic = monotonic
        self._pending: PreparedTemporalFrame | None = None

    @property
    def features(self) -> Mapping[str, Mapping[str, Any]]:
        return self.dataset.features

    @property
    def fps(self) -> int:
        return self.dataset.fps

    def add_frame(self, frame: dict[str, Any]) -> None:
        if self._pending is None:
            raise RuntimeError(
                "dataset frame has no pre-actuation temporal validation; "
                "use the paired TimestampedTeleoperator"
            )
        self.recorder.commit_frame(frame, self._pending)
        self._pending = None

    def prepare_for_actuation(self) -> None:
        """Validate the current observation/action bundle before record_loop can send it."""

        if self._pending is not None:
            raise RuntimeError("previous temporal frame was not committed")
        timing = self.timing_provider.current_frame_timing()
        self._pending = self.recorder.prepare_frame(
            timing,
            selection_timestamp=self.monotonic(),
        )

    def save_episode(self, *args: Any, **kwargs: Any) -> Any:
        if self._pending is not None:
            raise RuntimeError("cannot save an episode with an uncommitted temporal frame")
        result = self.dataset.save_episode(*args, **kwargs)
        self._reset_episode_state()
        return result

    def clear_episode_buffer(self, *args: Any, **kwargs: Any) -> Any:
        result = self.dataset.clear_episode_buffer(*args, **kwargs)
        self._reset_episode_state()
        return result

    def _reset_episode_state(self) -> None:
        self._pending = None
        self.recorder.reset_episode()
        self.timing_provider.reset_episode()

    def __getattr__(self, name: str) -> Any:
        return getattr(self.dataset, name)


def _validate_recording_camera_rates(
    dataset: Any,
    robot: ObservationTimingSource,
    required_sources: tuple[str, ...],
) -> None:
    """Prevent a dense logical grid from overstating a slower physical camera cadence."""

    cameras = getattr(robot, "cameras", None)
    if not isinstance(cameras, Mapping):
        return
    dataset_fps = float(dataset.fps)
    for source in required_sources:
        prefix = "observation.images."
        if not source.startswith(prefix):
            continue
        name = source.removeprefix(prefix)
        camera = cameras.get(name)
        if camera is None:
            raise ValueError(f"required temporal camera {name!r} is not configured")
        camera_fps = getattr(camera, "fps", None)
        if (
            isinstance(camera_fps, bool)
            or not isinstance(camera_fps, (int, float))
            or camera_fps < dataset_fps
        ):
            raise ValueError(
                f"camera {name!r} fps={camera_fps!r} cannot supply a duplicate-free "
                f"dataset grid at {dataset_fps:g} fps"
            )


def wrap_lerobot_dataset_for_temporal_recording(
    dataset: Any,
    contract: Mapping[str, Any],
    *,
    robot: ObservationTimingSource,
    teleop: Teleoperator,
    source_class: str,
    timed_action_reader: TimedActionReader | None = None,
    monotonic: Callable[[], float] = time.perf_counter,
) -> tuple[TemporalLeRobotDatasetAdapter, TimestampedTeleoperator]:
    """Build the only project-owned layer needed by upstream ``record_loop``."""

    timed_teleop = TimestampedTeleoperator(
        teleop,
        timed_action_reader=timed_action_reader,
        require_xr=source_class == "human_vr",
        monotonic=monotonic,
    )
    recorder = TemporalFrameRecorder.from_resolved_contract(
        dataset,
        contract,
        source_class=source_class,
        accepted_clock_domains=("host_monotonic",),
    )
    _validate_recording_camera_rates(dataset, robot, recorder.required_sources)
    provider = LeRobotFrameTimingProvider(robot, timed_teleop, recorder.required_sources)
    adapter = TemporalLeRobotDatasetAdapter(
        dataset,
        recorder,
        provider,
        monotonic=monotonic,
    )
    timed_teleop.set_before_action_return(adapter.prepare_for_actuation)
    return adapter, timed_teleop

