    'default_ground_plane.usda': '8d86d2473acd68f6e4f3763c52347eee283b521303c56d29b8bd733c72811636',
    'Materials/Textures/default_ground_plane_albedo.png': '2c41b1f063769715b3d74738abd3efa4078eabb95f6ada8e5d2b3bba29411b14',
    'Materials/Textures/default_ground_plane_roughness.png': 'a55248660ef2d82b15b9cf731d42b2580c160314be5ae4c13e27c773c2debf8c',
}


def git(checkout: Path, *arguments: str) -> str:
    # Trust this explicit shared checkout only, never a global safe.directory '*'.
    return subprocess.check_output(
        ['git', '-c', f'safe.directory={checkout}', '-C', str(checkout), *arguments],
        text=True).strip()


def verify_stack(name: str) -> dict:
    stack = STACKS[name]
    if name == 'isaac61':
        for relative, expected in GROUND_HASHES.items():
            if hashlib.sha256((GROUND_ROOT / relative).read_bytes()).hexdigest() != expected:
                raise RuntimeError(f'Pinned NVIDIA ground asset changed: {relative}')
    for checkout, commit in (
        (stack['lab'], stack['commit']),
        (STORAGE / 'assets/agx_arm_urdf', 'f6642ce0d7872c686f29c99e9e10cd23d1d49313'),
    ):
        if git(checkout, 'rev-parse', 'HEAD') != commit or git(checkout, 'status', '--porcelain'):
            raise RuntimeError(f'Expected clean pinned checkout {commit}: {checkout}')
    for filename, key in (('pyproject.toml', 'pyproject'), ('uv.lock', 'lock')):
        if hashlib.sha256((stack['lab'] / filename).read_bytes()).hexdigest() != stack[key]:
            raise RuntimeError(f'Frozen upstream workspace mismatch: {filename}')
    probe = subprocess.check_output([
        str(stack['environment'] / 'bin/python'), '-c',
        'import importlib.metadata as m,json,sys; '
        'print(json.dumps({p:m.version(p) for p in sys.argv[1:]}))',
        *stack['packages'],
    ], text=True)
    if json.loads(probe) != stack['packages']:
        raise RuntimeError(f'Installed packages do not match {name}: {probe}')
    return stack


def private_directory(path: Path) -> Path:
    if path.is_symlink():
        raise RuntimeError(f'Per-user state cannot be a symlink: {path}')
    path.mkdir(parents=True, exist_ok=True, mode=0o700)
    if path.stat().st_uid != os.getuid():
        raise RuntimeError(f'Per-user state belongs to another UID: {path}')
    path.chmod(0o700)
    return path


def user_environment(stack: dict, name: str, *, state_root: Path | None = None) -> tuple[dict, Path]:
    home = Path(pwd.getpwuid(os.getuid()).pw_dir)
    if Path.home().resolve() != home.resolve():
        raise RuntimeError('HOME differs from the Linux account home; use a proper login shell')
    proposed = state_root or Path('/data') / pwd.getpwuid(os.getuid()).pw_name / 'vla-runtime' / f'isaac-{name}'
    if not proposed.is_absolute():
        raise RuntimeError('State root must be absolute')
    if proposed.resolve().is_relative_to(Path(__file__).resolve().parents[1]):
        raise RuntimeError('Runtime state must be outside the repository')
    state = private_directory(proposed)
    environment = os.environ.copy()
    for key in ('PYTHONHOME', 'VIRTUAL_ENV', 'EXP_PATH', 'ISAACSIM_PATH', 'XR_RUNTIME_JSON', 'NV_CXR_RUNTIME_DIR',
                'NV_CXR_OUTPUT_DIR', 'CXR_INSTALL_DIR', 'CXR_HOST_VOLUME_PATH',
                'ISAACLAB_CXR_SKIP_AUTOLAUNCH', 'ROBOSYN_VR_GROUND_USD', 'ROBOSYN_VR_CAMERA_DIAGNOSTICS_DIR'):
        environment.pop(key, None)
    environment.pop('UV_PYTHON_PREFERENCE', None)
    environment.update({
        'PYTHONPATH': str(stack['lab'] / 'source/isaaclab'),
        'PYTHONNOUSERSITE': '1', 'PYTHONDONTWRITEBYTECODE': '1',
        'ROBOSYN_VR_ASSET_CACHE': str(state / 'assets/demo'),
    })
    for key, relative in (
        ('XDG_CACHE_HOME', 'cache'), ('XDG_CONFIG_HOME', 'config'),
        ('XDG_DATA_HOME', 'data'), ('CUDA_CACHE_PATH', 'cuda'),
        ('WARP_CACHE_PATH', 'warp'), ('TMPDIR', 'tmp'), ('XDG_RUNTIME_DIR', 'run'),
    ):
        environment[key] = str(private_directory(state / relative))
    if name == 'isaac61':
        environment['ROBOSYN_VR_GROUND_USD'] = str(GROUND_ROOT / 'default_ground_plane.usda')
    private_directory(state / 'kit')
    return environment, state


def configure_cloudxr(environment: dict, *, mode: str, dry_run: bool) -> None:
    if mode == 'existing':
        root = Path(environment['VLA_CLOUDXR_INSTALL_DIR'])
        runtime = root / 'run'
        if not runtime.is_dir() or runtime.stat().st_uid != os.getuid():
            raise RuntimeError(f'Existing CloudXR IPC must belong to UID {os.getuid()}: {runtime}')
        manifest = root / 'openxr_cloudxr.json'
        if not manifest.is_file() or not os.access(manifest, os.R_OK):
            raise RuntimeError(f'Missing current-user OpenXR manifest: {manifest}')
        environment.update({'ISAACLAB_CXR_SKIP_AUTOLAUNCH': '1',
                            'XR_RUNTIME_JSON': str(manifest), 'NV_CXR_RUNTIME_DIR': str(runtime)})
    elif not dry_run:
        if environment.get('ISAACLAB_CXR_ACCEPT_EULA', '').upper() not in ('1', 'Y', 'YES', 'TRUE'):
            raise RuntimeError('Accept CloudXR EULA with ISAACLAB_CXR_ACCEPT_EULA=1')
        # This deployment uses the upstream default WSS port. Never take over another user's server.
        with socket.socket() as probe:
            try:
                probe.bind(('0.0.0.0', 48322))
            except OSError as error:
                raise RuntimeError('CloudXR port 48322 is occupied. Its owner must stop it, '
                                   'or use --cloudxr-mode existing for YOUR own runtime.') from error


def write_runtime_config(root: Path, stack: dict, state: Path, output: Path) -> Path:
    config = yaml.safe_load((root / 'configs' / stack['s1']).read_text())
    assets = private_directory(state / 'assets')
    config['asset']['composed_urdf'] = str(assets / 'piper_x_gate_c.urdf')
    config['asset']['converted_usd_dir'] = str(assets / 'converted/<composed_urdf_sha256>')
    path = output / 'runtime.yaml'
    path.write_text(yaml.safe_dump(config, sort_keys=False))
    return path

#!/usr/bin/env python3
"""Concrete Gate S1 asset materialization and D0/Isaac edge processors.

This module deliberately has no Isaac or LeRobot imports.  The executable runner imports
Isaac Lab only after Kit starts; core tests can exercise the semantic boundary offline.
"""

from __future__ import annotations

import hashlib
import math
import random
import xml.etree.ElementTree as ET
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Sequence

import numpy as np


D0_PROCESSOR_REVISION = "piper_x_d0_isaac_edge_mapping_v1"

ISAAC_ARM_JOINT_NAMES = ("joint1", "joint2", "joint3", "joint4", "joint5", "joint6", "gripper")
JOINT_LIMITS_DEG = np.asarray(
    [[-150.0, 150.0], [0.0, 180.0], [-170.0, 0.0], [-89.0, 89.0], [-89.0, 89.0], [-120.0, 120.0]],
    dtype=np.float64,
)
GRIPPER_LIMITS_MM = np.asarray([0.0, 100.0], dtype=np.float64)


class S1ConfigurationError(RuntimeError):
    """Raised when a checked S1 invariant is not satisfied."""


@dataclass(frozen=True)
class NativeBimanualTargets:
    """Separate native command derived from, but never substituted for, a D0 label."""

    left_rad_m: np.ndarray
    right_rad_m: np.ndarray
    saturated: bool


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def seed_reset(seed: int) -> None:
    """Apply the S1 deterministic reset seed to all non-Isaac RNGs."""

    random.seed(seed)
    np.random.seed(seed)
    try:
        import torch

        torch.manual_seed(seed)
        if torch.cuda.is_available():
            torch.cuda.manual_seed_all(seed)
    except ImportError:
        pass


def materialize_gate_c_urdf(source_checkout: Path, output_path: Path) -> str:
    """Resolve the single accepted Xacro include while preserving meshes and frames."""

    base_path = source_checkout / "piper_x/urdf/piper_x_description.urdf"
    gripper_path = source_checkout / "piper_x/urdf/piper_x_with_gripper_description.xacro"
    expected = {
        base_path: "34126caac7d5b37bc2409f337ac246afbe0bb8cd47fc9f16df5038f19bd21e3a",
        gripper_path: "0ee3f52f9acf3060a7f3e439c6e5e46b6a53d4fa509dd495045548be6b7f90cd",
    }
    for path, digest in expected.items():
        if not path.is_file():
            raise S1ConfigurationError(f"missing accepted Gate C source: {path}")
        if sha256_file(path) != digest:
            raise S1ConfigurationError(f"Gate C source SHA-256 mismatch: {path}")

    base = ET.parse(base_path).getroot()
    gripper = ET.parse(gripper_path).getroot()
    includes = [element for element in gripper if element.tag.endswith("include")]
    if len(includes) != 1:
        raise S1ConfigurationError("accepted gripper Xacro no longer has exactly one include")
    if not includes[0].get("filename", "").endswith("piper_x/urdf/piper_x_description.urdf"):
        raise S1ConfigurationError("accepted gripper Xacro include changed")
    for element in list(gripper):
        if not element.tag.endswith("include"):
            base.append(element)

    # The accepted aperture coordinate uses a geometry-free child link. PhysX requires
    # positive mass properties for that dynamic link, so provide a tiny inertial carrier;
    # this does not alter any joint, frame, limit, visual, collision, or FK semantics.
    aperture_link = base.find("link[@name='gripper_link']")
    if aperture_link is None or list(aperture_link):
        raise S1ConfigurationError("accepted geometry-free gripper_link changed")
    inertial = ET.SubElement(aperture_link, "inertial")
    ET.SubElement(inertial, "origin", {"xyz": "0 0 0", "rpy": "0 0 0"})
    ET.SubElement(inertial, "mass", {"value": "0.001"})
    ET.SubElement(
        inertial,
        "inertia",
        {
            "ixx": "1e-7",
            "ixy": "0",
            "ixz": "0",
            "iyy": "1e-7",
            "iyz": "0",
            "izz": "1e-7",
        },
    )

    output_path.parent.mkdir(parents=True, exist_ok=True)
    ET.indent(base, space="  ")
    ET.ElementTree(base).write(output_path, encoding="utf-8", xml_declaration=True)
    return sha256_file(output_path)


def _checked_vector(
    values: Sequence[float] | np.ndarray, *, length: int, name: str
) -> np.ndarray:
    vector = np.asarray(values, dtype=np.float64)
    if vector.shape != (length,):
        raise ValueError(f"{name} must have shape ({length},), got {vector.shape}")
    if not np.all(np.isfinite(vector)):
        raise ValueError(f"{name} contains a non-finite value")
    return vector.copy()


def d0_action_to_native(action: Sequence[float] | np.ndarray) -> NativeBimanualTargets:
    """Convert D0 degrees/signed-mm into clipped Isaac radians/model-aperture targets.

    The caller's label is copied before conversion.  Clipping affects only the returned native
    command, never the source label that belongs in ``dataset.action``.
    """

    d0 = _checked_vector(action, length=14, name="D0 action")
    native_arms: list[np.ndarray] = []
    saturated = False
    for offset in (0, 7):
        source_joints = d0[offset : offset + 6]
        source_gripper = d0[offset + 6]
        clipped_joints = np.clip(source_joints, JOINT_LIMITS_DEG[:, 0], JOINT_LIMITS_DEG[:, 1])
        clipped_gripper = float(np.clip(source_gripper, *GRIPPER_LIMITS_MM))
        saturated |= not np.array_equal(source_joints, clipped_joints)
        saturated |= source_gripper != clipped_gripper
        native_arms.append(np.concatenate((np.deg2rad(clipped_joints), [clipped_gripper / 1000.0])))
    return NativeBimanualTargets(native_arms[0], native_arms[1], saturated)


def native_state_to_d0(left_rad_m, right_rad_m) -> np.ndarray:
    """Canonical measured joint degrees and absolute gripper millimetres."""
    native_arms = [
        _checked_vector(left_rad_m, length=7, name="left native observation"),
        _checked_vector(right_rad_m, length=7, name="right native observation"),
    ]
    d0_arms = []
    for arm in native_arms:
        d0_arms.append(np.concatenate((np.rad2deg(arm[:6]), [abs(arm[6]) * 1000.0])))

    return np.concatenate(d0_arms).astype(np.float32)


def native_observation_to_d0(
    left_rad_m: Sequence[float] | np.ndarray,
    right_rad_m: Sequence[float] | np.ndarray,
    left_image: np.ndarray,
    right_image: np.ndarray,
) -> dict[str, np.ndarray]:
    """Map the plain S1 state/wrist subset; this is not a complete D0 v4 source view."""

    def rgb(value: np.ndarray, role: str) -> np.ndarray:
        array = np.asarray(value)
        if array.shape not in {(480, 640, 3), (480, 640, 4), (600, 960, 3), (600, 960, 4)}:
            raise ValueError(f"{role} image must be legacy 480x640 or native ZED 600x960 RGB/RGBA HWC, got {array.shape}")
        if array.dtype != np.uint8:
            raise ValueError(f"{role} image must be uint8, got {array.dtype}")
        return np.ascontiguousarray(array[..., :3])

    return {
        "observation.state": native_state_to_d0(left_rad_m, right_rad_m),
        "observation.images.left_wrist": rgb(left_image, "left_wrist"),
        "observation.images.right_wrist": rgb(right_image, "right_wrist"),
    }


def quaternion_xyzw_to_matrix(quaternion: Sequence[float] | np.ndarray) -> np.ndarray:
    """Convert Isaac Lab's documented xyzw quaternion to a 3x3 matrix."""

    x, y, z, w = _checked_vector(quaternion, length=4, name="quaternion")
    norm = math.sqrt(x * x + y * y + z * z + w * w)
    if norm == 0.0:
        raise ValueError("zero quaternion")
    x, y, z, w = x / norm, y / norm, z / norm, w / norm
    return np.asarray(
        [
            [1 - 2 * (y * y + z * z), 2 * (x * y - z * w), 2 * (x * z + y * w)],
            [2 * (x * y + z * w), 1 - 2 * (x * x + z * z), 2 * (y * z - x * w)],
            [2 * (x * z - y * w), 2 * (y * z + x * w), 1 - 2 * (x * x + y * y)],
        ],
        dtype=np.float64,
    )


def pose_xyzw_to_matrix(pose: Sequence[float] | np.ndarray) -> np.ndarray:
    checked = _checked_vector(pose, length=7, name="pose")
    transform = np.eye(4, dtype=np.float64)
    transform[:3, :3] = quaternion_xyzw_to_matrix(checked[3:])
    transform[:3, 3] = checked[:3]
    return transform


def relative_pose_matrix(
    base_pose: Sequence[float] | np.ndarray, tcp_pose: Sequence[float] | np.ndarray
) -> np.ndarray:
    return np.linalg.inv(pose_xyzw_to_matrix(base_pose)) @ pose_xyzw_to_matrix(tcp_pose)


def transform_error(actual: np.ndarray, expected: Sequence[Sequence[float]]) -> tuple[float, float]:
    expected_array = np.asarray(expected, dtype=np.float64)
    position = float(np.linalg.norm(actual[:3, 3] - expected_array[:3, 3]))
    relative_rotation = actual[:3, :3] @ expected_array[:3, :3].T
    cosine = float(np.clip((np.trace(relative_rotation) - 1.0) / 2.0, -1.0, 1.0))
    return position, math.acos(cosine)


def jsonable(value: Any) -> Any:
    """Convert runtime arrays/scalars into stable JSON values."""

    if isinstance(value, np.ndarray):
        return value.tolist()
    if isinstance(value, np.generic):
        return value.item()
    if isinstance(value, dict):
        return {key: jsonable(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [jsonable(item) for item in value]
    return value

"""Required feed health using source sequence and buffer metadata, never image copies."""

from __future__ import annotations

import numpy as np


class CameraGuard:
    """Camera.frame is acquisition-owned; static image content is allowed.

    Only the small frame counters cross to CPU. Checking each sensor separately
    avoids concatenating the full wrist images just to inspect their metadata.
    A reset starts a new sequence epoch; regression outside reset fails closed.
    """

    def __init__(self, max_stale_steps: int = 2) -> None:
        if max_stale_steps < 0:
            raise ValueError("camera stale tolerance must be nonnegative")
        self.max_stale_steps = max_stale_steps
        self.previous: dict[str, int] = {}
        self.stale: dict[str, int] = {}

    def reset(self) -> None:
        self.previous.clear()
        self.stale.clear()

    def sample(self, env) -> dict:
        rig = env.camera
        if hasattr(rig, "wrists"):
            sources = [
                ("left_wrist", rig.wrists[0]),
                ("right_wrist", rig.wrists[1]),
                ("demo_scene", rig.scene_camera),
            ]
        else:
            sources = [("wrists", rig)]
        roles = {}
        for role, camera in sources:
            output = camera.data.output
            pixels = output.get("rgba", output.get("rgb"))
            if hasattr(pixels, "torch"):
                pixels = pixels.torch
            channels = 4 if "rgba" in output else 3
            batch = 2 if role == "wrists" else 1
            cfg = getattr(camera, "cfg", None)
            height, width = (cfg.height, cfg.width) if cfg else (480, 640)
            if (height, width) not in ((480, 640), (600, 960)):
                raise RuntimeError("Unsupported source camera resolution")
            if (
                pixels is None
                or tuple(pixels.shape) != (batch, height, width, channels)
                or str(pixels.dtype) not in ("torch.uint8", "uint8")
            ):
                raise RuntimeError(f"Broken required camera buffer: {role}")
            frames = camera.frame
            if hasattr(frames, "torch"):
                frames = frames.torch
            indices = frames.detach().cpu().numpy().reshape(-1)
            if len(indices) != batch or not np.isfinite(indices).all():
                raise RuntimeError(f"Broken camera sequence: {role}")
            for index, frame in enumerate(indices):
                key = f"{role}:{index}"
                frame = int(frame)
                previous = self.previous.get(key)
                if frame < 0 or (previous is not None and frame < previous):
                    raise RuntimeError(f"Camera sequence regressed without reset: {key}")
                advanced = previous is None or frame > previous
                self.stale[key] = 0 if advanced else self.stale.get(key, 0) + 1
                if self.stale[key] > self.max_stale_steps:
                    raise RuntimeError(f"Frozen required camera: {key}")
                self.previous[key] = frame
                roles[key] = {"frame_index": frame, "advanced": advanced}
        return {
            "valid": True,
            "strictly_advanced": all(v["advanced"] for v in roles.values()),
            "roles": roles,
        }

"""Display-only recording HUD using pinned Kit SceneUI; no camera or input owner."""

from __future__ import annotations

from dataclasses import dataclass
import math
import time
from types import SimpleNamespace

from tools.isaac_vr_episode_lifecycle import RecordingState


REVIEW_CHOICES = (("X", "Save"), ("B", "Discard"))
OUTCOME_CHOICES = (("X", "Success"), ("Y", "Failure"), ("B", "Incomplete"))
OUTCOME_BUTTONS = {"success": "X", "failure": "Y", "incomplete": "B"}


@dataclass(frozen=True)
class RecordingUiView:
    status: str
    title: str = ""
    detail: str = ""
    choices: tuple[tuple[str, str], ...] = ()
    selected: str | None = None
    pressed: tuple[str, ...] = ()


class RecordingUiModel:
    """Observe accepted lifecycle events; retain confirmation across scene reset."""

    def __init__(self, feedback_seconds: float, *, clock=time.monotonic):
        if not math.isfinite(feedback_seconds) or feedback_seconds <= 0:
            raise ValueError("recording UI feedback_seconds must be finite and positive")
        self.feedback_seconds, self.clock = feedback_seconds, clock
        self._confirmation: RecordingUiView | None = None
        self._confirmation_until = 0.0

    def update(
        self,
        state: RecordingState | str,
        *,
        event: str | None = None,
        pressed: tuple[str, ...] = (),
        gap: bool = False,
        error: str | None = None,
    ) -> RecordingUiView:
        # Isaac's filename imports and core's tools.* imports must agree by
        # serialized state value, even when Python loads two enum classes.
        state = RecordingState(state)
        now = self.clock()
        if state is not RecordingState.WAITING or event == "reset":
            self._confirmation = None
        if state is RecordingState.WAITING:
            if event == "discard" or event in OUTCOME_BUTTONS:
                assert event is not None
                discarded = event == "discard"
                self._confirmation = RecordingUiView(
                    "[ready]  X - Start",
                    "Demonstration discarded" if discarded else "Demonstration saved",
                    "Selected: Discard" if discarded else f"Selected: {event.title()}",
                    REVIEW_CHOICES if discarded else OUTCOME_CHOICES,
                    "B" if discarded else OUTCOME_BUTTONS[event],
                )
                self._confirmation_until = now + self.feedback_seconds
            if self._confirmation is not None and now < self._confirmation_until:
                return self._confirmation
            self._confirmation = None
            return RecordingUiView("[ready]  X - Start")
        if state is RecordingState.RECORDING:
            suffix = "  |  Input gap: no sample" if gap else ""
            return RecordingUiView(f"[recording]  Y - Stop{suffix}")
        if state is RecordingState.REVIEW:
            return RecordingUiView(
                "[stopped]",
                "Recording stopped",
                "Keep or discard this demonstration?",
                REVIEW_CHOICES,
                pressed=pressed,
            )
        if state is RecordingState.CLASSIFY_OUTCOME:
            return RecordingUiView(
                "[stopped]",
                "Task outcome",
                "Selected: [X] Save - choose the task result",
                OUTCOME_CHOICES,
                pressed=pressed,
            )
        if state is RecordingState.FAILED:
            return RecordingUiView("[error]", "Recording failed", error or "See the host log")
        if state is RecordingState.INTERRUPTED:
            return RecordingUiView(
                "[interrupted]", "Recording interrupted", "Demonstration was not saved"
            )
        return RecordingUiView("[busy]", "Finishing recording")


class RecordingUi:
    """Two retained head-locked panels, excluded from dataset sensor rendering."""

    def __init__(self, config, *, isolation=None):
        import omni.ui as ui  # type: ignore[import-not-found]
        from omni.kit.scene_view.xr import XRSceneView  # type: ignore[import-not-found]
        from omni.kit.scene_view.xr_utils import (  # type: ignore[import-not-found]
            SpatialSource,
            UiContainer,
            UpdatePolicy,
            WidgetComponent,
        )
        from omni.kit.xr.core import XRCore  # type: ignore[import-not-found]
        from pxr import Gf  # type: ignore[import-not-found]

        self.model = RecordingUiModel(float(config["feedback_seconds"]))
        self.view = self.model.update(RecordingState.WAITING)
        self.isolation = isolation
        self.panels = {}
        self._visible = {"status": False, "review": False}
        if config["placement"] != "head_locked":
            raise ValueError("recording UI requires head_locked placement")
        meters_per_unit = float(XRCore.get_singleton().get_coordinate_system().meters_per_unit)
        if not math.isfinite(meters_per_unit) or meters_per_unit <= 0:
            raise RuntimeError("Invalid XR coordinate-system scale for recording UI")
        distance = float(config["distance_m"])
        if not math.isfinite(distance) or distance <= 0:
            raise ValueError("recording UI distance_m must be finite and positive")

        def make_panel(role):
            layout = config["layout"][role]

            class PanelWidget(ui.Widget):
                def __init__(widget_self, **kwargs):
                    super().__init__(**kwargs)
                    self._draw(role, ui)

            component = WidgetComponent(
                PanelWidget,
                width=float(layout["width_m"]) / meters_per_unit,
                height=float(layout["height_m"]) / meters_per_unit,
                # Text needs pixel-sized layout coordinates, unlike an image
                # provider that can fill a sub-pixel UI layout. Resolution scale
                # supersamples that layout; it does not enlarge its usable area.
                resolution_scale=1.0,
                unit_to_pixel_scale=float(config["pixels_per_m"]) * meters_per_unit,
                update_policy=UpdatePolicy.ON_DEMAND,
            )
            container = UiContainer(
                XRSceneView,
                component,
                space_stack=[
                    SpatialSource.new_prim_path_source("/_xr/stage/xrCamera"),
                    SpatialSource.new_translation_source(
                        Gf.Vec3f(
                            0.0,
                            float(layout["offset_y_m"]) / meters_per_unit,
                            -distance / meters_per_unit,
                        )
                    ),
                    SpatialSource.new_look_at_camera_source(),
                ],
            )
            container.hide()
            return SimpleNamespace(_container=container, component=component)

        try:
            for role in ("status", "review"):
                self.panels[role] = make_panel(role)
            self._present()
        except Exception:
            self.close()
            raise

    def _draw(self, role, ui):
        view = self.view
        with ui.ZStack():
            ui.Rectangle(style={"background_color": 0xF0201814, "border_radius": 8})
            with ui.VStack(spacing=10):
                if role == "status":
                    ui.Label(
                        view.status,
                        alignment=ui.Alignment.CENTER,
                        style={"font_size": 22, "color": 0xFFEEEEEE},
                    )
                    return
                ui.Label(
                    view.title, height=40, alignment=ui.Alignment.CENTER, style={"font_size": 28}
                )
                ui.Label(
                    view.detail,
                    height=40,
                    alignment=ui.Alignment.CENTER,
                    style={"font_size": 20, "color": 0xFFB8EFB8},
                )
                for button, label in view.choices:
                    selected = button == view.selected
                    ui.Label(
                        f"{'SELECTED  ' if selected else ''}[{button}]  {label}",
                        height=34,
                        alignment=ui.Alignment.CENTER,
                        style={"font_size": 24, "color": 0xFF70ED70 if selected else 0xFFEEEEEE},
                    )
                hint = "X/Y: left controller   B: right controller"
                if view.pressed:
                    hint = f"Pressed: {' / '.join(view.pressed)} - release before the next choice"
                ui.Label(
                    hint,
                    height=32,
                    alignment=ui.Alignment.CENTER,
                    style={"font_size": 17, "color": 0xFFB8B8B8},
                )

    def update(self, state: RecordingState | str, **kwargs) -> None:
        view = self.model.update(state, **kwargs)
        if view == self.view:
            return
        self.view = view
        self._present()

    def _present(self) -> None:
        for role, panel in self.panels.items():
            visible = role == "status" or bool(self.view.title)
            container = panel._container
            if visible != self._visible[role]:
                if visible:
                    container.show()
                else:
                    if self.isolation is not None:
                        self.isolation.release_panel(panel)
                    container.hide()
                self._visible[role] = visible
            if visible:
                container.scene_view.run_update()
                if panel.component.scene_widget is not None:
                    panel.component.scene_widget.invalidate()
                # Invalidation may replace the draw system. Reapply its sensor
                # exclusion before the existing simulation loop renders again.
                if self.isolation is not None:
                    self.isolation.check_panel(panel)

    def close(self) -> None:
        for role, panel in self.panels.items():
            if self.isolation is not None:
                self.isolation.release_panel(panel)
            panel._container.hide()
            self._visible[role] = False

"""Print the existing S2 logger's final aggregate, excluding its warmup controls."""

from __future__ import annotations

import argparse
import json
import math
from pathlib import Path
from typing import Any


def summarize(path: Path) -> str:
    records = [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines()]
    if not records or any(not isinstance(row, dict) for row in records):
        raise ValueError("Expected performance JSONL objects")
    if records[0].get("event") != "performance_log_started":
        raise ValueError("Missing performance header")
    if records[-1].get("event") != "performance_summary":
        raise ValueError("Incomplete log: missing final performance summary")
    if any(row.get("schema") != "piper_x_isaac_s2_performance_v1" for row in records):
        raise ValueError("Unsupported performance schema")
    if any(row.get("event") == "performance_summary" for row in records[1:-1]):
        raise ValueError("Unexpected data after final summary")
    summary = records[-1]
    measured = [
        row for row in records if row.get("event") == "performance_step" and row["post_warmup"]
    ]
    control = summary["control"]
    if not measured or control["samples"] != len(measured):
        raise ValueError("Incomplete log or no measured samples")

    def number(value: Any) -> str:
        if isinstance(value, bool) or not isinstance(value, (float, int)):
            raise ValueError("Expected numeric performance measurement")
        if not math.isfinite(value) or value < 0:
            raise ValueError("Invalid performance measurement")
        return f"{value:.6f}"

    lines = [f"performance: {path}", f"samples: {len(measured)}"]
    lines.append(f"effective_hz: {number(summary['effective_hz'])}")
    wall = summary.get("wall_control")
    if wall is not None:
        lines.append(f"wall_effective_hz: {number(summary['effective_wall_hz'])}")
        lines.append(f"wall_rtf: {number(summary['wall_rtf'])}")
        lines.append(
            f"wall_deadline_miss_fraction: {number(summary['wall_deadline_miss_fraction'])}"
        )
        for field in ("mean_ms", "p50_ms", "p90_ms", "p95_ms", "p99_ms", "p99_9_ms", "max_ms"):
            lines.append(f"wall_{field}: {number(wall[field])}")
    for field in ("mean_ms", "p50_ms", "p90_ms", "p95_ms", "p99_ms", "max_ms"):
        lines.append(f"{field}: {number(control[field])}")
    lines.append(f"deadline_miss_fraction: {number(summary['deadline_miss_fraction'])}")
    for label, stages in (
        ("stages (mean_ms / p95_ms)", summary["stages"]),
        ("nested stages NON-ADDITIVE (mean_ms / p95_ms)", summary["nested_stages_not_additive"]),
    ):
        lines.append(label + ":")
        for name, values in sorted(stages.items()):
            lines.append(f"  {name}: {number(values['mean_ms'])} / {number(values['p95_ms'])}")
    for name in ("unattributed", "instrumentation_write"):
        values = summary.get(name)
        lines.append(
            f"{name} mean_ms / p95_ms: {number(values['mean_ms'])} / {number(values['p95_ms'])}"
            if values
            else f"{name}: not_measured"
        )
    lines.append(
        "Body timings exclude log writes and inter-control work. Wall timings are "
        "start-to-start and exclude the interval crossing warmup. Nested stages "
        "are non-additive. Unlisted measurements are not_measured."
    )
    return "\n".join(lines)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("path", type=Path, help="Completed performance.jsonl")
    args = parser.parse_args(argv)
    try:
        print(summarize(args.path))
    except (OSError, ValueError, KeyError, TypeError) as exc:
        parser.error(str(exc))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Physical D0 timing validation and the existing LeRobot compatibility facade."""

from __future__ import annotations

from collections import Counter
from dataclasses import dataclass
from types import MappingProxyType
import math
import hashlib
import json
from typing import TYPE_CHECKING, Any, Mapping, Protocol

import numpy as np


if TYPE_CHECKING:
    from tools.d0_causal import CausalTransactionValidator, PreparedTransaction


CROSS_MODAL_SKEW_KEY = "temporal.cross_modal_skew_ms"


class DatasetWriter(Protocol):
    """The narrow upstream LeRobotDataset surface used by this adapter."""

    @property
    def features(self) -> Mapping[str, Mapping[str, Any]]: ...

    def add_frame(self, frame: dict[str, Any]) -> None: ...


class TemporalContractViolation(ValueError):
    """A frame was rejected before it reached ``LeRobotDataset.add_frame``."""

    def __init__(self, reason: str, detail: str) -> None:
        super().__init__(f"{reason}: {detail}")
        self.reason = reason
        self.detail = detail


@dataclass(frozen=True)
class SourceTiming:
    """Physical acquisition identity for one source sample."""

    sequence: int
    source_timestamp: float
    clock_domain: str

    def __post_init__(self) -> None:
        if (
            isinstance(self.sequence, bool)
            or not isinstance(self.sequence, int)
            or self.sequence < 0
        ):
            raise ValueError("sequence must be a non-negative integer")
        if (
            isinstance(self.source_timestamp, bool)
            or not isinstance(self.source_timestamp, (int, float))
            or not math.isfinite(self.source_timestamp)
        ):
            raise ValueError("source_timestamp must be finite")
        if not self.clock_domain:
            raise ValueError("clock_domain must be non-empty")


@dataclass(frozen=True)
class PreparedTemporalFrame:
    """Validated temporal enrichment awaiting the matching dataset frame."""

    enrichment: Mapping[str, Any]
    accepted: Mapping[str, SourceTiming]
    previous: Mapping[str, SourceTiming]
    generation: int


@dataclass(frozen=True)
class TemporalLimits:
    """Per-source age limits and the bundle-wide skew limit, in milliseconds."""

    max_age_ms: Mapping[str, float]
    max_cross_modal_skew_ms: float

    def __post_init__(self) -> None:
        if not math.isfinite(self.max_cross_modal_skew_ms) or self.max_cross_modal_skew_ms < 0:
            raise ValueError("max_cross_modal_skew_ms must be finite and non-negative")
        for source, value in self.max_age_ms.items():
            if not source or not math.isfinite(value) or value < 0:
                raise ValueError(f"invalid max age for {source!r}: {value!r}")

    @classmethod
    def from_resolved_contract(
        cls,
        contract: Mapping[str, Any],
        required_sources: tuple[str, ...],
    ) -> "TemporalLimits":
        """Resolve non-null modality budgets from the canonical contract."""

        timing = contract["timing"]
        source_limit_keys = {
            "observation.state": "max_joint_age_ms",
            "observation.images.left_wrist": "max_camera_age_ms",
            "observation.images.right_wrist": "max_camera_age_ms",
            "observation.images.scene": "max_camera_age_ms",
            "xr.left_pose": "max_xr_age_ms",
            "xr.right_pose": "max_xr_age_ms",
            "source_action": "max_policy_action_age_ms",
        }
        max_age_ms: dict[str, float] = {}
        for source in required_sources:
            key = source_limit_keys.get(source)
            if key is None:
                raise ValueError(f"no temporal limit mapping for required source {source!r}")
            value = timing.get(key)
            if value is None:
                raise ValueError(f"timing.{key} must be resolved before recording starts")
            max_age_ms[source] = float(value)
        skew = timing.get("max_cross_modal_skew_ms")
        if skew is None:
            raise ValueError(
                "timing.max_cross_modal_skew_ms must be resolved before recording starts"
            )
        return cls(max_age_ms=max_age_ms, max_cross_modal_skew_ms=float(skew))


def temporal_feature_specs(
    feature_sets: Mapping[str, Mapping[str, str]],
    required_sources: tuple[str, ...],
    *,
    cross_modal_skew_key: str = CROSS_MODAL_SKEW_KEY,
) -> dict[str, dict[str, Any]]:
    """Build LeRobot v3 feature declarations for persisted source timing."""

    specs: dict[str, dict[str, Any]] = {}
    for source in required_sources:
        keys = feature_sets[source]
        specs[keys["sequence"]] = {"dtype": "int64", "shape": (1,)}
        specs[keys["source_timestamp"]] = {"dtype": "float64", "shape": (1,)}
        specs[keys["clock_domain"]] = {"dtype": "string", "shape": (1,)}
        specs[keys["age_ms"]] = {"dtype": "float64", "shape": (1,)}
    specs[cross_modal_skew_key] = {"dtype": "float64", "shape": (1,)}
    return specs


class PhysicalTimingValidator:
    """Validate physical source timing independently of any dataset writer."""

    def __init__(
        self,
        *,
        feature_sets: Mapping[str, Mapping[str, str]],
        required_sources: tuple[str, ...],
        limits: TemporalLimits,
        accepted_clock_domains: tuple[str, ...],
        cross_modal_skew_key: str = CROSS_MODAL_SKEW_KEY,
    ) -> None:
        if not required_sources:
            raise ValueError("required_sources must not be empty")
        if set(required_sources) != set(limits.max_age_ms):
            raise ValueError("max_age_ms keys must exactly match required_sources")
        missing_sets = set(required_sources) - set(feature_sets)
        if missing_sets:
            raise ValueError(f"missing temporal feature sets: {sorted(missing_sets)}")
        if not accepted_clock_domains or any(not domain for domain in accepted_clock_domains):
            raise ValueError("accepted_clock_domains must contain non-empty names")

        self.feature_sets = {name: dict(feature_sets[name]) for name in required_sources}
        self.required_sources = required_sources
        self.limits = limits
        self.accepted_clock_domains = frozenset(accepted_clock_domains)
        self.cross_modal_skew_key = cross_modal_skew_key
        self._last_accepted: dict[str, SourceTiming] = {}
        self.accepted_frames = 0
        self._generation = 0
        self.rejected_frames: Counter[str] = Counter()

    def prepare_frame(
        self,
        source_timing: Mapping[str, SourceTiming],
        *,
        selection_timestamp: float,
    ) -> PreparedTemporalFrame:
        """Validate source timing before actuation and retain its exact enrichment."""

        try:
            enrichment, accepted = self._validated_frame(
                {}, source_timing, selection_timestamp=selection_timestamp
            )
        except TemporalContractViolation as exc:
            self.rejected_frames[exc.reason] += 1
            raise
        for value in enrichment.values():
            if isinstance(value, np.ndarray):
                value.setflags(write=False)
        return PreparedTemporalFrame(
            enrichment=MappingProxyType(enrichment),
            accepted=MappingProxyType(accepted),
            previous=MappingProxyType(dict(self._last_accepted)),
            generation=self._generation,
        )

    def accept(self, prepared: PreparedTemporalFrame) -> None:
        if prepared.generation != self._generation or dict(self._last_accepted) != dict(
            prepared.previous
        ):
            self._reject("prepared_frame_order", "physical history changed after preparation")
        self._last_accepted = dict(prepared.accepted)
        self.accepted_frames += 1
        self._generation += 1

    def reset_episode(self) -> None:
        """Reset episode-local sequence/time history without erasing QA counters."""

        self._last_accepted.clear()
        self._generation += 1

    def qa_summary(self) -> dict[str, Any]:
        return {
            "accepted_frames": self.accepted_frames,
            "rejected_frames": sum(self.rejected_frames.values()),
            "rejected_by_reason": dict(sorted(self.rejected_frames.items())),
        }

    def _reject(self, reason: str, detail: str) -> None:
        raise TemporalContractViolation(reason, detail)

    def _validated_frame(
        self,
        frame: Mapping[str, Any],
        source_timing: Mapping[str, SourceTiming],
        *,
        selection_timestamp: float,
    ) -> tuple[dict[str, Any], dict[str, SourceTiming]]:
        if not math.isfinite(selection_timestamp):
            self._reject("invalid_selection_timestamp", "selection timestamp must be finite")
        forbidden = {"timestamp", "frame_index"} & set(frame)
        if forbidden:
            self._reject("logical_time_override", f"LeRobot owns {sorted(forbidden)}")
        missing = set(self.required_sources) - set(source_timing)
        extra = set(source_timing) - set(self.required_sources)
        if missing or extra:
            self._reject(
                "missing_timing_metadata" if missing else "source_set_mismatch",
                f"missing={sorted(missing)} extra={sorted(extra)}",
            )

        for source in self.required_sources:
            sample = source_timing[source]
            if not isinstance(sample, SourceTiming):
                self._reject(
                    "missing_timing_metadata",
                    f"{source} must provide a complete SourceTiming value",
                )

        domains = {sample.clock_domain for sample in source_timing.values()}
        if len(domains) != 1:
            self._reject("clock_domain_mismatch", f"domains={sorted(domains)}")
        if not domains <= self.accepted_clock_domains:
            self._reject(
                "undeclared_clock_domain",
                f"domains={sorted(domains)} accepted={sorted(self.accepted_clock_domains)}",
            )

        ages: dict[str, float] = {}
        for source in self.required_sources:
            sample = source_timing[source]
            age_ms = (selection_timestamp - sample.source_timestamp) * 1000.0
            if age_ms < 0:
                self._reject("future_source_sample", f"{source} age_ms={age_ms}")
            if age_ms > self.limits.max_age_ms[source]:
                self._reject(
                    "stale_source_sample",
                    f"{source} age_ms={age_ms} limit={self.limits.max_age_ms[source]}",
                )
            previous = self._last_accepted.get(source)
            if previous is not None:
                if sample.sequence <= previous.sequence:
                    self._reject(
                        "repeated_sequence"
                        if sample.sequence == previous.sequence
                        else "sequence_regression",
                        f"{source} sequence={sample.sequence} previous={previous.sequence}",
                    )
                if sample.source_timestamp <= previous.source_timestamp:
                    self._reject(
                        "source_time_regression",
                        f"{source} timestamp={sample.source_timestamp} previous={previous.source_timestamp}",
                    )
            ages[source] = age_ms

        timestamps = [source_timing[source].source_timestamp for source in self.required_sources]
        skew_ms = (max(timestamps) - min(timestamps)) * 1000.0
        if skew_ms > self.limits.max_cross_modal_skew_ms:
            self._reject(
                "cross_modal_skew",
                f"skew_ms={skew_ms} limit={self.limits.max_cross_modal_skew_ms}",
            )

        enriched = dict(frame)
        for source in self.required_sources:
            sample = source_timing[source]
            keys = self.feature_sets[source]
            enriched[keys["sequence"]] = np.asarray([sample.sequence], dtype=np.int64)
            enriched[keys["source_timestamp"]] = np.asarray(
                [sample.source_timestamp], dtype=np.float64
            )
            enriched[keys["clock_domain"]] = sample.clock_domain
            enriched[keys["age_ms"]] = np.asarray([ages[source]], dtype=np.float64)
        enriched[self.cross_modal_skew_key] = np.asarray([skew_ms], dtype=np.float64)
        return enriched, dict(source_timing)


def frame_payloads(frame: Mapping[str, Any]) -> tuple[bytes, bytes]:
    """Bind typed frame content without retaining image bytes in a transaction."""

    def encode(values: Mapping[str, Any]) -> bytes:
        encoded: dict[str, Any] = {}
        for key, value in values.items():
            if isinstance(value, str):
                encoded[key] = ["string", value]
            elif isinstance(value, np.ndarray) and not value.dtype.hasobject:
                encoded[key] = [
                    value.dtype.str,
                    list(value.shape),
                    hashlib.sha256(value.tobytes(order="C")).hexdigest(),
                ]
            else:
                raise ValueError(f"unsupported payload type for {key}")
        return json.dumps(encoded, sort_keys=True, separators=(",", ":")).encode()

    return (
        encode({k: v for k, v in frame.items() if k.startswith("observation.") or k == "task"}),
        encode({"action": frame["action"]}),
    )


class TemporalFrameRecorder(PhysicalTimingValidator):
    """Compatibility facade for the physical LeRobot persistence seam.

    Pre-actuation timing and source identities are frozen; upstream owns the
    observation/label processor pairing. This seam does not attest a successor
    observation or hardware acceptance. Full v4 source admission needs that proof.
    """

    def __init__(
        self,
        dataset: DatasetWriter,
        *,
        feature_sets: Mapping[str, Mapping[str, str]],
        required_sources: tuple[str, ...],
        limits: TemporalLimits,
        accepted_clock_domains: tuple[str, ...],
        cross_modal_skew_key: str = CROSS_MODAL_SKEW_KEY,
    ) -> None:
        super().__init__(
            feature_sets=feature_sets,
            required_sources=required_sources,
            limits=limits,
            accepted_clock_domains=accepted_clock_domains,
            cross_modal_skew_key=cross_modal_skew_key,
        )
        self.dataset = dataset
        expected = temporal_feature_specs(
            self.feature_sets,
            required_sources,
            cross_modal_skew_key=cross_modal_skew_key,
        )
        missing = set(expected) - set(dataset.features)
        if missing:
            raise ValueError(f"dataset is missing temporal features: {sorted(missing)}")

    @classmethod
    def from_resolved_contract(
        cls,
        dataset: DatasetWriter,
        contract: Mapping[str, Any],
        *,
        source_class: str,
        runtime: str = "real",
        limits: TemporalLimits | None = None,
        accepted_clock_domains: tuple[str, ...] = ("host_monotonic",),
    ) -> "TemporalFrameRecorder":
        if runtime != "real":
            raise ValueError(
                "physical LeRobot compatibility facade is real-only; select the Isaac causal profile"
            )
        timing = contract["dataset"]["temporal_semantics"]["source_timing"]
        source_classes = tuple(contract["taxonomy"]["source_classes"])
        if source_class not in source_classes:
            raise ValueError(
                f"unknown source_class {source_class!r}; expected one of {source_classes}"
            )
        group = "human_vr" if source_class == "human_vr" else "automated"
        required_sources = tuple(timing["required_feature_sets_by_source_class"][group])
        return cls(
            dataset,
            feature_sets=timing["feature_sets"],
            required_sources=required_sources,
            limits=limits or TemporalLimits.from_resolved_contract(contract, required_sources),
            accepted_clock_domains=accepted_clock_domains,
            cross_modal_skew_key=timing["cross_modal_skew_feature_key"],
        )

    def add_frame(
        self,
        frame: Mapping[str, Any],
        source_timing: Mapping[str, SourceTiming],
        *,
        selection_timestamp: float,
    ) -> None:
        """Add one accepted frame, or reject it without calling upstream."""

        prepared = self.prepare_frame(source_timing, selection_timestamp=selection_timestamp)
        self.commit_frame(frame, prepared)

    def commit_transaction_frame(
        self,
        frame: Mapping[str, Any],
        causal: CausalTransactionValidator,
        transaction: PreparedTransaction,
    ) -> None:
        """Persist a real prepared pair now; causal completion still needs obs_t+1."""
        if causal.physical is not self or transaction.physical is None:
            raise ValueError("transaction must use this physical recorder")
        obs, action = frame_payloads(frame)
        causal.validate_persistence(transaction, observation_payload=obs, action_payload=action)
        self.commit_frame(frame, transaction.physical)
        causal.mark_persisted(transaction)

    def commit_frame(
        self,
        frame: Mapping[str, Any],
        prepared: PreparedTemporalFrame,
    ) -> None:
        """Persist the dataset frame only if it matches the pre-actuation validation."""

        try:
            if prepared.generation != self._generation or dict(self._last_accepted) != dict(
                prepared.previous
            ):
                self._reject(
                    "prepared_frame_order",
                    "another temporal frame was committed after this bundle was prepared",
                )
            forbidden = {"timestamp", "frame_index"} & set(frame)
            if forbidden:
                self._reject("logical_time_override", f"LeRobot owns {sorted(forbidden)}")
            overlap = set(frame) & set(prepared.enrichment)
            if overlap:
                self._reject(
                    "temporal_metadata_override",
                    f"frame must not provide recorder-owned fields {sorted(overlap)}",
                )
            enriched = {**dict(frame), **dict(prepared.enrichment)}
            self.dataset.add_frame(enriched)
        except TemporalContractViolation as exc:
            self.rejected_frames[exc.reason] += 1
            raise
        self._last_accepted = dict(prepared.accepted)
        self.accepted_frames += 1
        self._generation += 1

"""Canonical renderer, camera, and mutable-visual provenance for offline RGB.

The pure validation and canonicalization functions in this module intentionally
do not import Kit or USD.  Production adapters load those APIs lazily after
``AppLauncher`` has initialized Isaac Sim.

The exported USD digest proves byte identity, but it does not say which renderer
or camera contract must consume that stage.  This document binds those inputs
explicitly.  Mutable visual properties are represented by per-property hashes so
large meshes and texture arrays are not duplicated into the recording manifest.
Replay rebuilds the index from the verified stage and requires an exact match.
"""

from __future__ import annotations

from collections.abc import Callable, Iterable, Mapping, Sequence
import hashlib
import json
import math
from typing import Any


VISUAL_PROVENANCE_SCHEMA = "piper_x_isaac_vr_visual_provenance_v2"
CANONICAL_CAMERA_ROLES = ("left_wrist", "right_wrist", "scene")
TRANSIENT_PRIM_PREFIXES = ("/Render", "/Replicator", "/_xr")

# These settings affect RTX output or the scene submitted to RTX.  Missing
# settings remain explicit entries; an upgrade cannot silently add a new default
# without changing the provenance hash.
RENDERER_SETTING_PATHS = (
    "/app/useFabricSceneDelegate",
    "/renderer/active",
    "/renderer/enabled",
    "/renderer/multiGpu/enabled",
    "/renderer/scenePartitioning/enabled",
    "/rtx/rendermode",
    "/rtx/pathtracing/spp",
    "/rtx/pathtracing/totalSpp",
    "/rtx/post/aa/op",
    "/rtx/post/tonemap/op",
    "/rtx-transient/resourcemanager/texturestreaming/enabled",
)

_VISUAL_PRIM_TYPES = frozenset(
    {
        "BasisCurves",
        "Camera",
        "Capsule",
        "Cone",
        "Cube",
        "Cylinder",
        "GeomSubset",
        "Material",
        "Mesh",
        "Plane",
        "PointInstancer",
        "Points",
        "Shader",
        "Sphere",
    }
)
_VISUAL_ATTRIBUTE_PREFIXES = (
    "camera:",
    "clipping",
    "corner",
    "crease",
    "display",
    "doubleSided",
    "extent",
    "faceVertex",
    "focalLength",
    "focusDistance",
    "fStop",
    "horizontalAperture",
    "inputs:",
    "light:",
    "material:",
    "normals",
    "orientation",
    "outputs:",
    "points",
    "primvars:",
    "projection",
    "purpose",
    "shutter:",
    "subdivisionScheme",
    "verticalAperture",
    "visibility",
    "widths",
    "xformOp:",
    "xformOpOrder",
)
_VISUAL_RELATIONSHIP_PREFIXES = ("material:", "inputs:", "outputs:", "light:")


class VisualProvenanceError(RuntimeError):
    """The renderer or composed visual scene is not reproducibly described."""


def _canonical_value(value: Any) -> Any:
    """Convert a USD/Carb value to strict deterministic JSON data."""

    if value is None or isinstance(value, (str, bool)):
        return value
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        if not math.isfinite(value):
            raise VisualProvenanceError("visual provenance contains a non-finite float")
        # JSON uses the shortest round-trippable representation for Python floats.
        return value
    if isinstance(value, bytes):
        return {"bytes_hex": value.hex()}
    if isinstance(value, Mapping):
        result: dict[str, Any] = {}
        for key, item in value.items():
            if not isinstance(key, str):
                raise VisualProvenanceError("visual provenance mapping keys must be strings")
            result[key] = _canonical_value(item)
        return result
    if isinstance(value, (list, tuple)):
        return [_canonical_value(item) for item in value]
    asset_path = getattr(value, "path", None)
    if isinstance(asset_path, str):
        return {"asset_path": asset_path}
    if hasattr(value, "tolist"):
        return _canonical_value(value.tolist())
    if isinstance(value, Iterable):
        return [_canonical_value(item) for item in value]
    # Tokens, paths, enums, and scalar Gf values all have stable textual forms.
    text = str(value)
    if not text or text.startswith("<"):
        raise VisualProvenanceError(f"unsupported visual provenance value: {value!r}")
    return {"text": text, "python_type": type(value).__name__}


def _canonical_json(value: Any) -> bytes:
    return json.dumps(
        _canonical_value(value),
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    ).encode("utf-8")


def _sha256(value: Any) -> str:
    return hashlib.sha256(_canonical_json(value)).hexdigest()


def _is_transient(path: str) -> bool:
    return any(
        path == prefix or path.startswith(prefix + "/") for prefix in TRANSIENT_PRIM_PREFIXES
    )


def _is_visual_attribute(prim_type: str, name: str) -> bool:
    return (
        prim_type in _VISUAL_PRIM_TYPES
        or prim_type.endswith("Light")
        or name.startswith(_VISUAL_ATTRIBUTE_PREFIXES)
    )


def _is_visual_relationship(prim_type: str, name: str) -> bool:
    return (
        prim_type in {"Material", "Shader", "GeomSubset"}
        or prim_type.endswith("Light")
        or name.startswith(_VISUAL_RELATIONSHIP_PREFIXES)
    )


def _attribute_payload(attribute: Any) -> dict[str, Any]:
    samples = []
    if hasattr(attribute, "GetTimeSamples"):
        for time_code in attribute.GetTimeSamples():
            samples.append(
                {
                    "time": _canonical_value(time_code),
                    "value": _canonical_value(attribute.Get(time_code)),
                }
            )
    payload = {
        "default": _canonical_value(attribute.Get()),
        "time_samples": samples,
        "type_name": str(attribute.GetTypeName()) if hasattr(attribute, "GetTypeName") else "",
    }
    return payload


def _property_index(stage: Any) -> list[dict[str, Any]]:
    properties: list[dict[str, Any]] = []
    try:
        prims = list(stage.Traverse())
    except Exception as exc:
        raise VisualProvenanceError("could not traverse the composed USD stage") from exc
    for prim in sorted(prims, key=lambda item: str(item.GetPath())):
        path = str(prim.GetPath())
        if not path.startswith("/"):
            raise VisualProvenanceError(f"non-absolute prim path in visual stage: {path!r}")
        if _is_transient(path):
            continue
        prim_type = str(prim.GetTypeName())
        for attribute in sorted(prim.GetAttributes(), key=lambda item: str(item.GetName())):
            name = str(attribute.GetName())
            if not _is_visual_attribute(prim_type, name):
                continue
            payload = _attribute_payload(attribute)
            properties.append(
                {
                    "kind": "attribute",
                    "name": name,
                    "payload_sha256": _sha256(payload),
                    "prim_path": path,
                    "prim_type": prim_type,
                }
            )
        for relationship in sorted(prim.GetRelationships(), key=lambda item: str(item.GetName())):
            name = str(relationship.GetName())
            if not _is_visual_relationship(prim_type, name):
                continue
            targets = sorted(str(target) for target in relationship.GetTargets())
            properties.append(
                {
                    "kind": "relationship",
                    "name": name,
                    "payload_sha256": _sha256({"targets": targets}),
                    "prim_path": path,
                    "prim_type": prim_type,
                }
            )
    identities = [(item["prim_path"], item["kind"], item["name"]) for item in properties]
    if len(identities) != len(set(identities)):
        raise VisualProvenanceError("composed visual stage contains duplicate property identities")
    return properties


def _camera_entry(stage: Any, role: str, spec: Mapping[str, Any]) -> dict[str, Any]:
    path = spec.get("prim_path")
    resolution = spec.get("resolution")
    if not isinstance(path, str) or not path.startswith("/") or "//" in path:
        raise VisualProvenanceError(f"camera {role} has an invalid absolute prim path")
    if (
        not isinstance(resolution, Sequence)
        or isinstance(resolution, (str, bytes))
        or len(resolution) != 2
        or any(type(value) is not int or value <= 0 for value in resolution)
    ):
        raise VisualProvenanceError(f"camera {role} has an invalid resolution")
    prim = stage.GetPrimAtPath(path)
    if prim is None or (hasattr(prim, "IsValid") and not prim.IsValid()):
        raise VisualProvenanceError(f"camera {role} prim is missing: {path}")
    if str(prim.GetTypeName()) != "Camera":
        raise VisualProvenanceError(f"camera {role} prim is not a USD Camera: {path}")
    attributes = []
    for attribute in sorted(prim.GetAttributes(), key=lambda item: str(item.GetName())):
        payload = _attribute_payload(attribute)
        attributes.append(
            {
                "name": str(attribute.GetName()),
                "payload": payload,
                "payload_sha256": _sha256(payload),
            }
        )
    if not attributes:
        raise VisualProvenanceError(f"camera {role} has no composed attributes: {path}")
    entry = {
        "attributes": attributes,
        "data_type": str(spec.get("data_type", "rgb")),
        "prim_path": path,
        "prim_type": "Camera",
        "resolution": [int(resolution[0]), int(resolution[1])],
        "role": role,
    }
    entry["camera_configuration_sha256"] = _sha256(entry)
    return entry


def _kit_runtime_identity() -> dict[str, Any]:
    try:
        import omni.kit.app
    except ImportError as exc:  # pragma: no cover - requires initialized Isaac environment
        raise VisualProvenanceError("Kit is unavailable while capturing visual provenance") from exc
    app = omni.kit.app.get_app()
    identity: dict[str, Any] = {}
    for name in ("get_version", "get_build_version"):
        method = getattr(app, name, None)
        identity[name.removeprefix("get_")] = str(method()) if callable(method) else None
    return identity


def _kit_setting_reader(path: str) -> Any:
    try:
        import carb.settings
    except ImportError as exc:  # pragma: no cover - requires initialized Isaac environment
        raise VisualProvenanceError("Carb settings are unavailable") from exc
    settings = carb.settings.get_settings()
    try:
        type_code = int(settings.get_type(path))
    except Exception:
        type_code = None
    try:
        value = settings.get(path)
    except Exception as exc:
        raise VisualProvenanceError(f"could not read renderer setting {path}") from exc
    return {"present": value is not None, "type_code": type_code, "value": value}


def build_visual_provenance(
    stage: Any,
    camera_specs: Mapping[str, Mapping[str, Any]],
    *,
    setting_reader: Callable[[str], Any] | None = None,
    runtime_identity: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Build a deterministic semantic index for all offline-RGB inputs."""

    if set(camera_specs) != set(CANONICAL_CAMERA_ROLES):
        raise VisualProvenanceError(
            f"camera specs must contain exactly {list(CANONICAL_CAMERA_ROLES)}"
        )
    reader = setting_reader or _kit_setting_reader
    settings = [
        {"path": path, "state": _canonical_value(reader(path))} for path in RENDERER_SETTING_PATHS
    ]
    cameras = [_camera_entry(stage, role, camera_specs[role]) for role in CANONICAL_CAMERA_ROLES]
    if len({camera["prim_path"] for camera in cameras}) != len(cameras):
        raise VisualProvenanceError("canonical camera roles must use unique prim paths")
    properties = _property_index(stage)
    renderer = {
        "implementation": "RTX",
        "runtime_identity": _canonical_value(runtime_identity or _kit_runtime_identity()),
        "settings": settings,
        "settings_policy": "piper_x_rtx_settings_v1",
    }
    renderer["renderer_configuration_sha256"] = _sha256(renderer)
    document: dict[str, Any] = {
        "camera_roles": cameras,
        "materialization": {
            "annotator": "rgb",
            "capture_driver": "kit_app_update",
            "camera_role_order": list(CANONICAL_CAMERA_ROLES),
            "materialization_revision": "piper_x_offline_rgb_materializer_v1",
            "orchestrator_reference_time_gate": False,
            "render_product_lifecycle": "persistent_per_role",
            "render_updates_per_frame": 4,
            "warmup_updates": 3,
        },
        "mutable_visual_state": {
            "excluded_transient_prefixes": list(TRANSIENT_PRIM_PREFIXES),
            "property_count": len(properties),
            "properties": properties,
        },
        "renderer": renderer,
        "schema": VISUAL_PROVENANCE_SCHEMA,
    }
    document["visual_provenance_sha256"] = _sha256(document)
    verify_visual_provenance(document)
    return document


def verify_visual_provenance(document: Mapping[str, Any]) -> dict[str, Any]:
    """Verify the document's structure and self-hash without importing Kit."""

    if not isinstance(document, Mapping) or document.get("schema") != VISUAL_PROVENANCE_SCHEMA:
        raise VisualProvenanceError("unsupported visual provenance schema")
    digest = document.get("visual_provenance_sha256")
    if not isinstance(digest, str) or len(digest) != 64:
        raise VisualProvenanceError("visual provenance requires a SHA-256 self-hash")
    unsigned = dict(document)
    unsigned.pop("visual_provenance_sha256", None)
    actual = _sha256(unsigned)
    if digest != actual:
        raise VisualProvenanceError(
            f"visual provenance self-hash mismatch: expected {digest}, got {actual}"
        )
    cameras = document.get("camera_roles")
    if not isinstance(cameras, list) or [item.get("role") for item in cameras] != list(
        CANONICAL_CAMERA_ROLES
    ):
        raise VisualProvenanceError("visual provenance camera role order is invalid")
    paths = [item.get("prim_path") for item in cameras]
    if any(not isinstance(path, str) or not path.startswith("/") for path in paths):
        raise VisualProvenanceError("visual provenance has an invalid camera path")
    if len(paths) != len(set(paths)):
        raise VisualProvenanceError("visual provenance camera paths are not unique")
    for camera in cameras:
        camera_digest = camera.get("camera_configuration_sha256")
        if not isinstance(camera_digest, str) or len(camera_digest) != 64:
            raise VisualProvenanceError("visual provenance camera has no configuration hash")
        unsigned_camera = dict(camera)
        unsigned_camera.pop("camera_configuration_sha256", None)
        if camera_digest != _sha256(unsigned_camera):
            raise VisualProvenanceError("visual provenance camera configuration hash mismatch")
    renderer = document.get("renderer")
    settings = renderer.get("settings") if isinstance(renderer, Mapping) else None
    if not isinstance(settings, list) or [entry.get("path") for entry in settings] != list(
        RENDERER_SETTING_PATHS
    ):
        raise VisualProvenanceError("visual provenance renderer settings policy is incomplete")
    renderer_digest = renderer.get("renderer_configuration_sha256")
    if not isinstance(renderer_digest, str) or len(renderer_digest) != 64:
        raise VisualProvenanceError("visual provenance renderer has no configuration hash")
    unsigned_renderer = dict(renderer)
    unsigned_renderer.pop("renderer_configuration_sha256", None)
    if renderer_digest != _sha256(unsigned_renderer):
        raise VisualProvenanceError("visual provenance renderer configuration hash mismatch")
    materialization = document.get("materialization")
    if (
        not isinstance(materialization, Mapping)
        or materialization.get("materialization_revision") != "piper_x_offline_rgb_materializer_v1"
    ):
        raise VisualProvenanceError("visual provenance materialization revision is invalid")
    visuals = document.get("mutable_visual_state")
    if not isinstance(visuals, Mapping):
        raise VisualProvenanceError("visual provenance mutable state is invalid")
    properties = visuals.get("properties")
    if not isinstance(properties, list) or visuals.get("property_count") != len(properties):
        raise VisualProvenanceError("visual provenance property index count is invalid")
    identities = []
    for item in properties:
        if not isinstance(item, Mapping):
            raise VisualProvenanceError("visual provenance property entry is not an object")
        identities.append((item.get("prim_path"), item.get("kind"), item.get("name")))
        property_digest = item.get("payload_sha256")
        if not isinstance(property_digest, str) or len(property_digest) != 64:
            raise VisualProvenanceError("visual provenance property has no SHA-256 digest")
    if identities != sorted(identities) or len(identities) != len(set(identities)):
        raise VisualProvenanceError("visual provenance properties are not canonical and unique")
    return dict(document)


def assert_visual_provenance_matches(
    recorded: Mapping[str, Any],
    stage: Any,
    *,
    setting_reader: Callable[[str], Any] | None = None,
    runtime_identity: Mapping[str, Any] | None = None,
) -> None:
    """Rebuild provenance from a replay stage and require exact equivalence."""

    verified = verify_visual_provenance(recorded)
    camera_specs = {
        str(entry["role"]): {
            "data_type": entry["data_type"],
            "prim_path": entry["prim_path"],
            "resolution": entry["resolution"],
        }
        for entry in verified["camera_roles"]
    }
    rebuilt = build_visual_provenance(
        stage,
        camera_specs,
        setting_reader=setting_reader,
        runtime_identity=runtime_identity,
    )
    if rebuilt["visual_provenance_sha256"] != verified["visual_provenance_sha256"]:
        mismatches: list[str] = []
        for section in ("camera_roles", "materialization", "renderer"):
            if rebuilt[section] != verified[section]:
                mismatches.append(
                    f"{section}: recorded={_sha256(verified[section])} "
                    f"replayed={_sha256(rebuilt[section])}"
                )
        recorded_visuals = verified["mutable_visual_state"]
        replayed_visuals = rebuilt["mutable_visual_state"]
        if recorded_visuals != replayed_visuals:
            recorded_properties = {
                (item["prim_path"], item["kind"], item["name"]): item["payload_sha256"]
                for item in recorded_visuals["properties"]
            }
            replayed_properties = {
                (item["prim_path"], item["kind"], item["name"]): item["payload_sha256"]
                for item in replayed_visuals["properties"]
            }
            changed = sorted(
                key
                for key in set(recorded_properties) | set(replayed_properties)
                if recorded_properties.get(key) != replayed_properties.get(key)
            )
            mismatches.append(
                "mutable_visual_state: "
                f"recorded={_sha256(recorded_visuals)} replayed={_sha256(replayed_visuals)}; "
                f"changed_properties={changed[:8]!r}"
            )
        raise VisualProvenanceError(
            "opened replay stage, cameras, or RTX runtime do not match recording provenance; "
            + "; ".join(mismatches)
        )
